window.BOOK = {"meta": {"edition": "open-source", "dataSource": "chinese-poetry/chinese-poetry", "sourceUrl": "https://github.com/chinese-poetry/chinese-poetry/blob/master/诗经/shijing.json", "sourceSha256": "3c7ca54d59424542ada99adfcc85420287fbbd5c8a511e9baf705cb2b04051e7", "dataLicense": "MIT", "hasSourcePDF": false, "sourcePageCount": 0, "hasSourceOCR": false, "notice": "公开版收录 305 篇古典诗文及少量自行编写的示例注释，未附商业书籍扫描、现代题解及注析全文。"}, "poems": [{"id": "p001", "title": "关雎", "section": "国风", "group": "周南", "intro": "《关雎》收于《诗经·国风·周南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "关关雎鸠，在河之洲。窈窕淑女，君子好逑。", "sentences": ["关关雎鸠，在河之洲。", "窈窕淑女，君子好逑。"], "notes": "以下为本项目编写的简短示例，并非原书注释。\n\n关关：描写鸟鸣声。\n雎鸠：诗中出现的鸟名。\n洲：水中的陆地。\n窈窕：形容女子美好。\n逑：配偶。", "page": null}, {"text": "参差荇菜，左右流之。窈窕淑女，寤寐求之。", "sentences": ["参差荇菜，左右流之。", "窈窕淑女，寤寐求之。"], "notes": "", "page": null}, {"text": "求之不得，寤寐思服。悠哉悠哉，辗转反侧。", "sentences": ["求之不得，寤寐思服。", "悠哉悠哉，辗转反侧。"], "notes": "", "page": null}, {"text": "参差荇菜，左右采之。窈窕淑女，琴瑟友之。", "sentences": ["参差荇菜，左右采之。", "窈窕淑女，琴瑟友之。"], "notes": "", "page": null}, {"text": "参差荇菜，左右芼之。窈窕淑女，钟鼓乐之。", "sentences": ["参差荇菜，左右芼之。", "窈窕淑女，钟鼓乐之。"], "notes": "", "page": null}]}, {"id": "p002", "title": "葛覃", "section": "国风", "group": "周南", "intro": "《葛覃》收于《诗经·国风·周南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "葛之覃兮，施于中谷，维叶萋萋。黄鸟于飞，集于灌木，其鸣喈喈。", "sentences": ["葛之覃兮，施于中谷，维叶萋萋。", "黄鸟于飞，集于灌木，其鸣喈喈。"], "notes": "", "page": null}, {"text": "葛之覃兮，施于中谷，维叶莫莫。是刈是濩，为絺为绤，服之无斁。", "sentences": ["葛之覃兮，施于中谷，维叶莫莫。", "是刈是濩，为絺为绤，服之无斁。"], "notes": "", "page": null}, {"text": "言告师氏，言告言归。薄污我私，薄浣我衣。害浣害否，归宁父母。", "sentences": ["言告师氏，言告言归。", "薄污我私，薄浣我衣。", "害浣害否，归宁父母。"], "notes": "", "page": null}]}, {"id": "p003", "title": "卷耳", "section": "国风", "group": "周南", "intro": "《卷耳》收于《诗经·国风·周南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "采采卷耳，不盈顷筐。嗟我怀人，置彼周行。", "sentences": ["采采卷耳，不盈顷筐。", "嗟我怀人，置彼周行。"], "notes": "", "page": null}, {"text": "陟彼崔嵬，我马虺隤。我姑酌彼金罍，维以不永怀。", "sentences": ["陟彼崔嵬，我马虺隤。", "我姑酌彼金罍，维以不永怀。"], "notes": "", "page": null}, {"text": "陟彼高冈，我马玄黄。我姑酌彼兕觥，维以不永伤。", "sentences": ["陟彼高冈，我马玄黄。", "我姑酌彼兕觥，维以不永伤。"], "notes": "", "page": null}, {"text": "陟彼砠矣，我马瘏矣，我仆痡矣，云何吁矣。", "sentences": ["陟彼砠矣，我马瘏矣，我仆痡矣，云何吁矣。"], "notes": "", "page": null}]}, {"id": "p004", "title": "樛木", "section": "国风", "group": "周南", "intro": "《樛木》收于《诗经·国风·周南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "南有樛木，葛藟累之。乐只君子，福履绥之。", "sentences": ["南有樛木，葛藟累之。", "乐只君子，福履绥之。"], "notes": "", "page": null}, {"text": "南有樛木，葛藟荒之。乐只君子，福履将之。", "sentences": ["南有樛木，葛藟荒之。", "乐只君子，福履将之。"], "notes": "", "page": null}, {"text": "南有樛木，葛藟萦之。乐只君子，福履成之。", "sentences": ["南有樛木，葛藟萦之。", "乐只君子，福履成之。"], "notes": "", "page": null}]}, {"id": "p005", "title": "螽斯", "section": "国风", "group": "周南", "intro": "《螽斯》收于《诗经·国风·周南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "螽斯羽，诜诜兮。宜尔子孙，振振兮。", "sentences": ["螽斯羽，诜诜兮。", "宜尔子孙，振振兮。"], "notes": "", "page": null}, {"text": "螽斯羽，薨薨兮。宜尔子孙。绳绳兮。", "sentences": ["螽斯羽，薨薨兮。", "宜尔子孙。", "绳绳兮。"], "notes": "", "page": null}, {"text": "螽斯羽，揖揖兮。宜尔子孙，蛰蛰兮。", "sentences": ["螽斯羽，揖揖兮。", "宜尔子孙，蛰蛰兮。"], "notes": "", "page": null}]}, {"id": "p006", "title": "桃夭", "section": "国风", "group": "周南", "intro": "《桃夭》收于《诗经·国风·周南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "桃之夭夭，灼灼其华。之子于归，宜其室家。", "sentences": ["桃之夭夭，灼灼其华。", "之子于归，宜其室家。"], "notes": "", "page": null}, {"text": "桃之夭夭，有蕡其实。之子于归，宜其家室。", "sentences": ["桃之夭夭，有蕡其实。", "之子于归，宜其家室。"], "notes": "", "page": null}, {"text": "桃之夭夭，其叶蓁蓁。之子于归，宜其家人。", "sentences": ["桃之夭夭，其叶蓁蓁。", "之子于归，宜其家人。"], "notes": "", "page": null}]}, {"id": "p007", "title": "兔罝", "section": "国风", "group": "周南", "intro": "《兔罝》收于《诗经·国风·周南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "肃肃兔罝，椓之丁丁。赳赳武夫，公侯干城。", "sentences": ["肃肃兔罝，椓之丁丁。", "赳赳武夫，公侯干城。"], "notes": "", "page": null}, {"text": "肃肃兔罝，施于中逵。赳赳武夫，公侯好仇。", "sentences": ["肃肃兔罝，施于中逵。", "赳赳武夫，公侯好仇。"], "notes": "", "page": null}, {"text": "肃肃免罝，施于中林。赳赳武夫，公侯腹心。", "sentences": ["肃肃免罝，施于中林。", "赳赳武夫，公侯腹心。"], "notes": "", "page": null}]}, {"id": "p008", "title": "芣苡", "section": "国风", "group": "周南", "intro": "《芣苡》收于《诗经·国风·周南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "采采芣苡，薄言采之。采采芣苡，薄言有之。", "sentences": ["采采芣苡，薄言采之。", "采采芣苡，薄言有之。"], "notes": "", "page": null}, {"text": "采采芣苡，薄言掇之。采采芣苡，薄言捋之。", "sentences": ["采采芣苡，薄言掇之。", "采采芣苡，薄言捋之。"], "notes": "", "page": null}, {"text": "采采芣苡，薄言袺之。采采芣苡，薄言襭之。", "sentences": ["采采芣苡，薄言袺之。", "采采芣苡，薄言襭之。"], "notes": "", "page": null}]}, {"id": "p009", "title": "汉广", "section": "国风", "group": "周南", "intro": "《汉广》收于《诗经·国风·周南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "南有乔木，不可休息。汉有游女，不可求思。汉之广矣，不可泳思。江之永矣，不可方思。", "sentences": ["南有乔木，不可休息。", "汉有游女，不可求思。", "汉之广矣，不可泳思。", "江之永矣，不可方思。"], "notes": "", "page": null}, {"text": "翘翘错薪，言刈其楚。之子于归，言秣其马。汉之广矣，不可泳思。江之永矣，不可方思。", "sentences": ["翘翘错薪，言刈其楚。", "之子于归，言秣其马。", "汉之广矣，不可泳思。", "江之永矣，不可方思。"], "notes": "", "page": null}, {"text": "翘翘错薪，言刈其蒌。之子于归。言秣其驹。汉之广矣，不可泳思。江之永矣，不可方思。", "sentences": ["翘翘错薪，言刈其蒌。", "之子于归。", "言秣其驹。", "汉之广矣，不可泳思。", "江之永矣，不可方思。"], "notes": "", "page": null}]}, {"id": "p010", "title": "汝坟", "section": "国风", "group": "周南", "intro": "《汝坟》收于《诗经·国风·周南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "遵彼汝坟，伐其条枚。未见君子，惄如调饥。", "sentences": ["遵彼汝坟，伐其条枚。", "未见君子，惄如调饥。"], "notes": "", "page": null}, {"text": "遵彼汝坟，伐其条肄。既见君子，不我遐弃。", "sentences": ["遵彼汝坟，伐其条肄。", "既见君子，不我遐弃。"], "notes": "", "page": null}, {"text": "鲂鱼赪尾，王室如毁。虽则如毁，父母孔迩。", "sentences": ["鲂鱼赪尾，王室如毁。", "虽则如毁，父母孔迩。"], "notes": "", "page": null}]}, {"id": "p011", "title": "麟之趾", "section": "国风", "group": "周南", "intro": "《麟之趾》收于《诗经·国风·周南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "麟之趾，振振公子，于嗟麟兮。", "sentences": ["麟之趾，振振公子，于嗟麟兮。"], "notes": "", "page": null}, {"text": "麟之定，振振公姓，于嗟麟兮。", "sentences": ["麟之定，振振公姓，于嗟麟兮。"], "notes": "", "page": null}, {"text": "麟之角，振振公族，于嗟麟兮。", "sentences": ["麟之角，振振公族，于嗟麟兮。"], "notes": "", "page": null}]}, {"id": "p012", "title": "鹊巢", "section": "国风", "group": "召南", "intro": "《鹊巢》收于《诗经·国风·召南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "维鹊有巢，维鸠居之。之子于归，百两御之。", "sentences": ["维鹊有巢，维鸠居之。", "之子于归，百两御之。"], "notes": "", "page": null}, {"text": "维鹊有巢，维鸠方之。之子于归，百两将之。", "sentences": ["维鹊有巢，维鸠方之。", "之子于归，百两将之。"], "notes": "", "page": null}, {"text": "维鹊有巢，维鸠盈之。之子于归，百两成之。", "sentences": ["维鹊有巢，维鸠盈之。", "之子于归，百两成之。"], "notes": "", "page": null}]}, {"id": "p013", "title": "采蘩", "section": "国风", "group": "召南", "intro": "《采蘩》收于《诗经·国风·召南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "于以采蘩？于沼于沚。于以用之？公侯之事。", "sentences": ["于以采蘩？", "于沼于沚。", "于以用之？", "公侯之事。"], "notes": "", "page": null}, {"text": "于以采蘩？于涧之中。于以用之？公侯之宫。", "sentences": ["于以采蘩？", "于涧之中。", "于以用之？", "公侯之宫。"], "notes": "", "page": null}, {"text": "被之僮僮，夙夜在公。被之祁祁，薄言还归。", "sentences": ["被之僮僮，夙夜在公。", "被之祁祁，薄言还归。"], "notes": "", "page": null}]}, {"id": "p014", "title": "草虫", "section": "国风", "group": "召南", "intro": "《草虫》收于《诗经·国风·召南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "喓喓草虫，趯趯阜螽。未见君子，忧心忡忡。亦既见止，亦既觏止，我心则降。", "sentences": ["喓喓草虫，趯趯阜螽。", "未见君子，忧心忡忡。", "亦既见止，亦既觏止，我心则降。"], "notes": "", "page": null}, {"text": "陟彼南山，言采其蕨。未见君子，忧心惙惙。亦既见止，亦既觏止，我心则说。", "sentences": ["陟彼南山，言采其蕨。", "未见君子，忧心惙惙。", "亦既见止，亦既觏止，我心则说。"], "notes": "", "page": null}, {"text": "陟彼南山，言采其薇。未见君子，我心伤悲。亦既见止，亦既觏止，我心则夷。", "sentences": ["陟彼南山，言采其薇。", "未见君子，我心伤悲。", "亦既见止，亦既觏止，我心则夷。"], "notes": "", "page": null}]}, {"id": "p015", "title": "采蘋", "section": "国风", "group": "召南", "intro": "《采蘋》收于《诗经·国风·召南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "于以采蘋？南涧之滨。于以采藻？于彼行潦。", "sentences": ["于以采蘋？", "南涧之滨。", "于以采藻？", "于彼行潦。"], "notes": "", "page": null}, {"text": "于以盛之？维筐及筥。于以湘之？维锜及釜。", "sentences": ["于以盛之？", "维筐及筥。", "于以湘之？", "维锜及釜。"], "notes": "", "page": null}, {"text": "于以奠之？宗室牖下。谁其尸之？有齐季女。", "sentences": ["于以奠之？", "宗室牖下。", "谁其尸之？", "有齐季女。"], "notes": "", "page": null}]}, {"id": "p016", "title": "甘棠", "section": "国风", "group": "召南", "intro": "《甘棠》收于《诗经·国风·召南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "蔽芾甘棠，勿翦勿伐，召伯所茇。", "sentences": ["蔽芾甘棠，勿翦勿伐，召伯所茇。"], "notes": "", "page": null}, {"text": "蔽芾甘棠，勿翦勿败，召伯所憩。", "sentences": ["蔽芾甘棠，勿翦勿败，召伯所憩。"], "notes": "", "page": null}, {"text": "蔽芾甘棠，勿翦勿拜，召伯所说。", "sentences": ["蔽芾甘棠，勿翦勿拜，召伯所说。"], "notes": "", "page": null}]}, {"id": "p017", "title": "行露", "section": "国风", "group": "召南", "intro": "《行露》收于《诗经·国风·召南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "厌浥行露，岂不夙夜，谓行多露。", "sentences": ["厌浥行露，岂不夙夜，谓行多露。"], "notes": "", "page": null}, {"text": "谁谓雀无角？何以穿我屋？谁谓女无家？何以速我狱？虽速我狱，室家不足！", "sentences": ["谁谓雀无角？", "何以穿我屋？", "谁谓女无家？", "何以速我狱？", "虽速我狱，室家不足！"], "notes": "", "page": null}, {"text": "谁谓鼠无牙？何以穿我墉？谁谓女无家？何以速我讼？虽速我讼，亦不女从！", "sentences": ["谁谓鼠无牙？", "何以穿我墉？", "谁谓女无家？", "何以速我讼？", "虽速我讼，亦不女从！"], "notes": "", "page": null}]}, {"id": "p018", "title": "羔羊", "section": "国风", "group": "召南", "intro": "《羔羊》收于《诗经·国风·召南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "羔羊之皮，素丝五紽。退食自公，委蛇委蛇。", "sentences": ["羔羊之皮，素丝五紽。", "退食自公，委蛇委蛇。"], "notes": "", "page": null}, {"text": "羔羊之革，素丝五緎。委蛇委蛇，自公退食。", "sentences": ["羔羊之革，素丝五緎。", "委蛇委蛇，自公退食。"], "notes": "", "page": null}, {"text": "羔羊之缝，素丝五总。委蛇委蛇，退食自公。", "sentences": ["羔羊之缝，素丝五总。", "委蛇委蛇，退食自公。"], "notes": "", "page": null}]}, {"id": "p019", "title": "殷其雷", "section": "国风", "group": "召南", "intro": "《殷其雷》收于《诗经·国风·召南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "殷其雷，在南山之阳。何斯违斯，莫敢或遑？振振君子，归哉归哉！", "sentences": ["殷其雷，在南山之阳。", "何斯违斯，莫敢或遑？", "振振君子，归哉归哉！"], "notes": "", "page": null}, {"text": "殷其雷，在南山之侧。何斯违斯，莫敢遑息？振振君子，归哉归哉！", "sentences": ["殷其雷，在南山之侧。", "何斯违斯，莫敢遑息？", "振振君子，归哉归哉！"], "notes": "", "page": null}, {"text": "殷其雷，在南山之下。何斯违斯，莫或遑处？振振君子，归哉归哉！", "sentences": ["殷其雷，在南山之下。", "何斯违斯，莫或遑处？", "振振君子，归哉归哉！"], "notes": "", "page": null}]}, {"id": "p020", "title": "摽有梅", "section": "国风", "group": "召南", "intro": "《摽有梅》收于《诗经·国风·召南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "摽有梅，其实七兮。求我庶士，迨其吉兮。", "sentences": ["摽有梅，其实七兮。", "求我庶士，迨其吉兮。"], "notes": "", "page": null}, {"text": "摽有梅，其实三兮。求我庶士，迨其今兮。", "sentences": ["摽有梅，其实三兮。", "求我庶士，迨其今兮。"], "notes": "", "page": null}, {"text": "摽有梅，顷筐塈之。求我庶士，迨其谓之。", "sentences": ["摽有梅，顷筐塈之。", "求我庶士，迨其谓之。"], "notes": "", "page": null}]}, {"id": "p021", "title": "小星", "section": "国风", "group": "召南", "intro": "《小星》收于《诗经·国风·召南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "嘒彼小星，三五在东。肃肃宵征，夙夜在公。寔命不同！", "sentences": ["嘒彼小星，三五在东。", "肃肃宵征，夙夜在公。", "寔命不同！"], "notes": "", "page": null}, {"text": "嘒彼小星，维参与昴。肃肃宵征，抱衾与裯。寔命不犹！", "sentences": ["嘒彼小星，维参与昴。", "肃肃宵征，抱衾与裯。", "寔命不犹！"], "notes": "", "page": null}]}, {"id": "p022", "title": "江有汜", "section": "国风", "group": "召南", "intro": "《江有汜》收于《诗经·国风·召南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "江有汜，之子归，不我以。不我以，其后也悔。", "sentences": ["江有汜，之子归，不我以。", "不我以，其后也悔。"], "notes": "", "page": null}, {"text": "江有渚，之子归，不我与。不我与，其后也处。", "sentences": ["江有渚，之子归，不我与。", "不我与，其后也处。"], "notes": "", "page": null}, {"text": "江有沱，之子归，不我过。不我过，其啸也歌。", "sentences": ["江有沱，之子归，不我过。", "不我过，其啸也歌。"], "notes": "", "page": null}]}, {"id": "p023", "title": "野有死麕", "section": "国风", "group": "召南", "intro": "《野有死麕》收于《诗经·国风·召南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "野有死麕，白茅包之。有女怀春，吉士诱之。", "sentences": ["野有死麕，白茅包之。", "有女怀春，吉士诱之。"], "notes": "", "page": null}, {"text": "林有朴樕，野有死鹿。白茅纯束，有女如玉。", "sentences": ["林有朴樕，野有死鹿。", "白茅纯束，有女如玉。"], "notes": "", "page": null}, {"text": "舒而脱脱兮，无感我帨兮，无使尨也吠。", "sentences": ["舒而脱脱兮，无感我帨兮，无使尨也吠。"], "notes": "", "page": null}]}, {"id": "p024", "title": "何彼襛矣", "section": "国风", "group": "召南", "intro": "《何彼襛矣》收于《诗经·国风·召南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "何彼襛矣，唐棣之华？曷不肃雍？王姬之车。", "sentences": ["何彼襛矣，唐棣之华？", "曷不肃雍？", "王姬之车。"], "notes": "", "page": null}, {"text": "何彼襛矣，华如桃李？平王之孙，齐侯之子。", "sentences": ["何彼襛矣，华如桃李？", "平王之孙，齐侯之子。"], "notes": "", "page": null}, {"text": "其钓维何？维丝伊缗。齐侯之子，平王之孙。", "sentences": ["其钓维何？", "维丝伊缗。", "齐侯之子，平王之孙。"], "notes": "", "page": null}]}, {"id": "p025", "title": "驺虞", "section": "国风", "group": "召南", "intro": "《驺虞》收于《诗经·国风·召南》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "彼茁者葭，壹发五豝，于嗟乎驺虞！", "sentences": ["彼茁者葭，壹发五豝，于嗟乎驺虞！"], "notes": "", "page": null}, {"text": "彼茁者蓬，壹发五豵，于嗟乎驺虞！", "sentences": ["彼茁者蓬，壹发五豵，于嗟乎驺虞！"], "notes": "", "page": null}]}, {"id": "p026", "title": "柏舟", "section": "国风", "group": "邶风", "intro": "《柏舟》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "泛彼柏舟，亦泛其流。耿耿不寐，如有隐忧。微我无酒，以敖以游。", "sentences": ["泛彼柏舟，亦泛其流。", "耿耿不寐，如有隐忧。", "微我无酒，以敖以游。"], "notes": "", "page": null}, {"text": "我心匪鉴，不可以茹。亦有兄弟，不可以据。薄言往诉，逢彼之怒。", "sentences": ["我心匪鉴，不可以茹。", "亦有兄弟，不可以据。", "薄言往诉，逢彼之怒。"], "notes": "", "page": null}, {"text": "我心匪石，不可转也。我心匪席，不可卷也。威仪棣棣，不可选也。", "sentences": ["我心匪石，不可转也。", "我心匪席，不可卷也。", "威仪棣棣，不可选也。"], "notes": "", "page": null}, {"text": "忧心悄悄，愠于群小。觏闵既多，受侮不少。静言思之，寤辟有摽。", "sentences": ["忧心悄悄，愠于群小。", "觏闵既多，受侮不少。", "静言思之，寤辟有摽。"], "notes": "", "page": null}, {"text": "日居月诸，胡迭而微？心之忧矣，如匪浣衣。静言思之，不能奋飞。", "sentences": ["日居月诸，胡迭而微？", "心之忧矣，如匪浣衣。", "静言思之，不能奋飞。"], "notes": "", "page": null}]}, {"id": "p027", "title": "绿衣", "section": "国风", "group": "邶风", "intro": "《绿衣》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "绿兮衣兮，绿衣黄裹。心之忧矣，曷维其已！", "sentences": ["绿兮衣兮，绿衣黄裹。", "心之忧矣，曷维其已！"], "notes": "", "page": null}, {"text": "绿兮衣兮，绿衣黄裳。心之忧矣，曷维其亡！", "sentences": ["绿兮衣兮，绿衣黄裳。", "心之忧矣，曷维其亡！"], "notes": "", "page": null}, {"text": "绿兮丝兮，女所治兮。我思古人，俾无訧兮！", "sentences": ["绿兮丝兮，女所治兮。", "我思古人，俾无訧兮！"], "notes": "", "page": null}, {"text": "絺兮绤兮，凄其以风。我思古人，实获我心！", "sentences": ["絺兮绤兮，凄其以风。", "我思古人，实获我心！"], "notes": "", "page": null}]}, {"id": "p028", "title": "燕燕", "section": "国风", "group": "邶风", "intro": "《燕燕》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "燕燕于飞，差池其羽。之子于归，远送于野。瞻望弗及，泣涕如雨。", "sentences": ["燕燕于飞，差池其羽。", "之子于归，远送于野。", "瞻望弗及，泣涕如雨。"], "notes": "", "page": null}, {"text": "燕燕于飞，颉之颃之。之子于归，远于将之。瞻望弗及，伫立以泣。", "sentences": ["燕燕于飞，颉之颃之。", "之子于归，远于将之。", "瞻望弗及，伫立以泣。"], "notes": "", "page": null}, {"text": "燕燕于飞，下上其音。之子于归，远送于南。瞻望弗及，实劳我心。", "sentences": ["燕燕于飞，下上其音。", "之子于归，远送于南。", "瞻望弗及，实劳我心。"], "notes": "", "page": null}, {"text": "仲氏任只，其心塞渊。终温且惠，淑慎其身。先君之思，以勖寡人。", "sentences": ["仲氏任只，其心塞渊。", "终温且惠，淑慎其身。", "先君之思，以勖寡人。"], "notes": "", "page": null}]}, {"id": "p029", "title": "日月", "section": "国风", "group": "邶风", "intro": "《日月》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "日居月诸，照临下土。乃如之人兮，逝不古处？胡能有定？宁不我顾。", "sentences": ["日居月诸，照临下土。", "乃如之人兮，逝不古处？", "胡能有定？", "宁不我顾。"], "notes": "", "page": null}, {"text": "日居月诸，下土是冒。乃如之人兮，逝不相好。胡能有定？宁不我报。", "sentences": ["日居月诸，下土是冒。", "乃如之人兮，逝不相好。", "胡能有定？", "宁不我报。"], "notes": "", "page": null}, {"text": "日居月诸，出自东方。乃如之人兮，德音无良。胡能有定？俾也可忘。", "sentences": ["日居月诸，出自东方。", "乃如之人兮，德音无良。", "胡能有定？", "俾也可忘。"], "notes": "", "page": null}, {"text": "日居月诸，东方自出。父兮母兮，畜我不卒。胡能有定？报我不述。", "sentences": ["日居月诸，东方自出。", "父兮母兮，畜我不卒。", "胡能有定？", "报我不述。"], "notes": "", "page": null}]}, {"id": "p030", "title": "终风", "section": "国风", "group": "邶风", "intro": "《终风》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "终风且暴，顾我则笑，谑浪笑敖，中心是悼。", "sentences": ["终风且暴，顾我则笑，谑浪笑敖，中心是悼。"], "notes": "", "page": null}, {"text": "终风且霾，惠然肯来，莫往莫来，悠悠我思。", "sentences": ["终风且霾，惠然肯来，莫往莫来，悠悠我思。"], "notes": "", "page": null}, {"text": "终风且曀，不日有曀，寤言不寐，愿言则嚏。", "sentences": ["终风且曀，不日有曀，寤言不寐，愿言则嚏。"], "notes": "", "page": null}, {"text": "曀曀其阴，虺虺其雷，寤言不寐，愿言则怀。", "sentences": ["曀曀其阴，虺虺其雷，寤言不寐，愿言则怀。"], "notes": "", "page": null}]}, {"id": "p031", "title": "击鼓", "section": "国风", "group": "邶风", "intro": "《击鼓》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "击鼓其镗，踊跃用兵。土国城漕，我独南行。", "sentences": ["击鼓其镗，踊跃用兵。", "土国城漕，我独南行。"], "notes": "", "page": null}, {"text": "从孙子仲，平陈与宋。不我以归，忧心有忡。", "sentences": ["从孙子仲，平陈与宋。", "不我以归，忧心有忡。"], "notes": "", "page": null}, {"text": "爰居爰处？爰丧其马？于以求之？于林之下。", "sentences": ["爰居爰处？", "爰丧其马？", "于以求之？", "于林之下。"], "notes": "", "page": null}, {"text": "死生契阔，与子成说。执子之手，与子偕老。", "sentences": ["死生契阔，与子成说。", "执子之手，与子偕老。"], "notes": "", "page": null}, {"text": "于嗟阔兮，不我活兮。于嗟洵兮，不我信兮。", "sentences": ["于嗟阔兮，不我活兮。", "于嗟洵兮，不我信兮。"], "notes": "", "page": null}]}, {"id": "p032", "title": "凯风", "section": "国风", "group": "邶风", "intro": "《凯风》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "凯风自南，吹彼棘心。棘心夭夭，母氏劬劳。", "sentences": ["凯风自南，吹彼棘心。", "棘心夭夭，母氏劬劳。"], "notes": "", "page": null}, {"text": "凯风自南，吹彼棘薪。母氏圣善，我无令人。", "sentences": ["凯风自南，吹彼棘薪。", "母氏圣善，我无令人。"], "notes": "", "page": null}, {"text": "爰有寒痊？在浚之下。有子七人，母氏劳苦。", "sentences": ["爰有寒痊？", "在浚之下。", "有子七人，母氏劳苦。"], "notes": "", "page": null}, {"text": "睍睆黄鸟，载好其音。有子七人，莫慰母心。", "sentences": ["睍睆黄鸟，载好其音。", "有子七人，莫慰母心。"], "notes": "", "page": null}]}, {"id": "p033", "title": "雄雉", "section": "国风", "group": "邶风", "intro": "《雄雉》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "雄雉于飞，泄泄其羽。我之怀矣，自诒伊阻。", "sentences": ["雄雉于飞，泄泄其羽。", "我之怀矣，自诒伊阻。"], "notes": "", "page": null}, {"text": "雄雉于飞，下上其音。展矣君子，实劳我心。", "sentences": ["雄雉于飞，下上其音。", "展矣君子，实劳我心。"], "notes": "", "page": null}, {"text": "瞻彼日月，悠悠我思。道之云远，曷云能来？", "sentences": ["瞻彼日月，悠悠我思。", "道之云远，曷云能来？"], "notes": "", "page": null}, {"text": "百尔君子，不知德行。不忮不求，何用不臧。", "sentences": ["百尔君子，不知德行。", "不忮不求，何用不臧。"], "notes": "", "page": null}]}, {"id": "p034", "title": "匏有苦叶", "section": "国风", "group": "邶风", "intro": "《匏有苦叶》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "匏有苦叶，济有深涉。深则厉，浅则揭。", "sentences": ["匏有苦叶，济有深涉。", "深则厉，浅则揭。"], "notes": "", "page": null}, {"text": "有瀰济盈，有鷕雉鸣。济盈不濡轨，雉鸣求其牡。", "sentences": ["有瀰济盈，有鷕雉鸣。", "济盈不濡轨，雉鸣求其牡。"], "notes": "", "page": null}, {"text": "雍雍鸣雁，旭日始旦。士如归妻，迨冰未泮。", "sentences": ["雍雍鸣雁，旭日始旦。", "士如归妻，迨冰未泮。"], "notes": "", "page": null}, {"text": "招招舟子，人涉卬否。不涉卬否，卬须我友。", "sentences": ["招招舟子，人涉卬否。", "不涉卬否，卬须我友。"], "notes": "", "page": null}]}, {"id": "p035", "title": "谷风", "section": "国风", "group": "邶风", "intro": "《谷风》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "习习谷风，以阴以雨。黾勉同心，不宜有怒。采葑采菲，无以下体？德音莫违，及尔同死。", "sentences": ["习习谷风，以阴以雨。", "黾勉同心，不宜有怒。", "采葑采菲，无以下体？", "德音莫违，及尔同死。"], "notes": "", "page": null}, {"text": "行道迟迟，中心有违。不远伊迩，薄送我畿。谁谓荼苦，其甘如荠。宴尔新婚，如兄如弟。", "sentences": ["行道迟迟，中心有违。", "不远伊迩，薄送我畿。", "谁谓荼苦，其甘如荠。", "宴尔新婚，如兄如弟。"], "notes": "", "page": null}, {"text": "泾以渭浊，湜湜其沚。宴尔新婚，不我屑以。毋逝我梁，毋发我笱。我躬不阅，遑恤我后。", "sentences": ["泾以渭浊，湜湜其沚。", "宴尔新婚，不我屑以。", "毋逝我梁，毋发我笱。", "我躬不阅，遑恤我后。"], "notes": "", "page": null}, {"text": "就其深矣，方之舟之。就其浅矣，泳之游之。何有何亡，黾勉求之。凡民有丧，匍匐救之。", "sentences": ["就其深矣，方之舟之。", "就其浅矣，泳之游之。", "何有何亡，黾勉求之。", "凡民有丧，匍匐救之。"], "notes": "", "page": null}, {"text": "不我能畜，反以我为仇。既阻我德，贾用不售。昔育恐育鞫，及尔颠覆。既生既育，比予于毒。", "sentences": ["不我能畜，反以我为仇。", "既阻我德，贾用不售。", "昔育恐育鞫，及尔颠覆。", "既生既育，比予于毒。"], "notes": "", "page": null}, {"text": "我有旨蓄，亦以御冬。宴尔新婚，以我御穷。有洸有溃，既诒我肄。不念昔者，伊余来塈。", "sentences": ["我有旨蓄，亦以御冬。", "宴尔新婚，以我御穷。", "有洸有溃，既诒我肄。", "不念昔者，伊余来塈。"], "notes": "", "page": null}]}, {"id": "p036", "title": "式微", "section": "国风", "group": "邶风", "intro": "《式微》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "式微，式微，胡不归？微君之故，胡为乎中露！", "sentences": ["式微，式微，胡不归？", "微君之故，胡为乎中露！"], "notes": "", "page": null}, {"text": "式微，式微，胡不归？微君之躬，胡为乎泥中！", "sentences": ["式微，式微，胡不归？", "微君之躬，胡为乎泥中！"], "notes": "", "page": null}]}, {"id": "p037", "title": "旄丘", "section": "国风", "group": "邶风", "intro": "《旄丘》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "旄丘之葛兮，何诞之节兮。叔兮伯兮，何多日也？", "sentences": ["旄丘之葛兮，何诞之节兮。", "叔兮伯兮，何多日也？"], "notes": "", "page": null}, {"text": "何其处也？必有与也！何其久也？必有以也！", "sentences": ["何其处也？", "必有与也！", "何其久也？", "必有以也！"], "notes": "", "page": null}, {"text": "狐裘蒙戎，匪车不东。叔兮伯兮，靡所与同。", "sentences": ["狐裘蒙戎，匪车不东。", "叔兮伯兮，靡所与同。"], "notes": "", "page": null}, {"text": "琐兮尾兮，流离之子。叔兮伯兮，褎如充耳。", "sentences": ["琐兮尾兮，流离之子。", "叔兮伯兮，褎如充耳。"], "notes": "", "page": null}]}, {"id": "p038", "title": "简兮", "section": "国风", "group": "邶风", "intro": "《简兮》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "简兮简兮，方将万舞。日之方中，在前上处。", "sentences": ["简兮简兮，方将万舞。", "日之方中，在前上处。"], "notes": "", "page": null}, {"text": "硕人俣俣，公庭万舞。有力如虎，执辔如组。", "sentences": ["硕人俣俣，公庭万舞。", "有力如虎，执辔如组。"], "notes": "", "page": null}, {"text": "左手执龠，右手秉翟。赫如渥赭，公言锡爵。", "sentences": ["左手执龠，右手秉翟。", "赫如渥赭，公言锡爵。"], "notes": "", "page": null}, {"text": "山有榛，隰有苓。云谁之思？西方美人。彼美人兮，西方之人兮。", "sentences": ["山有榛，隰有苓。", "云谁之思？", "西方美人。", "彼美人兮，西方之人兮。"], "notes": "", "page": null}]}, {"id": "p039", "title": "泉水", "section": "国风", "group": "邶风", "intro": "《泉水》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "毖彼泉水，亦流于淇。有怀于卫，靡日不思。娈彼诸姬，聊与之谋。", "sentences": ["毖彼泉水，亦流于淇。", "有怀于卫，靡日不思。", "娈彼诸姬，聊与之谋。"], "notes": "", "page": null}, {"text": "出宿于泲，饮饯于祢。女子有行，远父母兄弟，问我诸姑，遂及伯姊。", "sentences": ["出宿于泲，饮饯于祢。", "女子有行，远父母兄弟，问我诸姑，遂及伯姊。"], "notes": "", "page": null}, {"text": "出宿于干，饮饯于言。载脂载辖，还车言迈。遄臻于卫，不瑕有害？", "sentences": ["出宿于干，饮饯于言。", "载脂载辖，还车言迈。", "遄臻于卫，不瑕有害？"], "notes": "", "page": null}, {"text": "我思肥泉，兹之永叹。思须与漕，我心悠悠。驾言出游，以写我忧。", "sentences": ["我思肥泉，兹之永叹。", "思须与漕，我心悠悠。", "驾言出游，以写我忧。"], "notes": "", "page": null}]}, {"id": "p040", "title": "北门", "section": "国风", "group": "邶风", "intro": "《北门》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "出自北门，忧心殷殷。终窭且贫，莫知我艰。已焉哉！天实为之，谓之何哉！", "sentences": ["出自北门，忧心殷殷。", "终窭且贫，莫知我艰。", "已焉哉！", "天实为之，谓之何哉！"], "notes": "", "page": null}, {"text": "王事适我，政事一埤益我。我入自外，室人交遍谪我。已焉哉！天实为之，谓之何哉！", "sentences": ["王事适我，政事一埤益我。", "我入自外，室人交遍谪我。", "已焉哉！", "天实为之，谓之何哉！"], "notes": "", "page": null}, {"text": "王事敦我，政事一埤遗我。我入自外，室人交遍摧我。已焉哉！天实为之，谓之何哉！", "sentences": ["王事敦我，政事一埤遗我。", "我入自外，室人交遍摧我。", "已焉哉！", "天实为之，谓之何哉！"], "notes": "", "page": null}]}, {"id": "p041", "title": "北风", "section": "国风", "group": "邶风", "intro": "《北风》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "北风其凉，雨雪其雱。惠而好我，携手同行。其虚其邪？既亟只且！", "sentences": ["北风其凉，雨雪其雱。", "惠而好我，携手同行。", "其虚其邪？", "既亟只且！"], "notes": "", "page": null}, {"text": "北风其喈，雨雪其霏。惠而好我，携手同归。其虚其邪？既亟只且！", "sentences": ["北风其喈，雨雪其霏。", "惠而好我，携手同归。", "其虚其邪？", "既亟只且！"], "notes": "", "page": null}, {"text": "莫赤匪狐，莫黑匪乌。惠而好我，携手同车。其虚其邪？既亟只且！", "sentences": ["莫赤匪狐，莫黑匪乌。", "惠而好我，携手同车。", "其虚其邪？", "既亟只且！"], "notes": "", "page": null}]}, {"id": "p042", "title": "静女", "section": "国风", "group": "邶风", "intro": "《静女》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "静女其姝，俟我于城隅。爱而不见，搔首踟蹰。", "sentences": ["静女其姝，俟我于城隅。", "爱而不见，搔首踟蹰。"], "notes": "", "page": null}, {"text": "静女其娈，贻我彤管。彤管有炜，说怿女美。", "sentences": ["静女其娈，贻我彤管。", "彤管有炜，说怿女美。"], "notes": "", "page": null}, {"text": "自牧归荑，洵美且异。匪女之为美，美人之贻。", "sentences": ["自牧归荑，洵美且异。", "匪女之为美，美人之贻。"], "notes": "", "page": null}]}, {"id": "p043", "title": "新台", "section": "国风", "group": "邶风", "intro": "《新台》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "新台有泚，河水瀰瀰。燕婉之求，蘧篨不鲜。", "sentences": ["新台有泚，河水瀰瀰。", "燕婉之求，蘧篨不鲜。"], "notes": "", "page": null}, {"text": "新台有洒，河水浼浼。燕婉之求，蘧篨不殄。", "sentences": ["新台有洒，河水浼浼。", "燕婉之求，蘧篨不殄。"], "notes": "", "page": null}, {"text": "鱼网之设，鸿则离之。燕婉之求，得此戚施。", "sentences": ["鱼网之设，鸿则离之。", "燕婉之求，得此戚施。"], "notes": "", "page": null}]}, {"id": "p044", "title": "二子乘舟", "section": "国风", "group": "邶风", "intro": "《二子乘舟》收于《诗经·国风·邶风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "二子乘舟，泛泛其景。愿言思子，中心养养！", "sentences": ["二子乘舟，泛泛其景。", "愿言思子，中心养养！"], "notes": "", "page": null}, {"text": "二子乘舟，泛泛其逝。愿言思子，不瑕有害？", "sentences": ["二子乘舟，泛泛其逝。", "愿言思子，不瑕有害？"], "notes": "", "page": null}]}, {"id": "p045", "title": "柏舟", "section": "国风", "group": "鄘风", "intro": "《柏舟》收于《诗经·国风·鄘风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "泛彼柏舟，在彼中河。髧彼两髦，实维我仪。之死矢靡它。母也天只，不谅人只！", "sentences": ["泛彼柏舟，在彼中河。", "髧彼两髦，实维我仪。", "之死矢靡它。", "母也天只，不谅人只！"], "notes": "", "page": null}, {"text": "泛彼柏舟，在彼河侧。髧彼两髦，实维我特。之死矢靡慝。母也天只，不谅人只！", "sentences": ["泛彼柏舟，在彼河侧。", "髧彼两髦，实维我特。", "之死矢靡慝。", "母也天只，不谅人只！"], "notes": "", "page": null}]}, {"id": "p046", "title": "墙有茨", "section": "国风", "group": "鄘风", "intro": "《墙有茨》收于《诗经·国风·鄘风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "墙有茨，不可扫也。中冓之言，不可道也。所可道也，言之丑也。", "sentences": ["墙有茨，不可扫也。", "中冓之言，不可道也。", "所可道也，言之丑也。"], "notes": "", "page": null}, {"text": "墙有茨，不可襄也。中冓之言，不可详也。所可详也，言之长也。", "sentences": ["墙有茨，不可襄也。", "中冓之言，不可详也。", "所可详也，言之长也。"], "notes": "", "page": null}, {"text": "墙有茨，不可束也。中冓之言，不可读也。所可读也，言之辱也。", "sentences": ["墙有茨，不可束也。", "中冓之言，不可读也。", "所可读也，言之辱也。"], "notes": "", "page": null}]}, {"id": "p047", "title": "君子偕老", "section": "国风", "group": "鄘风", "intro": "《君子偕老》收于《诗经·国风·鄘风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "君子偕老，副笄六珈。委委佗佗，如山如河，象服是宜。子之不淑，云如之何？", "sentences": ["君子偕老，副笄六珈。", "委委佗佗，如山如河，象服是宜。", "子之不淑，云如之何？"], "notes": "", "page": null}, {"text": "玼兮玼兮，其之翟也。鬒发如云，不屑髢也。玉之瑱也，象之揥也，扬且之晳也。胡然而天也！胡然而帝也。", "sentences": ["玼兮玼兮，其之翟也。", "鬒发如云，不屑髢也。", "玉之瑱也，象之揥也，扬且之晳也。", "胡然而天也！", "胡然而帝也。"], "notes": "", "page": null}, {"text": "瑳兮瑳兮，其之展也。蒙彼绉絺，是绁袢也。子之清扬，扬且之颜也。展如之人兮，邦之媛也！", "sentences": ["瑳兮瑳兮，其之展也。", "蒙彼绉絺，是绁袢也。", "子之清扬，扬且之颜也。", "展如之人兮，邦之媛也！"], "notes": "", "page": null}]}, {"id": "p048", "title": "桑中", "section": "国风", "group": "鄘风", "intro": "《桑中》收于《诗经·国风·鄘风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "爰采唐矣？沬之乡矣。云谁之思？美孟姜矣。期我乎桑中，要我乎上宫，送我乎淇之上矣。", "sentences": ["爰采唐矣？", "沬之乡矣。", "云谁之思？", "美孟姜矣。", "期我乎桑中，要我乎上宫，送我乎淇之上矣。"], "notes": "", "page": null}, {"text": "爰采麦矣？沬之北矣。云谁之思？美孟弋矣。期我乎桑中，要我乎上宫，送我乎淇之上矣。", "sentences": ["爰采麦矣？", "沬之北矣。", "云谁之思？", "美孟弋矣。", "期我乎桑中，要我乎上宫，送我乎淇之上矣。"], "notes": "", "page": null}, {"text": "爰采葑矣？沬之东矣。云谁之思？美孟庸矣。期我乎桑中，要我乎上宫，送我乎淇之上矣。", "sentences": ["爰采葑矣？", "沬之东矣。", "云谁之思？", "美孟庸矣。", "期我乎桑中，要我乎上宫，送我乎淇之上矣。"], "notes": "", "page": null}]}, {"id": "p049", "title": "鹑之奔奔", "section": "国风", "group": "鄘风", "intro": "《鹑之奔奔》收于《诗经·国风·鄘风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "鹑之奔奔，鹊之彊彊。人之无良，我以为兄！", "sentences": ["鹑之奔奔，鹊之彊彊。", "人之无良，我以为兄！"], "notes": "", "page": null}, {"text": "鹊之彊彊，鹑之奔奔。人之无良，我以为君！", "sentences": ["鹊之彊彊，鹑之奔奔。", "人之无良，我以为君！"], "notes": "", "page": null}]}, {"id": "p050", "title": "定之方中", "section": "国风", "group": "鄘风", "intro": "《定之方中》收于《诗经·国风·鄘风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "定之方中，作于楚宫。揆之以日，作于楚室。树之榛栗，椅桐梓漆，爰伐琴桑。", "sentences": ["定之方中，作于楚宫。", "揆之以日，作于楚室。", "树之榛栗，椅桐梓漆，爰伐琴桑。"], "notes": "", "page": null}, {"text": "升彼虚矣，以望楚矣。望楚与堂，景山与京。降观于桑，卜云其吉，终然允臧。", "sentences": ["升彼虚矣，以望楚矣。", "望楚与堂，景山与京。", "降观于桑，卜云其吉，终然允臧。"], "notes": "", "page": null}, {"text": "灵雨既零，命彼倌人，星言夙驾，说于桑田。匪直也人，秉心塞渊，騋牝三千。", "sentences": ["灵雨既零，命彼倌人，星言夙驾，说于桑田。", "匪直也人，秉心塞渊，騋牝三千。"], "notes": "", "page": null}]}, {"id": "p051", "title": "蝃蝀", "section": "国风", "group": "鄘风", "intro": "《蝃蝀》收于《诗经·国风·鄘风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "蝃蝀在东，莫之敢指。女子有行，远父母兄弟。", "sentences": ["蝃蝀在东，莫之敢指。", "女子有行，远父母兄弟。"], "notes": "", "page": null}, {"text": "朝隮于西，崇朝其雨。女子有行，远兄弟父母。", "sentences": ["朝隮于西，崇朝其雨。", "女子有行，远兄弟父母。"], "notes": "", "page": null}, {"text": "乃如之人也，怀婚姻也。大无信也，不知命也！", "sentences": ["乃如之人也，怀婚姻也。", "大无信也，不知命也！"], "notes": "", "page": null}]}, {"id": "p052", "title": "相鼠", "section": "国风", "group": "鄘风", "intro": "《相鼠》收于《诗经·国风·鄘风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "相鼠有皮，人而无仪！人而无仪，不死何为？", "sentences": ["相鼠有皮，人而无仪！", "人而无仪，不死何为？"], "notes": "", "page": null}, {"text": "相鼠有齿，人而无止！人而无止，不死何俟？", "sentences": ["相鼠有齿，人而无止！", "人而无止，不死何俟？"], "notes": "", "page": null}, {"text": "相鼠有体，人而无礼，人而无礼！胡不遄死？", "sentences": ["相鼠有体，人而无礼，人而无礼！", "胡不遄死？"], "notes": "", "page": null}]}, {"id": "p053", "title": "干旄", "section": "国风", "group": "鄘风", "intro": "《干旄》收于《诗经·国风·鄘风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "孑孑干旄，在浚之郊。素丝纰之，良马四之。彼姝者子，何以畀之？", "sentences": ["孑孑干旄，在浚之郊。", "素丝纰之，良马四之。", "彼姝者子，何以畀之？"], "notes": "", "page": null}, {"text": "孑孑干旟，在浚之都。素丝组之，良马五之。彼姝者子，何以予之？", "sentences": ["孑孑干旟，在浚之都。", "素丝组之，良马五之。", "彼姝者子，何以予之？"], "notes": "", "page": null}, {"text": "孑孑干旌，在浚之城。素丝祝之，良马六之。彼姝者子，何以告之？", "sentences": ["孑孑干旌，在浚之城。", "素丝祝之，良马六之。", "彼姝者子，何以告之？"], "notes": "", "page": null}]}, {"id": "p054", "title": "载驰", "section": "国风", "group": "鄘风", "intro": "《载驰》收于《诗经·国风·鄘风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "载驰载驱，归唁卫侯。驱马悠悠，言至于漕。大夫跋涉，我心则忧。", "sentences": ["载驰载驱，归唁卫侯。", "驱马悠悠，言至于漕。", "大夫跋涉，我心则忧。"], "notes": "", "page": null}, {"text": "既不我嘉，不能旋反。视尔不臧，我思不远。", "sentences": ["既不我嘉，不能旋反。", "视尔不臧，我思不远。"], "notes": "", "page": null}, {"text": "既不我嘉，不能旋济？视尔不臧，我思不閟。", "sentences": ["既不我嘉，不能旋济？", "视尔不臧，我思不閟。"], "notes": "", "page": null}, {"text": "陟彼阿丘，言采其蝱。女子善怀，亦各有行。许人尤之，众稚且狂。", "sentences": ["陟彼阿丘，言采其蝱。", "女子善怀，亦各有行。", "许人尤之，众稚且狂。"], "notes": "", "page": null}, {"text": "我行其野，芃芃其麦。控于大邦，谁因谁极？大夫君子，无我有尤。百尔所思，不如我所之。", "sentences": ["我行其野，芃芃其麦。", "控于大邦，谁因谁极？", "大夫君子，无我有尤。", "百尔所思，不如我所之。"], "notes": "", "page": null}]}, {"id": "p055", "title": "淇奥", "section": "国风", "group": "卫风", "intro": "《淇奥》收于《诗经·国风·卫风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "瞻彼淇奥，绿竹猗猗。有匪君子，如切如磋，如琢如磨，瑟兮僴兮，赫兮咺兮。有匪君子，终不可谖兮。", "sentences": ["瞻彼淇奥，绿竹猗猗。", "有匪君子，如切如磋，如琢如磨，瑟兮僴兮，赫兮咺兮。", "有匪君子，终不可谖兮。"], "notes": "", "page": null}, {"text": "瞻彼淇奥，绿竹青青。有匪君子，充耳秀莹，会弁如星。瑟兮僴兮。赫兮咺兮，有匪君子，终不可谖兮。", "sentences": ["瞻彼淇奥，绿竹青青。", "有匪君子，充耳秀莹，会弁如星。", "瑟兮僴兮。", "赫兮咺兮，有匪君子，终不可谖兮。"], "notes": "", "page": null}, {"text": "瞻彼淇奥，绿竹如箦。有匪君子，如金如锡，如圭如璧。宽兮绰兮，猗重较兮。善戏谑兮，不为虐兮。", "sentences": ["瞻彼淇奥，绿竹如箦。", "有匪君子，如金如锡，如圭如璧。", "宽兮绰兮，猗重较兮。", "善戏谑兮，不为虐兮。"], "notes": "", "page": null}]}, {"id": "p056", "title": "考槃", "section": "国风", "group": "卫风", "intro": "《考槃》收于《诗经·国风·卫风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "考槃在涧，硕人之宽。独寐寤言，永矢弗谖。", "sentences": ["考槃在涧，硕人之宽。", "独寐寤言，永矢弗谖。"], "notes": "", "page": null}, {"text": "考槃在阿，硕人之薖。独寐寤歌，永矢弗过。", "sentences": ["考槃在阿，硕人之薖。", "独寐寤歌，永矢弗过。"], "notes": "", "page": null}, {"text": "考槃在六，硕人之轴。独寐寤宿，永矢弗告。", "sentences": ["考槃在六，硕人之轴。", "独寐寤宿，永矢弗告。"], "notes": "", "page": null}]}, {"id": "p057", "title": "硕人", "section": "国风", "group": "卫风", "intro": "《硕人》收于《诗经·国风·卫风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "硕人其颀，衣锦褧衣。齐侯之子，卫侯之妻。东宫之妹，邢侯之姨，谭公维私。", "sentences": ["硕人其颀，衣锦褧衣。", "齐侯之子，卫侯之妻。", "东宫之妹，邢侯之姨，谭公维私。"], "notes": "", "page": null}, {"text": "手如柔荑，肤如凝脂，领如蝤蛴，齿如瓠犀，螓首蛾眉，巧笑倩兮，美目盼兮。", "sentences": ["手如柔荑，肤如凝脂，领如蝤蛴，齿如瓠犀，螓首蛾眉，巧笑倩兮，美目盼兮。"], "notes": "", "page": null}, {"text": "硕人敖敖，说于农郊。四牡有骄，朱幩镳镳。翟茀以朝。大夫夙退，无使君劳。", "sentences": ["硕人敖敖，说于农郊。", "四牡有骄，朱幩镳镳。", "翟茀以朝。", "大夫夙退，无使君劳。"], "notes": "", "page": null}, {"text": "河水洋洋，北流活活。施罛濊濊，鳣鲔发发。葭菼揭揭，庶姜孽孽，庶士有朅。", "sentences": ["河水洋洋，北流活活。", "施罛濊濊，鳣鲔发发。", "葭菼揭揭，庶姜孽孽，庶士有朅。"], "notes": "", "page": null}]}, {"id": "p058", "title": "氓", "section": "国风", "group": "卫风", "intro": "《氓》收于《诗经·国风·卫风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "氓之蚩蚩，抱布贸丝。匪来贸丝，来即我谋。送子涉淇，至于顿丘。匪我愆期，子无良媒。将子无怒，秋以为期。", "sentences": ["氓之蚩蚩，抱布贸丝。", "匪来贸丝，来即我谋。", "送子涉淇，至于顿丘。", "匪我愆期，子无良媒。", "将子无怒，秋以为期。"], "notes": "", "page": null}, {"text": "乘彼垝垣，以望复关。不见复关，泣涕涟涟。既见复关，载笑载言。尔卜尔筮，体无咎言。以尔车来，以我贿迁。", "sentences": ["乘彼垝垣，以望复关。", "不见复关，泣涕涟涟。", "既见复关，载笑载言。", "尔卜尔筮，体无咎言。", "以尔车来，以我贿迁。"], "notes": "", "page": null}, {"text": "桑之未落，其叶沃若。于嗟鸠兮！无食桑葚。于嗟女兮！无与士耽。士之耽兮，犹可说也。女之耽兮，不可说也。", "sentences": ["桑之未落，其叶沃若。", "于嗟鸠兮！", "无食桑葚。", "于嗟女兮！", "无与士耽。", "士之耽兮，犹可说也。", "女之耽兮，不可说也。"], "notes": "", "page": null}, {"text": "桑之落矣，其黄而陨。自我徂尔，三岁食贫。淇水汤汤，渐车帷裳。女也不爽，士二其行。士也罔极，二三其德。", "sentences": ["桑之落矣，其黄而陨。", "自我徂尔，三岁食贫。", "淇水汤汤，渐车帷裳。", "女也不爽，士二其行。", "士也罔极，二三其德。"], "notes": "", "page": null}, {"text": "三岁为妇，靡室劳矣。夙兴夜寐，靡有朝矣。言既遂矣，至于暴矣。兄弟不知，咥其笑矣。静言思之，躬自悼矣。", "sentences": ["三岁为妇，靡室劳矣。", "夙兴夜寐，靡有朝矣。", "言既遂矣，至于暴矣。", "兄弟不知，咥其笑矣。", "静言思之，躬自悼矣。"], "notes": "", "page": null}, {"text": "及尔偕老，老使我怨。淇则有岸，隰则有泮。总角之宴，言笑晏晏，信誓旦旦，不思其反。反是不思，亦已焉哉！", "sentences": ["及尔偕老，老使我怨。", "淇则有岸，隰则有泮。", "总角之宴，言笑晏晏，信誓旦旦，不思其反。", "反是不思，亦已焉哉！"], "notes": "", "page": null}]}, {"id": "p059", "title": "竹竿", "section": "国风", "group": "卫风", "intro": "《竹竿》收于《诗经·国风·卫风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "籊籊竹竿，以钓于淇。岂不尔思？远莫致之。", "sentences": ["籊籊竹竿，以钓于淇。", "岂不尔思？", "远莫致之。"], "notes": "", "page": null}, {"text": "泉源在左，淇水在右。女子有行，远兄弟父母。", "sentences": ["泉源在左，淇水在右。", "女子有行，远兄弟父母。"], "notes": "", "page": null}, {"text": "淇水在右，泉源在左。巧笑之瑳，佩玉之傩。", "sentences": ["淇水在右，泉源在左。", "巧笑之瑳，佩玉之傩。"], "notes": "", "page": null}, {"text": "淇水滺滺，桧楫松舟。驾言出游，以写我忧。", "sentences": ["淇水滺滺，桧楫松舟。", "驾言出游，以写我忧。"], "notes": "", "page": null}]}, {"id": "p060", "title": "芄兰", "section": "国风", "group": "卫风", "intro": "《芄兰》收于《诗经·国风·卫风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "芄兰之支，童子佩觿。虽则佩觿，能不我知。容兮遂兮，垂带悸兮。", "sentences": ["芄兰之支，童子佩觿。", "虽则佩觿，能不我知。", "容兮遂兮，垂带悸兮。"], "notes": "", "page": null}, {"text": "芄兰之叶，童子佩韘。虽则佩韘，能不我甲。容兮遂兮，垂带悸兮。", "sentences": ["芄兰之叶，童子佩韘。", "虽则佩韘，能不我甲。", "容兮遂兮，垂带悸兮。"], "notes": "", "page": null}]}, {"id": "p061", "title": "河广", "section": "国风", "group": "卫风", "intro": "《河广》收于《诗经·国风·卫风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "谁谓河广？一苇杭之。谁谓宋远？跂予望之。", "sentences": ["谁谓河广？", "一苇杭之。", "谁谓宋远？", "跂予望之。"], "notes": "", "page": null}, {"text": "谁谓河广？曾不容刀。谁谓宋远？曾不崇朝。", "sentences": ["谁谓河广？", "曾不容刀。", "谁谓宋远？", "曾不崇朝。"], "notes": "", "page": null}]}, {"id": "p062", "title": "伯兮", "section": "国风", "group": "卫风", "intro": "《伯兮》收于《诗经·国风·卫风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "伯兮朅兮，邦之桀兮。伯也执殳，为王前驱。", "sentences": ["伯兮朅兮，邦之桀兮。", "伯也执殳，为王前驱。"], "notes": "", "page": null}, {"text": "自伯之东，首如飞蓬。岂无膏沐？谁适为容！", "sentences": ["自伯之东，首如飞蓬。", "岂无膏沐？", "谁适为容！"], "notes": "", "page": null}, {"text": "其雨其雨，杲杲出日。愿言思伯，甘心首疾。", "sentences": ["其雨其雨，杲杲出日。", "愿言思伯，甘心首疾。"], "notes": "", "page": null}, {"text": "焉得谖草？言树之背。愿言思伯。使我心痗。", "sentences": ["焉得谖草？", "言树之背。", "愿言思伯。", "使我心痗。"], "notes": "", "page": null}]}, {"id": "p063", "title": "有狐", "section": "国风", "group": "卫风", "intro": "《有狐》收于《诗经·国风·卫风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "有狐绥绥，在彼淇梁。心之忧矣，之子无裳。", "sentences": ["有狐绥绥，在彼淇梁。", "心之忧矣，之子无裳。"], "notes": "", "page": null}, {"text": "有狐绥绥，在彼淇厉。心之忧矣，之子无带。", "sentences": ["有狐绥绥，在彼淇厉。", "心之忧矣，之子无带。"], "notes": "", "page": null}, {"text": "有狐绥绥，在彼淇侧。心之忧矣，之子无服。", "sentences": ["有狐绥绥，在彼淇侧。", "心之忧矣，之子无服。"], "notes": "", "page": null}]}, {"id": "p064", "title": "木瓜", "section": "国风", "group": "卫风", "intro": "《木瓜》收于《诗经·国风·卫风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "投我以木瓜，报之以琼琚。匪报也，永以为好也！", "sentences": ["投我以木瓜，报之以琼琚。", "匪报也，永以为好也！"], "notes": "", "page": null}, {"text": "投我以木桃，报之以琼瑶。匪报也，永以为好也！", "sentences": ["投我以木桃，报之以琼瑶。", "匪报也，永以为好也！"], "notes": "", "page": null}, {"text": "投我以木李，报之以琼九。匪报也，永以为好也！", "sentences": ["投我以木李，报之以琼九。", "匪报也，永以为好也！"], "notes": "", "page": null}]}, {"id": "p065", "title": "黍离", "section": "国风", "group": "王风", "intro": "《黍离》收于《诗经·国风·王风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "彼黍离离，彼稷之苗。行迈靡靡，中心摇摇。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？", "sentences": ["彼黍离离，彼稷之苗。", "行迈靡靡，中心摇摇。", "知我者，谓我心忧；不知我者，谓我何求。", "悠悠苍天，此何人哉？"], "notes": "", "page": null}, {"text": "彼黍离离，彼稷之穗。行迈靡靡，中心如醉。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？", "sentences": ["彼黍离离，彼稷之穗。", "行迈靡靡，中心如醉。", "知我者，谓我心忧；不知我者，谓我何求。", "悠悠苍天，此何人哉？"], "notes": "", "page": null}, {"text": "彼黍离离，彼稷之实。行迈靡靡，中心如噎。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？", "sentences": ["彼黍离离，彼稷之实。", "行迈靡靡，中心如噎。", "知我者，谓我心忧；不知我者，谓我何求。", "悠悠苍天，此何人哉？"], "notes": "", "page": null}]}, {"id": "p066", "title": "君子于役", "section": "国风", "group": "王风", "intro": "《君子于役》收于《诗经·国风·王风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "君子于役，不知其期。曷至哉？鸡栖于埘。日之夕矣，羊牛下来。君子于役，如之何勿思！", "sentences": ["君子于役，不知其期。", "曷至哉？", "鸡栖于埘。", "日之夕矣，羊牛下来。", "君子于役，如之何勿思！"], "notes": "", "page": null}, {"text": "君子于役，不日不月。曷其有佸？鸡栖于桀。日之夕矣，羊牛下括。君子于役，苟无饥渴？", "sentences": ["君子于役，不日不月。", "曷其有佸？", "鸡栖于桀。", "日之夕矣，羊牛下括。", "君子于役，苟无饥渴？"], "notes": "", "page": null}]}, {"id": "p067", "title": "君子阳阳", "section": "国风", "group": "王风", "intro": "《君子阳阳》收于《诗经·国风·王风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "君子阳阳，左执簧，右招我由房，其乐只且！", "sentences": ["君子阳阳，左执簧，右招我由房，其乐只且！"], "notes": "", "page": null}, {"text": "君子陶陶，左执翿，右招我由敖，其乐只且！", "sentences": ["君子陶陶，左执翿，右招我由敖，其乐只且！"], "notes": "", "page": null}]}, {"id": "p068", "title": "扬之水", "section": "国风", "group": "王风", "intro": "《扬之水》收于《诗经·国风·王风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "扬之水，不流束薪。彼其之子，不与我戍申。怀哉怀哉，曷月予还归哉？", "sentences": ["扬之水，不流束薪。", "彼其之子，不与我戍申。", "怀哉怀哉，曷月予还归哉？"], "notes": "", "page": null}, {"text": "扬之水，不流束楚。彼其之子，不与我戍甫。怀哉怀哉，曷月予还归哉？", "sentences": ["扬之水，不流束楚。", "彼其之子，不与我戍甫。", "怀哉怀哉，曷月予还归哉？"], "notes": "", "page": null}, {"text": "扬之水，不流束蒲。彼其之子，不与我戍许。怀哉怀哉，曷月予还归哉？", "sentences": ["扬之水，不流束蒲。", "彼其之子，不与我戍许。", "怀哉怀哉，曷月予还归哉？"], "notes": "", "page": null}]}, {"id": "p069", "title": "中谷有蓷", "section": "国风", "group": "王风", "intro": "《中谷有蓷》收于《诗经·国风·王风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "中谷有蓷，暵其干矣。有女仳离，慨其叹矣。慨其叹矣，遇人之艰难矣。", "sentences": ["中谷有蓷，暵其干矣。", "有女仳离，慨其叹矣。", "慨其叹矣，遇人之艰难矣。"], "notes": "", "page": null}, {"text": "中谷有蓷，暵其修矣。有女仳离，条其歗矣。条其歗矣，遇人之不淑矣。", "sentences": ["中谷有蓷，暵其修矣。", "有女仳离，条其歗矣。", "条其歗矣，遇人之不淑矣。"], "notes": "", "page": null}, {"text": "中谷有蓷，暵其湿矣。有女仳离，啜其泣矣。啜其泣矣，何嗟及矣。", "sentences": ["中谷有蓷，暵其湿矣。", "有女仳离，啜其泣矣。", "啜其泣矣，何嗟及矣。"], "notes": "", "page": null}]}, {"id": "p070", "title": "兔爰", "section": "国风", "group": "王风", "intro": "《兔爰》收于《诗经·国风·王风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "有兔爰爰，雉离于罗。我生之初，尚无为；我生之后，逢此百罹。尚寐无吪。", "sentences": ["有兔爰爰，雉离于罗。", "我生之初，尚无为；我生之后，逢此百罹。", "尚寐无吪。"], "notes": "", "page": null}, {"text": "有兔爰爰，雉离于罦。我生之初，尚无造；我生之后，逢此百忧。尚寐无觉。", "sentences": ["有兔爰爰，雉离于罦。", "我生之初，尚无造；我生之后，逢此百忧。", "尚寐无觉。"], "notes": "", "page": null}, {"text": "有兔爰爰，雉离于罿。我生之初，尚无庸；我生之后，逢此百凶。尚寐无聪。", "sentences": ["有兔爰爰，雉离于罿。", "我生之初，尚无庸；我生之后，逢此百凶。", "尚寐无聪。"], "notes": "", "page": null}]}, {"id": "p071", "title": "葛藟", "section": "国风", "group": "王风", "intro": "《葛藟》收于《诗经·国风·王风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "绵绵葛藟，在河之浒。终远兄弟，谓他人父。谓他人父，亦莫我顾！", "sentences": ["绵绵葛藟，在河之浒。", "终远兄弟，谓他人父。", "谓他人父，亦莫我顾！"], "notes": "", "page": null}, {"text": "绵绵葛爰，在河之藟。终远兄弟，谓他人母。谓他人母，亦莫我有！", "sentences": ["绵绵葛爰，在河之藟。", "终远兄弟，谓他人母。", "谓他人母，亦莫我有！"], "notes": "", "page": null}, {"text": "绵绵葛藟，在河之漘。终远兄弟，谓他人昆。谓他人昆，亦莫我闻！", "sentences": ["绵绵葛藟，在河之漘。", "终远兄弟，谓他人昆。", "谓他人昆，亦莫我闻！"], "notes": "", "page": null}]}, {"id": "p072", "title": "采葛", "section": "国风", "group": "王风", "intro": "《采葛》收于《诗经·国风·王风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "彼采葛兮，一日不见，如三月兮！", "sentences": ["彼采葛兮，一日不见，如三月兮！"], "notes": "", "page": null}, {"text": "彼采萧兮，一日不见，如三秋兮！", "sentences": ["彼采萧兮，一日不见，如三秋兮！"], "notes": "", "page": null}, {"text": "彼采艾兮！一日不见，如三岁兮！", "sentences": ["彼采艾兮！", "一日不见，如三岁兮！"], "notes": "", "page": null}]}, {"id": "p073", "title": "大车", "section": "国风", "group": "王风", "intro": "《大车》收于《诗经·国风·王风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "大车槛槛，毳衣如菼。岂不尔思？畏子不敢。", "sentences": ["大车槛槛，毳衣如菼。", "岂不尔思？", "畏子不敢。"], "notes": "", "page": null}, {"text": "大车啍啍，毳衣如璊，岂不尔思？畏子不奔。", "sentences": ["大车啍啍，毳衣如璊，岂不尔思？", "畏子不奔。"], "notes": "", "page": null}, {"text": "谷则异室，死则同穴。谓予不信，有如皎日。", "sentences": ["谷则异室，死则同穴。", "谓予不信，有如皎日。"], "notes": "", "page": null}]}, {"id": "p074", "title": "丘中有麻", "section": "国风", "group": "王风", "intro": "《丘中有麻》收于《诗经·国风·王风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "丘中有麻，彼留子嗟。彼留子嗟，将其来施施。", "sentences": ["丘中有麻，彼留子嗟。", "彼留子嗟，将其来施施。"], "notes": "", "page": null}, {"text": "丘中有麦，彼留子国。彼留子国，将其来食。", "sentences": ["丘中有麦，彼留子国。", "彼留子国，将其来食。"], "notes": "", "page": null}, {"text": "丘中有李，彼留之子。彼留之子，贻我佩九。", "sentences": ["丘中有李，彼留之子。", "彼留之子，贻我佩九。"], "notes": "", "page": null}]}, {"id": "p075", "title": "缁衣", "section": "国风", "group": "郑风", "intro": "《缁衣》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "缁衣之宜兮，敝予又改为兮。适子之馆兮。还予授子之粲兮。", "sentences": ["缁衣之宜兮，敝予又改为兮。", "适子之馆兮。", "还予授子之粲兮。"], "notes": "", "page": null}, {"text": "缁衣之好兮，敝予又改造兮。适子之馆兮，还予授子之粲兮。", "sentences": ["缁衣之好兮，敝予又改造兮。", "适子之馆兮，还予授子之粲兮。"], "notes": "", "page": null}, {"text": "缁衣之席兮，敝予又改作兮。适子之馆兮，还予授子之粲兮。", "sentences": ["缁衣之席兮，敝予又改作兮。", "适子之馆兮，还予授子之粲兮。"], "notes": "", "page": null}]}, {"id": "p076", "title": "将仲子", "section": "国风", "group": "郑风", "intro": "《将仲子》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "将仲子兮，无逾我里，无折我树杞。岂敢爱之？畏我父母。仲可怀也，父母之言亦可畏也。", "sentences": ["将仲子兮，无逾我里，无折我树杞。", "岂敢爱之？", "畏我父母。", "仲可怀也，父母之言亦可畏也。"], "notes": "", "page": null}, {"text": "将仲子兮，无逾我墙，无折我树桑。岂敢爱之？畏我诸兄。仲可怀也，诸兄之言亦可畏也。", "sentences": ["将仲子兮，无逾我墙，无折我树桑。", "岂敢爱之？", "畏我诸兄。", "仲可怀也，诸兄之言亦可畏也。"], "notes": "", "page": null}, {"text": "将仲子兮，无逾我园，无折我树檀。岂敢爱之？畏人之多言。仲可怀也，人之多言亦可畏也。", "sentences": ["将仲子兮，无逾我园，无折我树檀。", "岂敢爱之？", "畏人之多言。", "仲可怀也，人之多言亦可畏也。"], "notes": "", "page": null}]}, {"id": "p077", "title": "叔于田", "section": "国风", "group": "郑风", "intro": "《叔于田》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "叔于田，巷无居人。岂无居人？不如叔也。洵美且仁。", "sentences": ["叔于田，巷无居人。", "岂无居人？", "不如叔也。", "洵美且仁。"], "notes": "", "page": null}, {"text": "叔于狩，巷无饮酒。岂无饮酒？不如叔也。洵美且好。", "sentences": ["叔于狩，巷无饮酒。", "岂无饮酒？", "不如叔也。", "洵美且好。"], "notes": "", "page": null}, {"text": "叔适野，巷无服马。岂无服马？不如叔也。洵美且武。", "sentences": ["叔适野，巷无服马。", "岂无服马？", "不如叔也。", "洵美且武。"], "notes": "", "page": null}]}, {"id": "p078", "title": "大叔于田", "section": "国风", "group": "郑风", "intro": "《大叔于田》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "叔于田，乘乘马。执辔如组，两骖如舞。叔在薮，火烈具举。襢裼暴虎，献于公所。将叔勿狃，戒其伤女。", "sentences": ["叔于田，乘乘马。", "执辔如组，两骖如舞。", "叔在薮，火烈具举。", "襢裼暴虎，献于公所。", "将叔勿狃，戒其伤女。"], "notes": "", "page": null}, {"text": "叔于田，乘乘黄。两服上襄，两骖雁行。叔在薮，火烈具扬。叔善射忌，又良御忌。抑罄控忌，抑纵送忌。", "sentences": ["叔于田，乘乘黄。", "两服上襄，两骖雁行。", "叔在薮，火烈具扬。", "叔善射忌，又良御忌。", "抑罄控忌，抑纵送忌。"], "notes": "", "page": null}, {"text": "叔于田，乘乘鸨。两服齐首，两骖如手。叔在薮，火烈具阜。叔马慢忌，叔发罕忌，抑释掤忌，抑鬯弓忌。", "sentences": ["叔于田，乘乘鸨。", "两服齐首，两骖如手。", "叔在薮，火烈具阜。", "叔马慢忌，叔发罕忌，抑释掤忌，抑鬯弓忌。"], "notes": "", "page": null}]}, {"id": "p079", "title": "清人", "section": "国风", "group": "郑风", "intro": "《清人》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "清人在彭，驷介旁旁。二矛重英，河上乎翱翔。", "sentences": ["清人在彭，驷介旁旁。", "二矛重英，河上乎翱翔。"], "notes": "", "page": null}, {"text": "清人在消，驷介麃麃。二矛重乔，河上乎逍遥。", "sentences": ["清人在消，驷介麃麃。", "二矛重乔，河上乎逍遥。"], "notes": "", "page": null}, {"text": "清人在轴，驷介陶陶。左旋右抽，中军作好。", "sentences": ["清人在轴，驷介陶陶。", "左旋右抽，中军作好。"], "notes": "", "page": null}]}, {"id": "p080", "title": "羔裘", "section": "国风", "group": "郑风", "intro": "《羔裘》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "羔裘如濡，洵直且侯。彼其之子，舍命不渝。", "sentences": ["羔裘如濡，洵直且侯。", "彼其之子，舍命不渝。"], "notes": "", "page": null}, {"text": "羔裘豹饰，孔武有力。彼其之子，邦之司直。", "sentences": ["羔裘豹饰，孔武有力。", "彼其之子，邦之司直。"], "notes": "", "page": null}, {"text": "羔裘晏兮，三英粲兮。彼其之子，邦之彦兮。", "sentences": ["羔裘晏兮，三英粲兮。", "彼其之子，邦之彦兮。"], "notes": "", "page": null}]}, {"id": "p081", "title": "遵大路", "section": "国风", "group": "郑风", "intro": "《遵大路》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "遵大路兮，掺执子之袪兮。无我恶兮，不蓵故也！", "sentences": ["遵大路兮，掺执子之袪兮。", "无我恶兮，不蓵故也！"], "notes": "", "page": null}, {"text": "遵大路兮，掺执子之手兮。无我魗兮，不蓵好也！", "sentences": ["遵大路兮，掺执子之手兮。", "无我魗兮，不蓵好也！"], "notes": "", "page": null}]}, {"id": "p082", "title": "女曰鸡鸣", "section": "国风", "group": "郑风", "intro": "《女曰鸡鸣》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "女曰鸡鸣，士曰昧旦。子兴视夜，明星有烂。将翱将翔，弋凫与雁。", "sentences": ["女曰鸡鸣，士曰昧旦。", "子兴视夜，明星有烂。", "将翱将翔，弋凫与雁。"], "notes": "", "page": null}, {"text": "弋言加之，与子宜之。宜言饮酒，与子偕老。琴瑟在御，莫不静好。", "sentences": ["弋言加之，与子宜之。", "宜言饮酒，与子偕老。", "琴瑟在御，莫不静好。"], "notes": "", "page": null}, {"text": "知子之来之，杂佩以赠之。知子之顺之，杂佩以问之。知子之好之，杂佩以报之。", "sentences": ["知子之来之，杂佩以赠之。", "知子之顺之，杂佩以问之。", "知子之好之，杂佩以报之。"], "notes": "", "page": null}]}, {"id": "p083", "title": "有女同车", "section": "国风", "group": "郑风", "intro": "《有女同车》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "有女同车，颜如舜华。将翱将翔，佩玉琼琚。彼美孟姜，洵美且都。", "sentences": ["有女同车，颜如舜华。", "将翱将翔，佩玉琼琚。", "彼美孟姜，洵美且都。"], "notes": "", "page": null}, {"text": "有女同行，颜如舜英。将翱将翔，佩玉将将。彼美孟姜，德音不忘。", "sentences": ["有女同行，颜如舜英。", "将翱将翔，佩玉将将。", "彼美孟姜，德音不忘。"], "notes": "", "page": null}]}, {"id": "p084", "title": "山有扶苏", "section": "国风", "group": "郑风", "intro": "《山有扶苏》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "山有扶苏，隰有荷华。不见子都，乃见狂且。", "sentences": ["山有扶苏，隰有荷华。", "不见子都，乃见狂且。"], "notes": "", "page": null}, {"text": "山有乔松，隰有游龙，不见子充，乃见狡童。", "sentences": ["山有乔松，隰有游龙，不见子充，乃见狡童。"], "notes": "", "page": null}]}, {"id": "p085", "title": "萚兮", "section": "国风", "group": "郑风", "intro": "《萚兮》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "萚兮萚兮，风其吹女。叔兮伯兮，倡予和女。", "sentences": ["萚兮萚兮，风其吹女。", "叔兮伯兮，倡予和女。"], "notes": "", "page": null}, {"text": "萚兮萚兮，风其漂女。叔兮伯兮，倡予要女。", "sentences": ["萚兮萚兮，风其漂女。", "叔兮伯兮，倡予要女。"], "notes": "", "page": null}]}, {"id": "p086", "title": "狡童", "section": "国风", "group": "郑风", "intro": "《狡童》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "彼狡童兮，不与我言兮。维子之故，使我不能餐兮。", "sentences": ["彼狡童兮，不与我言兮。", "维子之故，使我不能餐兮。"], "notes": "", "page": null}, {"text": "彼狡童兮，不与我食兮。维子之故，使我不能息兮。", "sentences": ["彼狡童兮，不与我食兮。", "维子之故，使我不能息兮。"], "notes": "", "page": null}]}, {"id": "p087", "title": "褰裳", "section": "国风", "group": "郑风", "intro": "《褰裳》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "子惠思我，褰裳涉溱。子不我思，岂无他人？狂童之狂也且！", "sentences": ["子惠思我，褰裳涉溱。", "子不我思，岂无他人？", "狂童之狂也且！"], "notes": "", "page": null}, {"text": "子惠思我，褰裳涉洧。子不我思，岂无他士？狂童之狂也且！", "sentences": ["子惠思我，褰裳涉洧。", "子不我思，岂无他士？", "狂童之狂也且！"], "notes": "", "page": null}]}, {"id": "p088", "title": "丰", "section": "国风", "group": "郑风", "intro": "《丰》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "子之丰兮，俟我乎巷兮，悔予不送兮。", "sentences": ["子之丰兮，俟我乎巷兮，悔予不送兮。"], "notes": "", "page": null}, {"text": "子之昌兮，俟我乎堂兮，悔予不将兮。", "sentences": ["子之昌兮，俟我乎堂兮，悔予不将兮。"], "notes": "", "page": null}, {"text": "衣锦褧衣，裳锦褧裳。叔兮伯兮，驾予与行。", "sentences": ["衣锦褧衣，裳锦褧裳。", "叔兮伯兮，驾予与行。"], "notes": "", "page": null}, {"text": "裳锦褧裳，衣锦褧衣。叔兮伯兮，驾予与归。", "sentences": ["裳锦褧裳，衣锦褧衣。", "叔兮伯兮，驾予与归。"], "notes": "", "page": null}]}, {"id": "p089", "title": "东门之墠", "section": "国风", "group": "郑风", "intro": "《东门之墠》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "东门之墠，茹藘在阪。其室则迩，其人甚远。", "sentences": ["东门之墠，茹藘在阪。", "其室则迩，其人甚远。"], "notes": "", "page": null}, {"text": "东门之栗，有践家室。岂不尔思？子不我即！", "sentences": ["东门之栗，有践家室。", "岂不尔思？", "子不我即！"], "notes": "", "page": null}]}, {"id": "p090", "title": "风雨", "section": "国风", "group": "郑风", "intro": "《风雨》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "风雨凄凄，鸡鸣喈喈，既见君子。云胡不夷？", "sentences": ["风雨凄凄，鸡鸣喈喈，既见君子。", "云胡不夷？"], "notes": "", "page": null}, {"text": "风雨潇潇，鸡鸣胶胶。既见君子，云胡不瘳？", "sentences": ["风雨潇潇，鸡鸣胶胶。", "既见君子，云胡不瘳？"], "notes": "", "page": null}, {"text": "风雨如晦，鸡鸣不已。既见君子，云胡不喜？", "sentences": ["风雨如晦，鸡鸣不已。", "既见君子，云胡不喜？"], "notes": "", "page": null}]}, {"id": "p091", "title": "子衿", "section": "国风", "group": "郑风", "intro": "《子衿》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "青青子衿，悠悠我心。纵我不往，子宁不嗣音？", "sentences": ["青青子衿，悠悠我心。", "纵我不往，子宁不嗣音？"], "notes": "", "page": null}, {"text": "青青子佩，悠悠我思。纵我不往，子宁不来？", "sentences": ["青青子佩，悠悠我思。", "纵我不往，子宁不来？"], "notes": "", "page": null}, {"text": "挑兮达兮，在城阙兮。一日不见，如三月兮。", "sentences": ["挑兮达兮，在城阙兮。", "一日不见，如三月兮。"], "notes": "", "page": null}]}, {"id": "p092", "title": "扬之水", "section": "国风", "group": "郑风", "intro": "《扬之水》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "扬之水，不流束楚。终鲜兄弟，维予与女。无信人之言，人实诳女。", "sentences": ["扬之水，不流束楚。", "终鲜兄弟，维予与女。", "无信人之言，人实诳女。"], "notes": "", "page": null}, {"text": "扬之水，不流束薪。终鲜兄弟，维予二人。无信人之言，人实不信。", "sentences": ["扬之水，不流束薪。", "终鲜兄弟，维予二人。", "无信人之言，人实不信。"], "notes": "", "page": null}]}, {"id": "p093", "title": "出其东门", "section": "国风", "group": "郑风", "intro": "《出其东门》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "出其东门，有女如云。虽则如云。匪我思存。缟衣綦巾，聊乐我员。", "sentences": ["出其东门，有女如云。", "虽则如云。", "匪我思存。", "缟衣綦巾，聊乐我员。"], "notes": "", "page": null}, {"text": "出其闉阇，有女如荼。虽则如荼，匪我思且。缟衣茹藘，聊可与娱。", "sentences": ["出其闉阇，有女如荼。", "虽则如荼，匪我思且。", "缟衣茹藘，聊可与娱。"], "notes": "", "page": null}]}, {"id": "p094", "title": "野有蔓草", "section": "国风", "group": "郑风", "intro": "《野有蔓草》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "野有蔓草，零露漙兮。有美一人，清扬婉兮。邂逅相遇，适我愿兮。", "sentences": ["野有蔓草，零露漙兮。", "有美一人，清扬婉兮。", "邂逅相遇，适我愿兮。"], "notes": "", "page": null}, {"text": "野有蔓草，零露瀼瀼。有美一人，婉如清扬。邂逅相遇，与子偕臧。", "sentences": ["野有蔓草，零露瀼瀼。", "有美一人，婉如清扬。", "邂逅相遇，与子偕臧。"], "notes": "", "page": null}]}, {"id": "p095", "title": "溱洧", "section": "国风", "group": "郑风", "intro": "《溱洧》收于《诗经·国风·郑风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "溱与洧，方涣涣兮。士与女，方秉蕳兮。女曰观乎？士曰既且。且往观乎？", "sentences": ["溱与洧，方涣涣兮。", "士与女，方秉蕳兮。", "女曰观乎？", "士曰既且。", "且往观乎？"], "notes": "", "page": null}, {"text": "洧之外，洵訏且乐。维士与女，伊其相谑，赠之以勺药。", "sentences": ["洧之外，洵訏且乐。", "维士与女，伊其相谑，赠之以勺药。"], "notes": "", "page": null}, {"text": "溱与洧，浏其清矣。士与女，殷其盈矣。女曰观乎？士曰既且。且往观乎？", "sentences": ["溱与洧，浏其清矣。", "士与女，殷其盈矣。", "女曰观乎？", "士曰既且。", "且往观乎？"], "notes": "", "page": null}, {"text": "洧之外，洵訏且乐。维士与女，伊其将谑，赠之以勺药。", "sentences": ["洧之外，洵訏且乐。", "维士与女，伊其将谑，赠之以勺药。"], "notes": "", "page": null}]}, {"id": "p096", "title": "鸡鸣", "section": "国风", "group": "齐风", "intro": "《鸡鸣》收于《诗经·国风·齐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "鸡既鸣矣，朝既盈矣。匪鸡则鸣，苍蝇之声。", "sentences": ["鸡既鸣矣，朝既盈矣。", "匪鸡则鸣，苍蝇之声。"], "notes": "", "page": null}, {"text": "东方明矣，朝既昌矣。匪东方则明，月出之光。", "sentences": ["东方明矣，朝既昌矣。", "匪东方则明，月出之光。"], "notes": "", "page": null}, {"text": "虫飞薨薨，甘与子同梦。会且归矣，无庶予子憎。", "sentences": ["虫飞薨薨，甘与子同梦。", "会且归矣，无庶予子憎。"], "notes": "", "page": null}]}, {"id": "p097", "title": "还", "section": "国风", "group": "齐风", "intro": "《还》收于《诗经·国风·齐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "子之还兮，遭我乎狃之间兮。并驱从两肩兮，揖我谓我儇兮。", "sentences": ["子之还兮，遭我乎狃之间兮。", "并驱从两肩兮，揖我谓我儇兮。"], "notes": "", "page": null}, {"text": "子之茂兮，遭我乎狃之道兮。并驱从两牡兮，揖我谓我好兮。", "sentences": ["子之茂兮，遭我乎狃之道兮。", "并驱从两牡兮，揖我谓我好兮。"], "notes": "", "page": null}, {"text": "子之昌兮，遭我乎狃之阳兮。并驱从两狼兮，揖我谓我臧兮。", "sentences": ["子之昌兮，遭我乎狃之阳兮。", "并驱从两狼兮，揖我谓我臧兮。"], "notes": "", "page": null}]}, {"id": "p098", "title": "着", "section": "国风", "group": "齐风", "intro": "《着》收于《诗经·国风·齐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "俟我于着乎而，充耳以素乎而，尚之以琼华乎而。", "sentences": ["俟我于着乎而，充耳以素乎而，尚之以琼华乎而。"], "notes": "", "page": null}, {"text": "俟我于庭乎而，充耳以青乎而，尚之以琼莹乎而。", "sentences": ["俟我于庭乎而，充耳以青乎而，尚之以琼莹乎而。"], "notes": "", "page": null}, {"text": "俟我于堂乎而，充耳以黄乎而，尚之以琼英乎而。", "sentences": ["俟我于堂乎而，充耳以黄乎而，尚之以琼英乎而。"], "notes": "", "page": null}]}, {"id": "p099", "title": "东方之日", "section": "国风", "group": "齐风", "intro": "《东方之日》收于《诗经·国风·齐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "东方之日兮，彼姝者子，在我室兮。在我室兮，履我即兮。", "sentences": ["东方之日兮，彼姝者子，在我室兮。", "在我室兮，履我即兮。"], "notes": "", "page": null}, {"text": "东方之月兮，彼姝者子，在我闼兮。在我闼兮，履我发兮。", "sentences": ["东方之月兮，彼姝者子，在我闼兮。", "在我闼兮，履我发兮。"], "notes": "", "page": null}]}, {"id": "p100", "title": "东方未明", "section": "国风", "group": "齐风", "intro": "《东方未明》收于《诗经·国风·齐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "东方未明，颠倒衣裳。颠之倒之，自公召之。", "sentences": ["东方未明，颠倒衣裳。", "颠之倒之，自公召之。"], "notes": "", "page": null}, {"text": "东方未晞，颠倒裳衣。倒之颠之，自公令之。", "sentences": ["东方未晞，颠倒裳衣。", "倒之颠之，自公令之。"], "notes": "", "page": null}, {"text": "折柳樊圃，狂夫瞿瞿。不能辰夜，不夙则莫。", "sentences": ["折柳樊圃，狂夫瞿瞿。", "不能辰夜，不夙则莫。"], "notes": "", "page": null}]}, {"id": "p101", "title": "南山", "section": "国风", "group": "齐风", "intro": "《南山》收于《诗经·国风·齐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "南山崔崔，雄狐绥绥。鲁道有荡，齐子由归。既曰归止，曷又怀止？", "sentences": ["南山崔崔，雄狐绥绥。", "鲁道有荡，齐子由归。", "既曰归止，曷又怀止？"], "notes": "", "page": null}, {"text": "葛屦五两，冠緌双止。鲁道有荡，齐子庸止。既曰庸止，曷又从止？", "sentences": ["葛屦五两，冠緌双止。", "鲁道有荡，齐子庸止。", "既曰庸止，曷又从止？"], "notes": "", "page": null}, {"text": "蓺麻如之何？衡从其亩。取妻如之何？必告父母。既曰告止，曷又鞠止？", "sentences": ["蓺麻如之何？", "衡从其亩。", "取妻如之何？", "必告父母。", "既曰告止，曷又鞠止？"], "notes": "", "page": null}, {"text": "析薪如之何？匪斧不克。取妻如之何？匪媒不得。既曰得止，曷又极止？", "sentences": ["析薪如之何？", "匪斧不克。", "取妻如之何？", "匪媒不得。", "既曰得止，曷又极止？"], "notes": "", "page": null}]}, {"id": "p102", "title": "甫田", "section": "国风", "group": "齐风", "intro": "《甫田》收于《诗经·国风·齐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "无田甫田，维莠骄骄。无思远人，劳心忉忉。", "sentences": ["无田甫田，维莠骄骄。", "无思远人，劳心忉忉。"], "notes": "", "page": null}, {"text": "无田甫田，维莠桀桀。无思远人，劳心怛怛。", "sentences": ["无田甫田，维莠桀桀。", "无思远人，劳心怛怛。"], "notes": "", "page": null}, {"text": "婉兮娈兮。总角丱兮。未几见兮，突而弁兮！", "sentences": ["婉兮娈兮。", "总角丱兮。", "未几见兮，突而弁兮！"], "notes": "", "page": null}]}, {"id": "p103", "title": "卢令", "section": "国风", "group": "齐风", "intro": "《卢令》收于《诗经·国风·齐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "卢令令，其人美且仁。", "sentences": ["卢令令，其人美且仁。"], "notes": "", "page": null}, {"text": "卢重环，其人美且鬈。", "sentences": ["卢重环，其人美且鬈。"], "notes": "", "page": null}, {"text": "卢重鋂，其人美且偲。", "sentences": ["卢重鋂，其人美且偲。"], "notes": "", "page": null}]}, {"id": "p104", "title": "敝笱", "section": "国风", "group": "齐风", "intro": "《敝笱》收于《诗经·国风·齐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "敝笱在梁，其鱼鲂鳏。齐子归止，其从如云。", "sentences": ["敝笱在梁，其鱼鲂鳏。", "齐子归止，其从如云。"], "notes": "", "page": null}, {"text": "敝笱在梁，其鱼鲂鱮。齐子归止，其从如雨。", "sentences": ["敝笱在梁，其鱼鲂鱮。", "齐子归止，其从如雨。"], "notes": "", "page": null}, {"text": "敝笱在梁，其鱼唯唯。齐子归止，其从如水。", "sentences": ["敝笱在梁，其鱼唯唯。", "齐子归止，其从如水。"], "notes": "", "page": null}]}, {"id": "p105", "title": "载驱", "section": "国风", "group": "齐风", "intro": "《载驱》收于《诗经·国风·齐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "载驱薄薄，簟茀朱鞹。鲁道有荡，齐子发夕。", "sentences": ["载驱薄薄，簟茀朱鞹。", "鲁道有荡，齐子发夕。"], "notes": "", "page": null}, {"text": "四骊济济，垂辔沵沵。鲁道有荡，齐子岂弟。", "sentences": ["四骊济济，垂辔沵沵。", "鲁道有荡，齐子岂弟。"], "notes": "", "page": null}, {"text": "汶水汤汤，行人彭彭。鲁道有荡，齐子翱翔。", "sentences": ["汶水汤汤，行人彭彭。", "鲁道有荡，齐子翱翔。"], "notes": "", "page": null}, {"text": "汶水滔滔，行人儦儦。鲁道有荡，齐了游敖。", "sentences": ["汶水滔滔，行人儦儦。", "鲁道有荡，齐了游敖。"], "notes": "", "page": null}]}, {"id": "p106", "title": "猗嗟", "section": "国风", "group": "齐风", "intro": "《猗嗟》收于《诗经·国风·齐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "猗嗟昌兮，颀而长兮。抑若扬兮，美目扬兮。巧趋跄兮，射则臧兮。", "sentences": ["猗嗟昌兮，颀而长兮。", "抑若扬兮，美目扬兮。", "巧趋跄兮，射则臧兮。"], "notes": "", "page": null}, {"text": "猗嗟名兮，美目清兮。仪既成兮，终日射侯，不出正兮，展我甥兮。", "sentences": ["猗嗟名兮，美目清兮。", "仪既成兮，终日射侯，不出正兮，展我甥兮。"], "notes": "", "page": null}, {"text": "猗嗟娈兮，清扬婉兮。舞则选兮，射则贯兮，四矢反兮，以御乱兮。", "sentences": ["猗嗟娈兮，清扬婉兮。", "舞则选兮，射则贯兮，四矢反兮，以御乱兮。"], "notes": "", "page": null}]}, {"id": "p107", "title": "葛屦", "section": "国风", "group": "魏风", "intro": "《葛屦》收于《诗经·国风·魏风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "纠纠葛屦，可以履霜？掺掺女手，可以缝裳？要之襋之，好人服之。", "sentences": ["纠纠葛屦，可以履霜？", "掺掺女手，可以缝裳？", "要之襋之，好人服之。"], "notes": "", "page": null}, {"text": "好人提提，宛然左辟，佩其象揥。维是褊心，是以为刺。", "sentences": ["好人提提，宛然左辟，佩其象揥。", "维是褊心，是以为刺。"], "notes": "", "page": null}]}, {"id": "p108", "title": "汾沮洳", "section": "国风", "group": "魏风", "intro": "《汾沮洳》收于《诗经·国风·魏风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "彼汾沮洳，言采其莫。彼其之子，美无度。美无度，殊异乎公路。", "sentences": ["彼汾沮洳，言采其莫。", "彼其之子，美无度。", "美无度，殊异乎公路。"], "notes": "", "page": null}, {"text": "彼汾一方，言采其桑。彼其之子，美如英。美如英，殊异乎公行。", "sentences": ["彼汾一方，言采其桑。", "彼其之子，美如英。", "美如英，殊异乎公行。"], "notes": "", "page": null}, {"text": "彼汾一曲，言采其藚。彼其之子，美如玉。美如玉，殊异乎公族。", "sentences": ["彼汾一曲，言采其藚。", "彼其之子，美如玉。", "美如玉，殊异乎公族。"], "notes": "", "page": null}]}, {"id": "p109", "title": "园有桃", "section": "国风", "group": "魏风", "intro": "《园有桃》收于《诗经·国风·魏风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "园有桃，其实之肴。心之忧矣，我歌且谣。不知我者，谓我士也骄。", "sentences": ["园有桃，其实之肴。", "心之忧矣，我歌且谣。", "不知我者，谓我士也骄。"], "notes": "", "page": null}, {"text": "彼人是哉，子曰何其？心之忧矣，其谁知之？其谁知之，盖亦勿思！", "sentences": ["彼人是哉，子曰何其？", "心之忧矣，其谁知之？", "其谁知之，盖亦勿思！"], "notes": "", "page": null}, {"text": "园有棘，其实之食。心之忧矣，聊以行国。不知我者，谓我士也罔极。", "sentences": ["园有棘，其实之食。", "心之忧矣，聊以行国。", "不知我者，谓我士也罔极。"], "notes": "", "page": null}, {"text": "彼人是哉，子曰何其？心之忧矣，其谁知之？其谁知之，盖亦勿思！", "sentences": ["彼人是哉，子曰何其？", "心之忧矣，其谁知之？", "其谁知之，盖亦勿思！"], "notes": "", "page": null}]}, {"id": "p110", "title": "陟岵", "section": "国风", "group": "魏风", "intro": "《陟岵》收于《诗经·国风·魏风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "陟彼岵兮，瞻望父兮。父曰：嗟！予子行役，夙夜无已。上慎旃哉，犹来！无止！", "sentences": ["陟彼岵兮，瞻望父兮。", "父曰：嗟！", "予子行役，夙夜无已。", "上慎旃哉，犹来！", "无止！"], "notes": "", "page": null}, {"text": "陟彼屺兮，瞻望母兮。母曰：嗟！予季行役，夙夜无寐。上慎旃哉，犹来！无弃！", "sentences": ["陟彼屺兮，瞻望母兮。", "母曰：嗟！", "予季行役，夙夜无寐。", "上慎旃哉，犹来！", "无弃！"], "notes": "", "page": null}, {"text": "陟彼冈兮，瞻望兄兮。兄曰：嗟！予弟行役，夙夜必偕。上慎旃哉，犹来！无死！", "sentences": ["陟彼冈兮，瞻望兄兮。", "兄曰：嗟！", "予弟行役，夙夜必偕。", "上慎旃哉，犹来！", "无死！"], "notes": "", "page": null}]}, {"id": "p111", "title": "十亩之间", "section": "国风", "group": "魏风", "intro": "《十亩之间》收于《诗经·国风·魏风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "十亩之间兮，桑者闲闲兮，行与子还兮。", "sentences": ["十亩之间兮，桑者闲闲兮，行与子还兮。"], "notes": "", "page": null}, {"text": "十亩之外兮，桑者泄泄兮，行与子逝兮。", "sentences": ["十亩之外兮，桑者泄泄兮，行与子逝兮。"], "notes": "", "page": null}]}, {"id": "p112", "title": "伐檀", "section": "国风", "group": "魏风", "intro": "《伐檀》收于《诗经·国风·魏风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "坎坎伐檀兮，置之河之干兮。河水清且涟猗。不稼不穑，胡取禾三百廛兮？", "sentences": ["坎坎伐檀兮，置之河之干兮。", "河水清且涟猗。", "不稼不穑，胡取禾三百廛兮？"], "notes": "", "page": null}, {"text": "不狩不猎，胡瞻尔庭有县貆兮？彼君子兮，不素餐兮！", "sentences": ["不狩不猎，胡瞻尔庭有县貆兮？", "彼君子兮，不素餐兮！"], "notes": "", "page": null}, {"text": "坎坎伐辐兮，置之河之侧兮。河水清且直猗。不稼不穑，胡取禾三百亿兮？", "sentences": ["坎坎伐辐兮，置之河之侧兮。", "河水清且直猗。", "不稼不穑，胡取禾三百亿兮？"], "notes": "", "page": null}, {"text": "不狩不猎，胡瞻尔庭有县特兮？彼君子兮，不素食兮！", "sentences": ["不狩不猎，胡瞻尔庭有县特兮？", "彼君子兮，不素食兮！"], "notes": "", "page": null}, {"text": "坎坎伐轮兮，置之河之漘兮。河水清且沦猗。不稼不穑，胡取禾三百囷兮？", "sentences": ["坎坎伐轮兮，置之河之漘兮。", "河水清且沦猗。", "不稼不穑，胡取禾三百囷兮？"], "notes": "", "page": null}, {"text": "不狩不猎，胡瞻尔庭有县鹑兮？彼君子兮，不素飧兮！", "sentences": ["不狩不猎，胡瞻尔庭有县鹑兮？", "彼君子兮，不素飧兮！"], "notes": "", "page": null}]}, {"id": "p113", "title": "硕鼠", "section": "国风", "group": "魏风", "intro": "《硕鼠》收于《诗经·国风·魏风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "硕鼠硕鼠，无食我黍！三岁贯女，莫我肯顾。逝将去女，适彼乐土。乐土乐土，爰得我所。", "sentences": ["硕鼠硕鼠，无食我黍！", "三岁贯女，莫我肯顾。", "逝将去女，适彼乐土。", "乐土乐土，爰得我所。"], "notes": "", "page": null}, {"text": "硕鼠硕鼠，无食我麦！三岁贯女，莫我肯德。逝将去女，适彼乐国。乐国乐国，爰得我直。", "sentences": ["硕鼠硕鼠，无食我麦！", "三岁贯女，莫我肯德。", "逝将去女，适彼乐国。", "乐国乐国，爰得我直。"], "notes": "", "page": null}, {"text": "硕鼠硕鼠，无食我苗！三岁贯女，莫我肯劳。逝将去女，适彼乐郊。乐郊乐郊，谁之永号？", "sentences": ["硕鼠硕鼠，无食我苗！", "三岁贯女，莫我肯劳。", "逝将去女，适彼乐郊。", "乐郊乐郊，谁之永号？"], "notes": "", "page": null}]}, {"id": "p114", "title": "蟋蟀", "section": "国风", "group": "唐风", "intro": "《蟋蟀》收于《诗经·国风·唐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "蟋蟀在堂，岁聿其莫。今我不乐，日月其除。无已大康，职思其居。好乐无荒，良士瞿瞿。", "sentences": ["蟋蟀在堂，岁聿其莫。", "今我不乐，日月其除。", "无已大康，职思其居。", "好乐无荒，良士瞿瞿。"], "notes": "", "page": null}, {"text": "蟋蟀在堂，岁聿其逝。今我不乐，日月其迈。无已大康，职思其外。好乐无荒，良士蹶蹶。", "sentences": ["蟋蟀在堂，岁聿其逝。", "今我不乐，日月其迈。", "无已大康，职思其外。", "好乐无荒，良士蹶蹶。"], "notes": "", "page": null}, {"text": "蟋蟀在堂，役车其休。今我不乐，日月其慆。无以大康。职思其忧。好乐无荒，良士休休。", "sentences": ["蟋蟀在堂，役车其休。", "今我不乐，日月其慆。", "无以大康。", "职思其忧。", "好乐无荒，良士休休。"], "notes": "", "page": null}]}, {"id": "p115", "title": "山有枢", "section": "国风", "group": "唐风", "intro": "《山有枢》收于《诗经·国风·唐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "山有枢，隰有榆。子有衣裳，弗曳弗娄。子有车马，弗驰弗驱。宛其死矣，他人是愉。", "sentences": ["山有枢，隰有榆。", "子有衣裳，弗曳弗娄。", "子有车马，弗驰弗驱。", "宛其死矣，他人是愉。"], "notes": "", "page": null}, {"text": "山有栲，隰有杻。子有廷内，弗洒弗扫。子有钟鼓，弗鼓弗考。宛其死矣，他人是保。", "sentences": ["山有栲，隰有杻。", "子有廷内，弗洒弗扫。", "子有钟鼓，弗鼓弗考。", "宛其死矣，他人是保。"], "notes": "", "page": null}, {"text": "山有漆，隰有栗。子有酒食，何不日鼓瑟？且以喜乐，且以永日。宛其死矣，他人入室。", "sentences": ["山有漆，隰有栗。", "子有酒食，何不日鼓瑟？", "且以喜乐，且以永日。", "宛其死矣，他人入室。"], "notes": "", "page": null}]}, {"id": "p116", "title": "扬之水", "section": "国风", "group": "唐风", "intro": "《扬之水》收于《诗经·国风·唐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "扬之水，白石凿凿。素衣朱襮，从子于沃。既见君子，云何不乐？", "sentences": ["扬之水，白石凿凿。", "素衣朱襮，从子于沃。", "既见君子，云何不乐？"], "notes": "", "page": null}, {"text": "扬之水，白石皓皓。素衣朱绣，从子于鹄。既见君子，云何其忧？", "sentences": ["扬之水，白石皓皓。", "素衣朱绣，从子于鹄。", "既见君子，云何其忧？"], "notes": "", "page": null}, {"text": "扬之水，白石粼粼。我闻有命，不敢以告人。", "sentences": ["扬之水，白石粼粼。", "我闻有命，不敢以告人。"], "notes": "", "page": null}]}, {"id": "p117", "title": "椒聊", "section": "国风", "group": "唐风", "intro": "《椒聊》收于《诗经·国风·唐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "椒聊之实，蕃衍盈升。彼其之子，硕大无朋。椒聊且，远条且。", "sentences": ["椒聊之实，蕃衍盈升。", "彼其之子，硕大无朋。", "椒聊且，远条且。"], "notes": "", "page": null}, {"text": "椒聊之实，蕃衍盈匊。彼其之子，硕大且笃。椒聊且，远条且。", "sentences": ["椒聊之实，蕃衍盈匊。", "彼其之子，硕大且笃。", "椒聊且，远条且。"], "notes": "", "page": null}]}, {"id": "p118", "title": "绸缪", "section": "国风", "group": "唐风", "intro": "《绸缪》收于《诗经·国风·唐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "绸缪束薪，三星在天。今夕何夕，见此良人？子兮子兮，如此良人何？", "sentences": ["绸缪束薪，三星在天。", "今夕何夕，见此良人？", "子兮子兮，如此良人何？"], "notes": "", "page": null}, {"text": "绸缪束刍，三星在隅。今夕何夕，见此邂逅？子兮子兮，如此邂逅何？", "sentences": ["绸缪束刍，三星在隅。", "今夕何夕，见此邂逅？", "子兮子兮，如此邂逅何？"], "notes": "", "page": null}, {"text": "绸缪束楚，三星在户。今夕何夕，见此粲者？子兮子兮，如此粲者何？", "sentences": ["绸缪束楚，三星在户。", "今夕何夕，见此粲者？", "子兮子兮，如此粲者何？"], "notes": "", "page": null}]}, {"id": "p119", "title": "杕杜", "section": "国风", "group": "唐风", "intro": "《杕杜》收于《诗经·国风·唐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "有杕之杜，其叶湑湑。独行踽踽。岂无他人？不如我同父。嗟行之人，胡不比焉？人无兄弟，胡不佽焉？", "sentences": ["有杕之杜，其叶湑湑。", "独行踽踽。", "岂无他人？", "不如我同父。", "嗟行之人，胡不比焉？", "人无兄弟，胡不佽焉？"], "notes": "", "page": null}, {"text": "有杕之杜，其叶箐箐。独行睘睘。岂无他人？不如我同姓。嗟行之人，胡不比焉？人无兄弟，胡不佽焉？", "sentences": ["有杕之杜，其叶箐箐。", "独行睘睘。", "岂无他人？", "不如我同姓。", "嗟行之人，胡不比焉？", "人无兄弟，胡不佽焉？"], "notes": "", "page": null}]}, {"id": "p120", "title": "羔裘", "section": "国风", "group": "唐风", "intro": "《羔裘》收于《诗经·国风·唐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "羔裘豹祛，自我人居居。岂无他人？维子之故。", "sentences": ["羔裘豹祛，自我人居居。", "岂无他人？", "维子之故。"], "notes": "", "page": null}, {"text": "羔裘豹褎，自我人究究。岂无他人？维子之好。", "sentences": ["羔裘豹褎，自我人究究。", "岂无他人？", "维子之好。"], "notes": "", "page": null}]}, {"id": "p121", "title": "鸨羽", "section": "国风", "group": "唐风", "intro": "《鸨羽》收于《诗经·国风·唐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "肃肃鸨羽，集于苞栩。王事靡盬，不能蓺稷黍。父母何怙？悠悠苍天，曷其有所？", "sentences": ["肃肃鸨羽，集于苞栩。", "王事靡盬，不能蓺稷黍。", "父母何怙？", "悠悠苍天，曷其有所？"], "notes": "", "page": null}, {"text": "肃肃鸨翼，集于苞棘。王事靡盬，不能蓺黍稷。父母何食？悠悠苍天，曷其有极？", "sentences": ["肃肃鸨翼，集于苞棘。", "王事靡盬，不能蓺黍稷。", "父母何食？", "悠悠苍天，曷其有极？"], "notes": "", "page": null}, {"text": "肃肃鸨行，集于苞桑，王事靡盬，不能蓺稻梁。父母何尝？悠悠苍天，曷其有常？", "sentences": ["肃肃鸨行，集于苞桑，王事靡盬，不能蓺稻梁。", "父母何尝？", "悠悠苍天，曷其有常？"], "notes": "", "page": null}]}, {"id": "p122", "title": "无衣", "section": "国风", "group": "唐风", "intro": "《无衣》收于《诗经·国风·唐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "岂曰无衣七兮？不如子之衣，安且吉兮！", "sentences": ["岂曰无衣七兮？", "不如子之衣，安且吉兮！"], "notes": "", "page": null}, {"text": "岂曰无衣六兮？不如子之衣，安且燠兮！", "sentences": ["岂曰无衣六兮？", "不如子之衣，安且燠兮！"], "notes": "", "page": null}]}, {"id": "p123", "title": "有杕之杜", "section": "国风", "group": "唐风", "intro": "《有杕之杜》收于《诗经·国风·唐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "有杕之杜，生于道左。彼君子兮，噬肯适我？中心好之，曷饮食之？", "sentences": ["有杕之杜，生于道左。", "彼君子兮，噬肯适我？", "中心好之，曷饮食之？"], "notes": "", "page": null}, {"text": "有杕之杜，生于道周。彼君子兮，噬肯来游？中心好之，曷饮食之？", "sentences": ["有杕之杜，生于道周。", "彼君子兮，噬肯来游？", "中心好之，曷饮食之？"], "notes": "", "page": null}]}, {"id": "p124", "title": "葛生", "section": "国风", "group": "唐风", "intro": "《葛生》收于《诗经·国风·唐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "葛生蒙楚，蔹蔓于野。予美亡此，谁与？独处？", "sentences": ["葛生蒙楚，蔹蔓于野。", "予美亡此，谁与？", "独处？"], "notes": "", "page": null}, {"text": "葛生蒙棘，蔹蔓于域。予美亡此，谁与？独息？", "sentences": ["葛生蒙棘，蔹蔓于域。", "予美亡此，谁与？", "独息？"], "notes": "", "page": null}, {"text": "角枕粲兮，锦衾烂兮。予美亡此，谁与？独旦？", "sentences": ["角枕粲兮，锦衾烂兮。", "予美亡此，谁与？", "独旦？"], "notes": "", "page": null}, {"text": "夏之日，冬之夜。百岁之后，归于其居。", "sentences": ["夏之日，冬之夜。", "百岁之后，归于其居。"], "notes": "", "page": null}, {"text": "冬之夜，夏之日。百岁之后，归于其室。", "sentences": ["冬之夜，夏之日。", "百岁之后，归于其室。"], "notes": "", "page": null}]}, {"id": "p125", "title": "采苓", "section": "国风", "group": "唐风", "intro": "《采苓》收于《诗经·国风·唐风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "采苓采苓，首阳之巅。人之为言，苟亦无信。舍旃舍旃，苟亦无然。人之为言，胡得焉？", "sentences": ["采苓采苓，首阳之巅。", "人之为言，苟亦无信。", "舍旃舍旃，苟亦无然。", "人之为言，胡得焉？"], "notes": "", "page": null}, {"text": "采苦采苦，首阳之下。人之为言，苟亦无与。舍旃舍旃，苟亦无然。人之为言，胡得焉？", "sentences": ["采苦采苦，首阳之下。", "人之为言，苟亦无与。", "舍旃舍旃，苟亦无然。", "人之为言，胡得焉？"], "notes": "", "page": null}, {"text": "采葑采葑，首阳之东。人之为言，苟亦无从。舍旃舍旃，苟亦无然。人之为言，胡得焉？", "sentences": ["采葑采葑，首阳之东。", "人之为言，苟亦无从。", "舍旃舍旃，苟亦无然。", "人之为言，胡得焉？"], "notes": "", "page": null}]}, {"id": "p126", "title": "车邻", "section": "国风", "group": "秦风", "intro": "《车邻》收于《诗经·国风·秦风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "有车邻邻，有马白颠。未见君子，寺人之令。", "sentences": ["有车邻邻，有马白颠。", "未见君子，寺人之令。"], "notes": "", "page": null}, {"text": "阪有漆，隰有栗。既见君子，并坐鼓瑟。今者不乐，逝者其耋。", "sentences": ["阪有漆，隰有栗。", "既见君子，并坐鼓瑟。", "今者不乐，逝者其耋。"], "notes": "", "page": null}, {"text": "阪有桑，隰有杨。既见君子，并坐鼓簧。今者不乐，逝者其亡。", "sentences": ["阪有桑，隰有杨。", "既见君子，并坐鼓簧。", "今者不乐，逝者其亡。"], "notes": "", "page": null}]}, {"id": "p127", "title": "驷驖", "section": "国风", "group": "秦风", "intro": "《驷驖》收于《诗经·国风·秦风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "驷驖孔阜，六辔在手。公之媚子，从公于狩。", "sentences": ["驷驖孔阜，六辔在手。", "公之媚子，从公于狩。"], "notes": "", "page": null}, {"text": "奉时辰牡，辰牡孔硕。公曰左之，舍拔则获。", "sentences": ["奉时辰牡，辰牡孔硕。", "公曰左之，舍拔则获。"], "notes": "", "page": null}, {"text": "游于北园，四马既闲。輶车鸾镳，载猃歇骄。", "sentences": ["游于北园，四马既闲。", "輶车鸾镳，载猃歇骄。"], "notes": "", "page": null}]}, {"id": "p128", "title": "小戎", "section": "国风", "group": "秦风", "intro": "《小戎》收于《诗经·国风·秦风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "小戎俴收，五楘梁辀。游环胁驱，阴靷鋈续。文茵畅毂，驾我骐馵。", "sentences": ["小戎俴收，五楘梁辀。", "游环胁驱，阴靷鋈续。", "文茵畅毂，驾我骐馵。"], "notes": "", "page": null}, {"text": "言念君子，温其如玉。在其板屋，乱我心曲。", "sentences": ["言念君子，温其如玉。", "在其板屋，乱我心曲。"], "notes": "", "page": null}, {"text": "四牡孔阜，六辔在手。骐骝是中，騧骊是骖。龙盾之合，鋈以觼軜。", "sentences": ["四牡孔阜，六辔在手。", "骐骝是中，騧骊是骖。", "龙盾之合，鋈以觼軜。"], "notes": "", "page": null}, {"text": "言念君子，温其在邑。方何为期？胡然我念之！", "sentences": ["言念君子，温其在邑。", "方何为期？", "胡然我念之！"], "notes": "", "page": null}, {"text": "俴驷孔群，厹矛鋈錞。蒙伐有苑，虎韔镂膺。交韔二弓，竹闭绲縢。", "sentences": ["俴驷孔群，厹矛鋈錞。", "蒙伐有苑，虎韔镂膺。", "交韔二弓，竹闭绲縢。"], "notes": "", "page": null}, {"text": "言念君子，载寝载兴。厌厌良人，秩秩德音。", "sentences": ["言念君子，载寝载兴。", "厌厌良人，秩秩德音。"], "notes": "", "page": null}]}, {"id": "p129", "title": "蒹葭", "section": "国风", "group": "秦风", "intro": "《蒹葭》收于《诗经·国风·秦风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "蒹葭苍苍，白露为霜。所谓伊人，在水一方。溯洄从之，道阻且长。溯游从之，宛在水中央。", "sentences": ["蒹葭苍苍，白露为霜。", "所谓伊人，在水一方。", "溯洄从之，道阻且长。", "溯游从之，宛在水中央。"], "notes": "以下为本项目编写的简短示例，并非原书注释。\n\n蒹、葭：两种水边植物的名称。\n苍苍：描写草木繁盛的样子。\n伊人：诗中思念的那个人。", "page": null}, {"text": "蒹葭萋萋，白露未晞。所谓伊人，在水之湄。溯洄从之，道阻且跻。溯游从之，宛在水中坻。", "sentences": ["蒹葭萋萋，白露未晞。", "所谓伊人，在水之湄。", "溯洄从之，道阻且跻。", "溯游从之，宛在水中坻。"], "notes": "", "page": null}, {"text": "蒹葭采采，白露未已。所谓伊人，在水之涘。溯洄从之，道阻且右。溯游从之，宛在水中沚。", "sentences": ["蒹葭采采，白露未已。", "所谓伊人，在水之涘。", "溯洄从之，道阻且右。", "溯游从之，宛在水中沚。"], "notes": "", "page": null}]}, {"id": "p130", "title": "终南", "section": "国风", "group": "秦风", "intro": "《终南》收于《诗经·国风·秦风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "终南何有？有条有梅。君子至止，锦衣狐裘。颜如渥丹，其君也哉！", "sentences": ["终南何有？", "有条有梅。", "君子至止，锦衣狐裘。", "颜如渥丹，其君也哉！"], "notes": "", "page": null}, {"text": "终南何有？有纪有堂。君子至止，黻衣绣裳。佩玉将将，寿考不忘！", "sentences": ["终南何有？", "有纪有堂。", "君子至止，黻衣绣裳。", "佩玉将将，寿考不忘！"], "notes": "", "page": null}]}, {"id": "p131", "title": "黄鸟", "section": "国风", "group": "秦风", "intro": "《黄鸟》收于《诗经·国风·秦风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "交交黄鸟，止于棘。谁从穆公？子车奄息。维此奄息，百夫之特。", "sentences": ["交交黄鸟，止于棘。", "谁从穆公？", "子车奄息。", "维此奄息，百夫之特。"], "notes": "", "page": null}, {"text": "临其穴，惴惴其栗。彼苍者天，歼我良人！如可赎兮，人百其身！", "sentences": ["临其穴，惴惴其栗。", "彼苍者天，歼我良人！", "如可赎兮，人百其身！"], "notes": "", "page": null}, {"text": "交交黄鸟，止于桑。谁从穆公？子车仲行。维此仲行，百夫之防。", "sentences": ["交交黄鸟，止于桑。", "谁从穆公？", "子车仲行。", "维此仲行，百夫之防。"], "notes": "", "page": null}, {"text": "临其穴，惴惴其栗。彼苍者天，歼我良人！如可赎兮，人百其身！", "sentences": ["临其穴，惴惴其栗。", "彼苍者天，歼我良人！", "如可赎兮，人百其身！"], "notes": "", "page": null}, {"text": "交交黄鸟，止于楚。谁从穆公？子车针虎。维此针虎，百夫之御。", "sentences": ["交交黄鸟，止于楚。", "谁从穆公？", "子车针虎。", "维此针虎，百夫之御。"], "notes": "", "page": null}, {"text": "临其穴，惴惴其栗。彼苍者天，歼我良人！如可赎兮，人百其身！", "sentences": ["临其穴，惴惴其栗。", "彼苍者天，歼我良人！", "如可赎兮，人百其身！"], "notes": "", "page": null}]}, {"id": "p132", "title": "晨风", "section": "国风", "group": "秦风", "intro": "《晨风》收于《诗经·国风·秦风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "鴥彼晨风，郁彼北林。未见君子，忧心钦钦。如何如何，忘我实多！", "sentences": ["鴥彼晨风，郁彼北林。", "未见君子，忧心钦钦。", "如何如何，忘我实多！"], "notes": "", "page": null}, {"text": "山有苞栎，隰有六駮。未见君子，忧心靡乐。如何如何，忘我实多！", "sentences": ["山有苞栎，隰有六駮。", "未见君子，忧心靡乐。", "如何如何，忘我实多！"], "notes": "", "page": null}, {"text": "山有苞棣，隰有树檖。未见君子，忧心如醉。如何如何，忘我实多！", "sentences": ["山有苞棣，隰有树檖。", "未见君子，忧心如醉。", "如何如何，忘我实多！"], "notes": "", "page": null}]}, {"id": "p133", "title": "无衣", "section": "国风", "group": "秦风", "intro": "《无衣》收于《诗经·国风·秦风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "岂曰无衣？与子同袍。王于兴师，修我戈矛。与子同仇！", "sentences": ["岂曰无衣？", "与子同袍。", "王于兴师，修我戈矛。", "与子同仇！"], "notes": "", "page": null}, {"text": "岂曰无衣？与子同泽。王于兴师，修我矛戟。与子偕作！", "sentences": ["岂曰无衣？", "与子同泽。", "王于兴师，修我矛戟。", "与子偕作！"], "notes": "", "page": null}, {"text": "岂曰无衣？与子同裳。王于兴师，修我甲兵。与子偕行！", "sentences": ["岂曰无衣？", "与子同裳。", "王于兴师，修我甲兵。", "与子偕行！"], "notes": "", "page": null}]}, {"id": "p134", "title": "渭阳", "section": "国风", "group": "秦风", "intro": "《渭阳》收于《诗经·国风·秦风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "我送舅氏，曰至渭阳。何以赠之？路车乘黄。", "sentences": ["我送舅氏，曰至渭阳。", "何以赠之？", "路车乘黄。"], "notes": "", "page": null}, {"text": "我送舅氏，悠悠我思。何以赠之？琼瑰玉佩。", "sentences": ["我送舅氏，悠悠我思。", "何以赠之？", "琼瑰玉佩。"], "notes": "", "page": null}]}, {"id": "p135", "title": "权舆", "section": "国风", "group": "秦风", "intro": "《权舆》收于《诗经·国风·秦风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "于我乎，夏屋渠渠，今也每食无余。于嗟乎，不承权舆！", "sentences": ["于我乎，夏屋渠渠，今也每食无余。", "于嗟乎，不承权舆！"], "notes": "", "page": null}, {"text": "于我乎，每食四簋，今也每食不饱。于嗟乎，不承权舆！", "sentences": ["于我乎，每食四簋，今也每食不饱。", "于嗟乎，不承权舆！"], "notes": "", "page": null}]}, {"id": "p136", "title": "宛丘", "section": "国风", "group": "陈风", "intro": "《宛丘》收于《诗经·国风·陈风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "子之汤兮，宛丘之上兮。洵有情兮，而无望兮。", "sentences": ["子之汤兮，宛丘之上兮。", "洵有情兮，而无望兮。"], "notes": "", "page": null}, {"text": "坎其击鼓，宛丘之下。无冬无夏，值其鹭羽。", "sentences": ["坎其击鼓，宛丘之下。", "无冬无夏，值其鹭羽。"], "notes": "", "page": null}, {"text": "坎其击缶，宛丘之道。无冬无夏，值其鹭翿。", "sentences": ["坎其击缶，宛丘之道。", "无冬无夏，值其鹭翿。"], "notes": "", "page": null}]}, {"id": "p137", "title": "东门之枌", "section": "国风", "group": "陈风", "intro": "《东门之枌》收于《诗经·国风·陈风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "东门之枌，宛丘之栩。子仲之子，婆娑其下。", "sentences": ["东门之枌，宛丘之栩。", "子仲之子，婆娑其下。"], "notes": "", "page": null}, {"text": "穀旦于差，南方之原。不绩其麻，市也婆娑。", "sentences": ["穀旦于差，南方之原。", "不绩其麻，市也婆娑。"], "notes": "", "page": null}, {"text": "穀旦于逝，越以鬷迈。视尔如荍，贻我握椒。", "sentences": ["穀旦于逝，越以鬷迈。", "视尔如荍，贻我握椒。"], "notes": "", "page": null}]}, {"id": "p138", "title": "衡门", "section": "国风", "group": "陈风", "intro": "《衡门》收于《诗经·国风·陈风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "衡门之下，可以栖迟。泌之洋洋，可以乐饥。", "sentences": ["衡门之下，可以栖迟。", "泌之洋洋，可以乐饥。"], "notes": "", "page": null}, {"text": "岂其食鱼，必河之鲂？岂其取妻，必齐之姜？", "sentences": ["岂其食鱼，必河之鲂？", "岂其取妻，必齐之姜？"], "notes": "", "page": null}, {"text": "岂其食鱼，必河之鲤？岂其取妻，必宋之子？", "sentences": ["岂其食鱼，必河之鲤？", "岂其取妻，必宋之子？"], "notes": "", "page": null}]}, {"id": "p139", "title": "东门之池", "section": "国风", "group": "陈风", "intro": "《东门之池》收于《诗经·国风·陈风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "东门之池，可以沤麻。彼美淑姬，可与晤歌。", "sentences": ["东门之池，可以沤麻。", "彼美淑姬，可与晤歌。"], "notes": "", "page": null}, {"text": "东门之池，可以沤纻。彼美淑姬，可与晤语。", "sentences": ["东门之池，可以沤纻。", "彼美淑姬，可与晤语。"], "notes": "", "page": null}, {"text": "东门之池，可以沤菅。彼美淑姬，可与晤言。", "sentences": ["东门之池，可以沤菅。", "彼美淑姬，可与晤言。"], "notes": "", "page": null}]}, {"id": "p140", "title": "东门之杨", "section": "国风", "group": "陈风", "intro": "《东门之杨》收于《诗经·国风·陈风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "东门之杨，其叶牂牂。昏以为期，明星煌煌。", "sentences": ["东门之杨，其叶牂牂。", "昏以为期，明星煌煌。"], "notes": "", "page": null}, {"text": "东门之杨，其叶肺肺。昏以为期，明星晢晢。", "sentences": ["东门之杨，其叶肺肺。", "昏以为期，明星晢晢。"], "notes": "", "page": null}]}, {"id": "p141", "title": "墓门", "section": "国风", "group": "陈风", "intro": "《墓门》收于《诗经·国风·陈风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "墓门有棘，斧以斯之。夫也不良，国人知之。知而不已，谁昔然矣。", "sentences": ["墓门有棘，斧以斯之。", "夫也不良，国人知之。", "知而不已，谁昔然矣。"], "notes": "", "page": null}, {"text": "墓门有梅，有鸮萃止。夫也不良，歌以讯之。讯予不顾，颠倒思予。", "sentences": ["墓门有梅，有鸮萃止。", "夫也不良，歌以讯之。", "讯予不顾，颠倒思予。"], "notes": "", "page": null}]}, {"id": "p142", "title": "防有鹊巢", "section": "国风", "group": "陈风", "intro": "《防有鹊巢》收于《诗经·国风·陈风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "防有鹊巢，邛有旨苕。谁侜予美？心焉忉忉。", "sentences": ["防有鹊巢，邛有旨苕。", "谁侜予美？", "心焉忉忉。"], "notes": "", "page": null}, {"text": "中唐有甓，邛有旨鷊。谁侜予美？心焉惕惕。", "sentences": ["中唐有甓，邛有旨鷊。", "谁侜予美？", "心焉惕惕。"], "notes": "", "page": null}]}, {"id": "p143", "title": "月出", "section": "国风", "group": "陈风", "intro": "《月出》收于《诗经·国风·陈风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "月出皎兮。佼人僚兮。舒窈纠兮。劳心悄兮。", "sentences": ["月出皎兮。", "佼人僚兮。", "舒窈纠兮。", "劳心悄兮。"], "notes": "", "page": null}, {"text": "月出皓兮。佼人懰兮。舒忧受兮。劳心慅兮。", "sentences": ["月出皓兮。", "佼人懰兮。", "舒忧受兮。", "劳心慅兮。"], "notes": "", "page": null}, {"text": "月出照兮。佼人燎兮。舒夭绍兮。劳心惨兮。", "sentences": ["月出照兮。", "佼人燎兮。", "舒夭绍兮。", "劳心惨兮。"], "notes": "", "page": null}]}, {"id": "p144", "title": "株林", "section": "国风", "group": "陈风", "intro": "《株林》收于《诗经·国风·陈风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "胡为乎株林？从夏南！匪适株林，从夏南！", "sentences": ["胡为乎株林？", "从夏南！", "匪适株林，从夏南！"], "notes": "", "page": null}, {"text": "驾我乘马，说于株野。乘我乘驹，朝食于株！", "sentences": ["驾我乘马，说于株野。", "乘我乘驹，朝食于株！"], "notes": "", "page": null}]}, {"id": "p145", "title": "泽陂", "section": "国风", "group": "陈风", "intro": "《泽陂》收于《诗经·国风·陈风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "彼泽之陂，有蒲与荷。有美一人，伤如之何？寤寐无为，涕泗滂沱。", "sentences": ["彼泽之陂，有蒲与荷。", "有美一人，伤如之何？", "寤寐无为，涕泗滂沱。"], "notes": "", "page": null}, {"text": "彼泽之陂，有蒲与蕳。有美一人，硕大且卷。寤寐无为，中心悁悁。", "sentences": ["彼泽之陂，有蒲与蕳。", "有美一人，硕大且卷。", "寤寐无为，中心悁悁。"], "notes": "", "page": null}, {"text": "彼泽之陂，有蒲菡萏。有美一人，硕大且俨。寤寐无为，辗转伏枕。", "sentences": ["彼泽之陂，有蒲菡萏。", "有美一人，硕大且俨。", "寤寐无为，辗转伏枕。"], "notes": "", "page": null}]}, {"id": "p146", "title": "羔裘", "section": "国风", "group": "桧风", "intro": "《羔裘》收于《诗经·国风·桧风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "羔裘逍遥，狐裘以朝。岂不尔思？劳心忉忉。", "sentences": ["羔裘逍遥，狐裘以朝。", "岂不尔思？", "劳心忉忉。"], "notes": "", "page": null}, {"text": "羔裘翱翔，狐裘在堂。岂不尔思？我心忧伤。", "sentences": ["羔裘翱翔，狐裘在堂。", "岂不尔思？", "我心忧伤。"], "notes": "", "page": null}, {"text": "羔裘如膏，日出有曜。岂不尔思？中心是悼。", "sentences": ["羔裘如膏，日出有曜。", "岂不尔思？", "中心是悼。"], "notes": "", "page": null}]}, {"id": "p147", "title": "素冠", "section": "国风", "group": "桧风", "intro": "《素冠》收于《诗经·国风·桧风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "庶见素冠兮，棘人栾栾兮。劳心慱慱兮。", "sentences": ["庶见素冠兮，棘人栾栾兮。", "劳心慱慱兮。"], "notes": "", "page": null}, {"text": "庶见素衣兮，我心伤悲兮。聊与子同归兮。", "sentences": ["庶见素衣兮，我心伤悲兮。", "聊与子同归兮。"], "notes": "", "page": null}, {"text": "庶见素韠兮，我心蕴结兮。聊与子如一兮。", "sentences": ["庶见素韠兮，我心蕴结兮。", "聊与子如一兮。"], "notes": "", "page": null}]}, {"id": "p148", "title": "隰有苌楚", "section": "国风", "group": "桧风", "intro": "《隰有苌楚》收于《诗经·国风·桧风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "隰有苌楚，猗傩其枝，夭之沃沃，乐子之无知。", "sentences": ["隰有苌楚，猗傩其枝，夭之沃沃，乐子之无知。"], "notes": "", "page": null}, {"text": "隰有苌楚，猗傩其华，夭之沃沃。乐子之无家。", "sentences": ["隰有苌楚，猗傩其华，夭之沃沃。", "乐子之无家。"], "notes": "", "page": null}, {"text": "隰有苌楚，猗傩其实，夭之沃沃。乐子之无室。", "sentences": ["隰有苌楚，猗傩其实，夭之沃沃。", "乐子之无室。"], "notes": "", "page": null}]}, {"id": "p149", "title": "匪风", "section": "国风", "group": "桧风", "intro": "《匪风》收于《诗经·国风·桧风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "匪风发兮，匪车偈兮。顾瞻周道，中心怛兮。", "sentences": ["匪风发兮，匪车偈兮。", "顾瞻周道，中心怛兮。"], "notes": "", "page": null}, {"text": "匪风飘兮，匪车嘌兮。顾瞻周道，中心吊兮。", "sentences": ["匪风飘兮，匪车嘌兮。", "顾瞻周道，中心吊兮。"], "notes": "", "page": null}, {"text": "谁能亨鱼？溉之釜鬵。谁将西归？怀之好音。", "sentences": ["谁能亨鱼？", "溉之釜鬵。", "谁将西归？", "怀之好音。"], "notes": "", "page": null}]}, {"id": "p150", "title": "蜉蝣", "section": "国风", "group": "曹风", "intro": "《蜉蝣》收于《诗经·国风·曹风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "蜉蝣之羽，衣裳楚楚。心之忧矣，于我归处。", "sentences": ["蜉蝣之羽，衣裳楚楚。", "心之忧矣，于我归处。"], "notes": "", "page": null}, {"text": "蜉蝣之翼，采采衣服。心之忧矣，于我归息。", "sentences": ["蜉蝣之翼，采采衣服。", "心之忧矣，于我归息。"], "notes": "", "page": null}, {"text": "蜉蝣掘阅，麻衣如雪。心之忧矣，于我归说。", "sentences": ["蜉蝣掘阅，麻衣如雪。", "心之忧矣，于我归说。"], "notes": "", "page": null}]}, {"id": "p151", "title": "候人", "section": "国风", "group": "曹风", "intro": "《候人》收于《诗经·国风·曹风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "彼候人兮，何戈与祋。彼其之子，三百赤芾。", "sentences": ["彼候人兮，何戈与祋。", "彼其之子，三百赤芾。"], "notes": "", "page": null}, {"text": "维鹈在梁，不濡其翼。彼其之子，不称其服。", "sentences": ["维鹈在梁，不濡其翼。", "彼其之子，不称其服。"], "notes": "", "page": null}, {"text": "维鹈在梁，不濡其咮。彼其之子，不遂其媾。", "sentences": ["维鹈在梁，不濡其咮。", "彼其之子，不遂其媾。"], "notes": "", "page": null}, {"text": "荟兮蔚兮，南山朝隮。婉兮娈兮，季女斯饥。", "sentences": ["荟兮蔚兮，南山朝隮。", "婉兮娈兮，季女斯饥。"], "notes": "", "page": null}]}, {"id": "p152", "title": "鳲鸠", "section": "国风", "group": "曹风", "intro": "《鳲鸠》收于《诗经·国风·曹风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "鳲鸠在桑，其子七兮。淑人君子，其仪一兮。其仪一兮，心如结兮。", "sentences": ["鳲鸠在桑，其子七兮。", "淑人君子，其仪一兮。", "其仪一兮，心如结兮。"], "notes": "", "page": null}, {"text": "鳲鸠在桑，其子在梅。淑人君子，其带伊丝。其带伊丝，其弁伊骐。", "sentences": ["鳲鸠在桑，其子在梅。", "淑人君子，其带伊丝。", "其带伊丝，其弁伊骐。"], "notes": "", "page": null}, {"text": "鳲鸠在桑，其子在棘。淑人君子，其仪不忒。其仪不忒，正是四国。", "sentences": ["鳲鸠在桑，其子在棘。", "淑人君子，其仪不忒。", "其仪不忒，正是四国。"], "notes": "", "page": null}, {"text": "鳲鸠在桑，其子在榛。淑人君子，正是国人，正是国人。胡不万年？", "sentences": ["鳲鸠在桑，其子在榛。", "淑人君子，正是国人，正是国人。", "胡不万年？"], "notes": "", "page": null}]}, {"id": "p153", "title": "下泉", "section": "国风", "group": "曹风", "intro": "《下泉》收于《诗经·国风·曹风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "冽彼下泉，浸彼苞稂。忾我寤叹，念彼周京。", "sentences": ["冽彼下泉，浸彼苞稂。", "忾我寤叹，念彼周京。"], "notes": "", "page": null}, {"text": "冽彼下泉，浸彼苞萧。忾我寤叹，念彼京周。", "sentences": ["冽彼下泉，浸彼苞萧。", "忾我寤叹，念彼京周。"], "notes": "", "page": null}, {"text": "冽彼下泉，浸彼苞蓍。忾我寤叹，念彼京师。", "sentences": ["冽彼下泉，浸彼苞蓍。", "忾我寤叹，念彼京师。"], "notes": "", "page": null}, {"text": "芃芃黍苗，阴雨膏之。四国有王，郇伯劳之。", "sentences": ["芃芃黍苗，阴雨膏之。", "四国有王，郇伯劳之。"], "notes": "", "page": null}]}, {"id": "p154", "title": "七月", "section": "国风", "group": "豳风", "intro": "《七月》收于《诗经·国风·豳风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "七月流火，九月授衣。一之日觱发，二之日栗烈。无衣无褐，何以卒岁？", "sentences": ["七月流火，九月授衣。", "一之日觱发，二之日栗烈。", "无衣无褐，何以卒岁？"], "notes": "", "page": null}, {"text": "三之日于耜，四之日举趾。同我妇子，馌彼南亩。田畯至喜。", "sentences": ["三之日于耜，四之日举趾。", "同我妇子，馌彼南亩。", "田畯至喜。"], "notes": "", "page": null}, {"text": "七月流火，九月授衣。春日载阳，有鸣仓庚。女执懿筐，遵彼微行，爰求柔桑。", "sentences": ["七月流火，九月授衣。", "春日载阳，有鸣仓庚。", "女执懿筐，遵彼微行，爰求柔桑。"], "notes": "", "page": null}, {"text": "春日迟迟，采蘩祁祁。女心伤悲，殆及公子同归。", "sentences": ["春日迟迟，采蘩祁祁。", "女心伤悲，殆及公子同归。"], "notes": "", "page": null}, {"text": "七月流火，八月萑苇。蚕月条桑，取彼斧斨。以伐远扬，猗彼女桑。", "sentences": ["七月流火，八月萑苇。", "蚕月条桑，取彼斧斨。", "以伐远扬，猗彼女桑。"], "notes": "", "page": null}, {"text": "七月鸣鵙，八月载绩。载玄载黄，我朱孔阳，为公子裳。", "sentences": ["七月鸣鵙，八月载绩。", "载玄载黄，我朱孔阳，为公子裳。"], "notes": "", "page": null}, {"text": "四月秀葽，五月鸣蜩。八月其获，十月陨萚。一之日于貉，取彼狐狸，为公子裘。", "sentences": ["四月秀葽，五月鸣蜩。", "八月其获，十月陨萚。", "一之日于貉，取彼狐狸，为公子裘。"], "notes": "", "page": null}, {"text": "二之日其同，载缵武功。言私其豵，献豜于公。", "sentences": ["二之日其同，载缵武功。", "言私其豵，献豜于公。"], "notes": "", "page": null}, {"text": "五月斯螽动股，六月莎鸡振羽。七月在野，八月在宇，九月在户，十月蟋蟀，入我床下。", "sentences": ["五月斯螽动股，六月莎鸡振羽。", "七月在野，八月在宇，九月在户，十月蟋蟀，入我床下。"], "notes": "", "page": null}, {"text": "穹窒熏鼠，塞向墐户。嗟我妇子，曰为改岁，入此室处。", "sentences": ["穹窒熏鼠，塞向墐户。", "嗟我妇子，曰为改岁，入此室处。"], "notes": "", "page": null}, {"text": "六月食郁及薁，七月亨葵及菽。八月剥枣，十月获稻。为此春酒，以介眉寿。", "sentences": ["六月食郁及薁，七月亨葵及菽。", "八月剥枣，十月获稻。", "为此春酒，以介眉寿。"], "notes": "", "page": null}, {"text": "七月食瓜，八月断壶，九月叔苴，采荼薪樗。食我农夫。", "sentences": ["七月食瓜，八月断壶，九月叔苴，采荼薪樗。", "食我农夫。"], "notes": "", "page": null}, {"text": "九月筑场圃，十月纳禾稼。黍稷重穋，禾麻菽麦。嗟我农夫，我稼既同，上入执宫功。", "sentences": ["九月筑场圃，十月纳禾稼。", "黍稷重穋，禾麻菽麦。", "嗟我农夫，我稼既同，上入执宫功。"], "notes": "", "page": null}, {"text": "昼尔于茅，宵尔索綯，亟其乘屋，其始播百谷。", "sentences": ["昼尔于茅，宵尔索綯，亟其乘屋，其始播百谷。"], "notes": "", "page": null}, {"text": "二之日凿冰冲冲，三之日纳于凌阴。四之日其蚤，献羔祭韭。九月肃霜，十月涤场。", "sentences": ["二之日凿冰冲冲，三之日纳于凌阴。", "四之日其蚤，献羔祭韭。", "九月肃霜，十月涤场。"], "notes": "", "page": null}, {"text": "朋酒斯飨，曰杀羔羊，跻彼公堂。称彼兕觥：万寿无疆！", "sentences": ["朋酒斯飨，曰杀羔羊，跻彼公堂。", "称彼兕觥：万寿无疆！"], "notes": "", "page": null}]}, {"id": "p155", "title": "鸱鸮", "section": "国风", "group": "豳风", "intro": "《鸱鸮》收于《诗经·国风·豳风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "鸱鸮鸱鸮，既取我子，无毁我室。恩斯勤斯，鬻子之闵斯。", "sentences": ["鸱鸮鸱鸮，既取我子，无毁我室。", "恩斯勤斯，鬻子之闵斯。"], "notes": "", "page": null}, {"text": "迨天之未阴雨，彻彼桑土，绸缪牖户。今女下民，或敢侮予？", "sentences": ["迨天之未阴雨，彻彼桑土，绸缪牖户。", "今女下民，或敢侮予？"], "notes": "", "page": null}, {"text": "予手拮据，予所捋荼。予所蓄租，予口卒瘏，曰予未有室家。", "sentences": ["予手拮据，予所捋荼。", "予所蓄租，予口卒瘏，曰予未有室家。"], "notes": "", "page": null}, {"text": "予羽谯谯，予尾翛翛，予室翘翘。风雨所漂摇，予维音哓哓！", "sentences": ["予羽谯谯，予尾翛翛，予室翘翘。", "风雨所漂摇，予维音哓哓！"], "notes": "", "page": null}]}, {"id": "p156", "title": "东山", "section": "国风", "group": "豳风", "intro": "《东山》收于《诗经·国风·豳风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "我徂东山，慆慆不归。我来自东，零雨其濛。我东曰归，我心西悲。", "sentences": ["我徂东山，慆慆不归。", "我来自东，零雨其濛。", "我东曰归，我心西悲。"], "notes": "", "page": null}, {"text": "制彼裳衣，勿士行枚。蜎蜎者蠋，烝在桑野。敦彼独宿，亦在车下。", "sentences": ["制彼裳衣，勿士行枚。", "蜎蜎者蠋，烝在桑野。", "敦彼独宿，亦在车下。"], "notes": "", "page": null}, {"text": "我徂东山，慆慆不归。我来自东，零雨其濛。果臝之实，亦施于宇。", "sentences": ["我徂东山，慆慆不归。", "我来自东，零雨其濛。", "果臝之实，亦施于宇。"], "notes": "", "page": null}, {"text": "伊威在室，蠨蛸在户。町畽鹿场，熠耀宵行。不可畏也，伊可怀也。", "sentences": ["伊威在室，蠨蛸在户。", "町畽鹿场，熠耀宵行。", "不可畏也，伊可怀也。"], "notes": "", "page": null}, {"text": "我徂东山，慆慆不归。我来自东，零雨其濛。鹳鸣于垤，妇叹于室。", "sentences": ["我徂东山，慆慆不归。", "我来自东，零雨其濛。", "鹳鸣于垤，妇叹于室。"], "notes": "", "page": null}, {"text": "洒扫穹窒，我征聿至。有敦瓜苦，烝在栗薪。自我不见，于今三年。", "sentences": ["洒扫穹窒，我征聿至。", "有敦瓜苦，烝在栗薪。", "自我不见，于今三年。"], "notes": "", "page": null}, {"text": "我徂东山，慆慆不归。我来自东，零雨其濛。仓庚于飞，熠耀其羽。", "sentences": ["我徂东山，慆慆不归。", "我来自东，零雨其濛。", "仓庚于飞，熠耀其羽。"], "notes": "", "page": null}, {"text": "之子于归，皇驳其马。亲结其缡，九十其仪。其新孔嘉，其旧如之何？", "sentences": ["之子于归，皇驳其马。", "亲结其缡，九十其仪。", "其新孔嘉，其旧如之何？"], "notes": "", "page": null}]}, {"id": "p157", "title": "破斧", "section": "国风", "group": "豳风", "intro": "《破斧》收于《诗经·国风·豳风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "既破我斧，又缺我斨。周公东征，四国是皇。哀我人斯，亦孔之将。", "sentences": ["既破我斧，又缺我斨。", "周公东征，四国是皇。", "哀我人斯，亦孔之将。"], "notes": "", "page": null}, {"text": "既破我斧，又缺我锜。周公东征，四国是遒。哀我人斯，亦孔之嘉。", "sentences": ["既破我斧，又缺我锜。", "周公东征，四国是遒。", "哀我人斯，亦孔之嘉。"], "notes": "", "page": null}, {"text": "既破我斧，又缺我銶。周公东征，四国是遒。哀我人斯，亦孔之休。", "sentences": ["既破我斧，又缺我銶。", "周公东征，四国是遒。", "哀我人斯，亦孔之休。"], "notes": "", "page": null}]}, {"id": "p158", "title": "伐柯", "section": "国风", "group": "豳风", "intro": "《伐柯》收于《诗经·国风·豳风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "伐柯如何？匪斧不克。取妻如何？匪媒不得。", "sentences": ["伐柯如何？", "匪斧不克。", "取妻如何？", "匪媒不得。"], "notes": "", "page": null}, {"text": "伐柯伐柯，其则不远。我觏之子，笾豆有践。", "sentences": ["伐柯伐柯，其则不远。", "我觏之子，笾豆有践。"], "notes": "", "page": null}]}, {"id": "p159", "title": "九罭", "section": "国风", "group": "豳风", "intro": "《九罭》收于《诗经·国风·豳风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "九罭之鱼，鳟鲂。我觏之子，衮衣绣裳。", "sentences": ["九罭之鱼，鳟鲂。", "我觏之子，衮衣绣裳。"], "notes": "", "page": null}, {"text": "鸿飞遵渚，公归无所，于女信处。鸿飞遵六，公归不复，于女信宿。", "sentences": ["鸿飞遵渚，公归无所，于女信处。", "鸿飞遵六，公归不复，于女信宿。"], "notes": "", "page": null}, {"text": "是以有衮衣兮，无以我公归兮，无使我心悲兮。", "sentences": ["是以有衮衣兮，无以我公归兮，无使我心悲兮。"], "notes": "", "page": null}]}, {"id": "p160", "title": "狼跋", "section": "国风", "group": "豳风", "intro": "《狼跋》收于《诗经·国风·豳风》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "狼跋其胡，载疐其尾。公孙硕肤，赤舄几几。", "sentences": ["狼跋其胡，载疐其尾。", "公孙硕肤，赤舄几几。"], "notes": "", "page": null}, {"text": "狼疐其尾，载跋其胡。公孙硕肤，德音不瑕？", "sentences": ["狼疐其尾，载跋其胡。", "公孙硕肤，德音不瑕？"], "notes": "", "page": null}]}, {"id": "p161", "title": "鹿鸣", "section": "小雅", "group": "鹿鸣之什", "intro": "《鹿鸣》收于《诗经·小雅·鹿鸣之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。吹笙鼓簧，承筐是将。人之好我，示我周行。", "sentences": ["呦呦鹿鸣，食野之苹。", "我有嘉宾，鼓瑟吹笙。", "吹笙鼓簧，承筐是将。", "人之好我，示我周行。"], "notes": "", "page": null}, {"text": "呦呦鹿鸣，食野之蒿。我有嘉宾，德音孔昭。视民不恌，君子是则是效。我有旨酒，嘉宾式燕以敖。", "sentences": ["呦呦鹿鸣，食野之蒿。", "我有嘉宾，德音孔昭。", "视民不恌，君子是则是效。", "我有旨酒，嘉宾式燕以敖。"], "notes": "", "page": null}, {"text": "呦呦鹿鸣，食野之芩。我有嘉宾，鼓瑟鼓琴。鼓瑟鼓琴，和乐且湛。我有旨酒，以燕乐嘉宾之心。", "sentences": ["呦呦鹿鸣，食野之芩。", "我有嘉宾，鼓瑟鼓琴。", "鼓瑟鼓琴，和乐且湛。", "我有旨酒，以燕乐嘉宾之心。"], "notes": "", "page": null}]}, {"id": "p162", "title": "四牡", "section": "小雅", "group": "鹿鸣之什", "intro": "《四牡》收于《诗经·小雅·鹿鸣之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "四牡騑騑，周道倭迟。岂不怀归？王事靡盬，我心伤悲。", "sentences": ["四牡騑騑，周道倭迟。", "岂不怀归？", "王事靡盬，我心伤悲。"], "notes": "", "page": null}, {"text": "四牡騑騑，啴啴骆马。岂不怀归？王事靡盬，不遑启处。", "sentences": ["四牡騑騑，啴啴骆马。", "岂不怀归？", "王事靡盬，不遑启处。"], "notes": "", "page": null}, {"text": "翩翩者鵻，载飞载下，集于苞栩。王事靡盬，不遑将父。", "sentences": ["翩翩者鵻，载飞载下，集于苞栩。", "王事靡盬，不遑将父。"], "notes": "", "page": null}, {"text": "翩翩者鵻，载飞载止，集于苞杞。王事靡盬，不遑将母。", "sentences": ["翩翩者鵻，载飞载止，集于苞杞。", "王事靡盬，不遑将母。"], "notes": "", "page": null}, {"text": "驾彼四骆，载骤骎骎。岂不怀归？是用作歌，将母来谂。", "sentences": ["驾彼四骆，载骤骎骎。", "岂不怀归？", "是用作歌，将母来谂。"], "notes": "", "page": null}]}, {"id": "p163", "title": "皇皇者华", "section": "小雅", "group": "鹿鸣之什", "intro": "《皇皇者华》收于《诗经·小雅·鹿鸣之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "皇皇者华，于彼原隰。駪駪征夫，每怀靡及。", "sentences": ["皇皇者华，于彼原隰。", "駪駪征夫，每怀靡及。"], "notes": "", "page": null}, {"text": "我马维驹，六辔如濡。载驰载驱，周爰咨诹。", "sentences": ["我马维驹，六辔如濡。", "载驰载驱，周爰咨诹。"], "notes": "", "page": null}, {"text": "我马维骐，六辔如丝。载驰载驱，周爰咨谋。", "sentences": ["我马维骐，六辔如丝。", "载驰载驱，周爰咨谋。"], "notes": "", "page": null}, {"text": "我马维骆，六辔沃若。载驰载驱，周爰咨度。", "sentences": ["我马维骆，六辔沃若。", "载驰载驱，周爰咨度。"], "notes": "", "page": null}, {"text": "我马维骃，六辔既均。载驰载驱，周爰咨询。", "sentences": ["我马维骃，六辔既均。", "载驰载驱，周爰咨询。"], "notes": "", "page": null}]}, {"id": "p164", "title": "棠棣", "section": "小雅", "group": "鹿鸣之什", "intro": "《棠棣》收于《诗经·小雅·鹿鸣之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "棠棣之华，鄂不韡韡。凡今之人，莫如兄弟。", "sentences": ["棠棣之华，鄂不韡韡。", "凡今之人，莫如兄弟。"], "notes": "", "page": null}, {"text": "死丧之威，兄弟孔怀。原隰裒矣，兄弟求矣。", "sentences": ["死丧之威，兄弟孔怀。", "原隰裒矣，兄弟求矣。"], "notes": "", "page": null}, {"text": "脊令在原，兄弟急难。每有良朋，况也永叹。", "sentences": ["脊令在原，兄弟急难。", "每有良朋，况也永叹。"], "notes": "", "page": null}, {"text": "兄弟阋于墙，外御其务。每有良朋，烝也无戎。", "sentences": ["兄弟阋于墙，外御其务。", "每有良朋，烝也无戎。"], "notes": "", "page": null}, {"text": "丧乱既平，既安且宁。虽有兄弟，不如友生？", "sentences": ["丧乱既平，既安且宁。", "虽有兄弟，不如友生？"], "notes": "", "page": null}, {"text": "傧尔笾豆，饮酒之饫。兄弟既具，和乐且孺。", "sentences": ["傧尔笾豆，饮酒之饫。", "兄弟既具，和乐且孺。"], "notes": "", "page": null}, {"text": "妻子好合，如鼓瑟琴。兄弟既翕，和乐且湛。", "sentences": ["妻子好合，如鼓瑟琴。", "兄弟既翕，和乐且湛。"], "notes": "", "page": null}, {"text": "宜尔室家，乐尔妻帑。是究是图，亶其然乎？", "sentences": ["宜尔室家，乐尔妻帑。", "是究是图，亶其然乎？"], "notes": "", "page": null}]}, {"id": "p165", "title": "伐木", "section": "小雅", "group": "鹿鸣之什", "intro": "《伐木》收于《诗经·小雅·鹿鸣之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "伐木丁丁，鸟鸣嘤嘤。出自幽谷，迁于乔木。嘤其鸣矣，求其友声。", "sentences": ["伐木丁丁，鸟鸣嘤嘤。", "出自幽谷，迁于乔木。", "嘤其鸣矣，求其友声。"], "notes": "", "page": null}, {"text": "相彼鸟矣，犹求友声。矧伊人矣，不求友生？神之听之，终和且平。", "sentences": ["相彼鸟矣，犹求友声。", "矧伊人矣，不求友生？", "神之听之，终和且平。"], "notes": "", "page": null}, {"text": "伐木许许，酾酒有藇！既有肥羜，以速诸父。宁适不来，微我弗顾。", "sentences": ["伐木许许，酾酒有藇！", "既有肥羜，以速诸父。", "宁适不来，微我弗顾。"], "notes": "", "page": null}, {"text": "于粲洒扫，陈馈八簋。既有肥牡，以速诸舅。宁适不来，微我有咎。", "sentences": ["于粲洒扫，陈馈八簋。", "既有肥牡，以速诸舅。", "宁适不来，微我有咎。"], "notes": "", "page": null}, {"text": "伐木于阪，酾酒有衍。笾豆有践，兄弟无远。民之失德，乾餱以愆。", "sentences": ["伐木于阪，酾酒有衍。", "笾豆有践，兄弟无远。", "民之失德，乾餱以愆。"], "notes": "", "page": null}, {"text": "有酒湑我，无酒酤我。坎坎鼓我，蹲蹲舞我。迨我暇矣，饮此湑矣。", "sentences": ["有酒湑我，无酒酤我。", "坎坎鼓我，蹲蹲舞我。", "迨我暇矣，饮此湑矣。"], "notes": "", "page": null}]}, {"id": "p166", "title": "天保", "section": "小雅", "group": "鹿鸣之什", "intro": "《天保》收于《诗经·小雅·鹿鸣之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "天保定尔，亦孔之固。俾尔单厚，何福不除？俾尔多益，以莫不庶。", "sentences": ["天保定尔，亦孔之固。", "俾尔单厚，何福不除？", "俾尔多益，以莫不庶。"], "notes": "", "page": null}, {"text": "天保定尔，俾尔戬穀。罄无不宜，受天百禄。降尔遐福，维日不足。", "sentences": ["天保定尔，俾尔戬穀。", "罄无不宜，受天百禄。", "降尔遐福，维日不足。"], "notes": "", "page": null}, {"text": "天保定尔，以莫不兴。如山如阜，如冈如陵，如川之方至，以莫不增。", "sentences": ["天保定尔，以莫不兴。", "如山如阜，如冈如陵，如川之方至，以莫不增。"], "notes": "", "page": null}, {"text": "吉蠲为饎，是用孝享。禴祠烝尝，于公先王。君曰：卜尔，万寿无疆。", "sentences": ["吉蠲为饎，是用孝享。", "禴祠烝尝，于公先王。", "君曰：卜尔，万寿无疆。"], "notes": "", "page": null}, {"text": "神之吊矣，诒尔多福。民之质矣，日用饮食。群黎百姓，遍为尔德。", "sentences": ["神之吊矣，诒尔多福。", "民之质矣，日用饮食。", "群黎百姓，遍为尔德。"], "notes": "", "page": null}, {"text": "如月之恒，如日之升。如南山之寿，不骞不崩。如松柏之茂，无不尔或承。", "sentences": ["如月之恒，如日之升。", "如南山之寿，不骞不崩。", "如松柏之茂，无不尔或承。"], "notes": "", "page": null}]}, {"id": "p167", "title": "采薇", "section": "小雅", "group": "鹿鸣之什", "intro": "《采薇》收于《诗经·小雅·鹿鸣之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "采薇采薇，薇亦作止。曰归曰归，岁亦莫止。靡室靡家，玁狁之故。不遑启居，玁狁之故。", "sentences": ["采薇采薇，薇亦作止。", "曰归曰归，岁亦莫止。", "靡室靡家，玁狁之故。", "不遑启居，玁狁之故。"], "notes": "", "page": null}, {"text": "采薇采薇，薇亦柔止。曰归曰归，心亦忧止。忧心烈烈，载饥载渴。我戍未定，靡使归聘。", "sentences": ["采薇采薇，薇亦柔止。", "曰归曰归，心亦忧止。", "忧心烈烈，载饥载渴。", "我戍未定，靡使归聘。"], "notes": "", "page": null}, {"text": "采薇采薇，薇亦刚止。曰归曰归，岁亦阳止。王事靡盬，不遑启处。忧心孔疚，我行不来！", "sentences": ["采薇采薇，薇亦刚止。", "曰归曰归，岁亦阳止。", "王事靡盬，不遑启处。", "忧心孔疚，我行不来！"], "notes": "", "page": null}, {"text": "彼尔维何？维常之华。彼路斯何？君子之车。戎车既驾，四牡业业。岂敢定居？一月三捷。", "sentences": ["彼尔维何？", "维常之华。", "彼路斯何？", "君子之车。", "戎车既驾，四牡业业。", "岂敢定居？", "一月三捷。"], "notes": "", "page": null}, {"text": "驾彼四牡，四牡骙骙。君子所依，小人所腓。四牡翼翼，象弭鱼服。岂不日戒？玁狁孔棘！", "sentences": ["驾彼四牡，四牡骙骙。", "君子所依，小人所腓。", "四牡翼翼，象弭鱼服。", "岂不日戒？", "玁狁孔棘！"], "notes": "", "page": null}, {"text": "昔我往矣，杨柳依依。今我来思，雨雪霏霏。行道迟迟，载渴载饥。我心伤悲，莫知我哀！", "sentences": ["昔我往矣，杨柳依依。", "今我来思，雨雪霏霏。", "行道迟迟，载渴载饥。", "我心伤悲，莫知我哀！"], "notes": "", "page": null}]}, {"id": "p168", "title": "出车", "section": "小雅", "group": "鹿鸣之什", "intro": "《出车》收于《诗经·小雅·鹿鸣之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "我出我车，于彼牧矣。自天子所，谓我来矣。召彼仆夫，谓之载矣。王事多难，维其棘矣。", "sentences": ["我出我车，于彼牧矣。", "自天子所，谓我来矣。", "召彼仆夫，谓之载矣。", "王事多难，维其棘矣。"], "notes": "", "page": null}, {"text": "我出我车，于彼郊矣。设此旐矣，建彼旄矣。彼旟旐斯，胡不旆旆？忧心悄悄，仆夫况瘁。", "sentences": ["我出我车，于彼郊矣。", "设此旐矣，建彼旄矣。", "彼旟旐斯，胡不旆旆？", "忧心悄悄，仆夫况瘁。"], "notes": "", "page": null}, {"text": "王命南仲，往城于方。出车彭彭，旂旐央央。天子命我，城彼朔方。赫赫南仲，玁狁于襄。", "sentences": ["王命南仲，往城于方。", "出车彭彭，旂旐央央。", "天子命我，城彼朔方。", "赫赫南仲，玁狁于襄。"], "notes": "", "page": null}, {"text": "昔我往矣，黍稷方华。今我来思，雨雪载途。王事多难，不遑启居。岂不怀归？畏此简书。", "sentences": ["昔我往矣，黍稷方华。", "今我来思，雨雪载途。", "王事多难，不遑启居。", "岂不怀归？", "畏此简书。"], "notes": "", "page": null}, {"text": "喓喓草虫，趯趯阜螽。未见君子，忧心忡忡。既见君子，我心则降。赫赫南仲，薄伐西戎。", "sentences": ["喓喓草虫，趯趯阜螽。", "未见君子，忧心忡忡。", "既见君子，我心则降。", "赫赫南仲，薄伐西戎。"], "notes": "", "page": null}, {"text": "春日迟迟，卉木萋萋。仓庚喈喈，采蘩祁祁。执讯获丑，薄言还归。赫赫南仲，玁狁于夷。", "sentences": ["春日迟迟，卉木萋萋。", "仓庚喈喈，采蘩祁祁。", "执讯获丑，薄言还归。", "赫赫南仲，玁狁于夷。"], "notes": "", "page": null}]}, {"id": "p169", "title": "杕杜", "section": "小雅", "group": "鹿鸣之什", "intro": "《杕杜》收于《诗经·小雅·鹿鸣之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "有杕之杜，有睆其实。王事靡盬，继嗣我日。日月阳止，女心伤止，征夫遑止。", "sentences": ["有杕之杜，有睆其实。", "王事靡盬，继嗣我日。", "日月阳止，女心伤止，征夫遑止。"], "notes": "", "page": null}, {"text": "有杕之杜，其叶萋萋。王事靡盬，我心伤悲。卉木萋止，女心悲止，征夫归止！", "sentences": ["有杕之杜，其叶萋萋。", "王事靡盬，我心伤悲。", "卉木萋止，女心悲止，征夫归止！"], "notes": "", "page": null}, {"text": "陟彼北山，言采其杞。王事靡盬，忧我父母。檀车幝幝，四牡痯痯，征夫不远！", "sentences": ["陟彼北山，言采其杞。", "王事靡盬，忧我父母。", "檀车幝幝，四牡痯痯，征夫不远！"], "notes": "", "page": null}, {"text": "匪载匪来，忧心孔疚。斯逝不至，而多为恤。卜筮偕止，会言近止，征夫迩止！", "sentences": ["匪载匪来，忧心孔疚。", "斯逝不至，而多为恤。", "卜筮偕止，会言近止，征夫迩止！"], "notes": "", "page": null}]}, {"id": "p170", "title": "鱼丽", "section": "小雅", "group": "鹿鸣之什", "intro": "《鱼丽》收于《诗经·小雅·鹿鸣之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "鱼丽于罶，鲿鲨。君子有酒，旨且多。", "sentences": ["鱼丽于罶，鲿鲨。", "君子有酒，旨且多。"], "notes": "", "page": null}, {"text": "鱼丽于罶，鲂鳢。君子有酒，多且旨。", "sentences": ["鱼丽于罶，鲂鳢。", "君子有酒，多且旨。"], "notes": "", "page": null}, {"text": "鱼丽于罶，鰋鲤。君子有酒，旨且有。物其多矣，", "sentences": ["鱼丽于罶，鰋鲤。", "君子有酒，旨且有。", "物其多矣，"], "notes": "", "page": null}, {"text": "维其嘉矣！物其旨矣，维其偕矣！物其有矣，维其时矣！", "sentences": ["维其嘉矣！", "物其旨矣，维其偕矣！", "物其有矣，维其时矣！"], "notes": "", "page": null}]}, {"id": "p171", "title": "南有嘉鱼", "section": "小雅", "group": "南有嘉鱼之什", "intro": "《南有嘉鱼》收于《诗经·小雅·南有嘉鱼之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "南有嘉鱼，烝然罩罩。君子有酒，嘉宾式燕以乐。", "sentences": ["南有嘉鱼，烝然罩罩。", "君子有酒，嘉宾式燕以乐。"], "notes": "", "page": null}, {"text": "南有嘉鱼，烝然汕汕。君子有酒，嘉宾式燕以衎。", "sentences": ["南有嘉鱼，烝然汕汕。", "君子有酒，嘉宾式燕以衎。"], "notes": "", "page": null}, {"text": "南有樛木，甘瓠累之。君子有酒，嘉宾式燕绥之。", "sentences": ["南有樛木，甘瓠累之。", "君子有酒，嘉宾式燕绥之。"], "notes": "", "page": null}, {"text": "翩翩者鵻，烝然来思。君子有酒，嘉宾式燕又思。", "sentences": ["翩翩者鵻，烝然来思。", "君子有酒，嘉宾式燕又思。"], "notes": "", "page": null}]}, {"id": "p172", "title": "南山有台", "section": "小雅", "group": "南有嘉鱼之什", "intro": "《南山有台》收于《诗经·小雅·南有嘉鱼之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "南山有台，北山有莱。乐只君子，邦家之基。乐只君子，万寿无期。", "sentences": ["南山有台，北山有莱。", "乐只君子，邦家之基。", "乐只君子，万寿无期。"], "notes": "", "page": null}, {"text": "南山有桑，北山有杨。乐只君子，邦家之光。乐只君子，万寿无疆。", "sentences": ["南山有桑，北山有杨。", "乐只君子，邦家之光。", "乐只君子，万寿无疆。"], "notes": "", "page": null}, {"text": "南山有杞，北山有李。乐只君子，民之父母。乐只君子，德音不已。", "sentences": ["南山有杞，北山有李。", "乐只君子，民之父母。", "乐只君子，德音不已。"], "notes": "", "page": null}, {"text": "南山有栲，北山有杻。乐只君子，遐不眉寿。乐只君子，德音是茂。", "sentences": ["南山有栲，北山有杻。", "乐只君子，遐不眉寿。", "乐只君子，德音是茂。"], "notes": "", "page": null}, {"text": "南山有枸，北山有楰。乐只君子，遐不黄耇。乐只君子，保艾尔后。", "sentences": ["南山有枸，北山有楰。", "乐只君子，遐不黄耇。", "乐只君子，保艾尔后。"], "notes": "", "page": null}]}, {"id": "p173", "title": "蓼萧", "section": "小雅", "group": "南有嘉鱼之什", "intro": "《蓼萧》收于《诗经·小雅·南有嘉鱼之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "蓼彼萧斯，零露湑兮。既见君子，我心写兮。燕笑语兮，是以有誉处兮。", "sentences": ["蓼彼萧斯，零露湑兮。", "既见君子，我心写兮。", "燕笑语兮，是以有誉处兮。"], "notes": "", "page": null}, {"text": "蓼彼萧斯，零露瀼瀼。既见君子，为龙为光。其德不爽，寿考不忘。", "sentences": ["蓼彼萧斯，零露瀼瀼。", "既见君子，为龙为光。", "其德不爽，寿考不忘。"], "notes": "", "page": null}, {"text": "蓼彼萧斯，零露泥泥。既见君子，孔燕岂弟。宜兄宜弟，令德寿岂。", "sentences": ["蓼彼萧斯，零露泥泥。", "既见君子，孔燕岂弟。", "宜兄宜弟，令德寿岂。"], "notes": "", "page": null}, {"text": "蓼彼萧斯，零露浓浓。既见君子，鞗革忡忡。和鸾雍雍，万福攸同。", "sentences": ["蓼彼萧斯，零露浓浓。", "既见君子，鞗革忡忡。", "和鸾雍雍，万福攸同。"], "notes": "", "page": null}]}, {"id": "p174", "title": "湛露", "section": "小雅", "group": "南有嘉鱼之什", "intro": "《湛露》收于《诗经·小雅·南有嘉鱼之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "湛湛露斯，匪阳不晞。厌厌夜饮，不醉无归。", "sentences": ["湛湛露斯，匪阳不晞。", "厌厌夜饮，不醉无归。"], "notes": "", "page": null}, {"text": "湛湛露斯，在彼丰草。厌厌夜饮，在宗载考。", "sentences": ["湛湛露斯，在彼丰草。", "厌厌夜饮，在宗载考。"], "notes": "", "page": null}, {"text": "湛湛露斯，在彼杞棘。显允君子，莫不令德。", "sentences": ["湛湛露斯，在彼杞棘。", "显允君子，莫不令德。"], "notes": "", "page": null}, {"text": "其桐其椅，其实离离。岂弟君子，莫不令仪。", "sentences": ["其桐其椅，其实离离。", "岂弟君子，莫不令仪。"], "notes": "", "page": null}]}, {"id": "p175", "title": "彤弓", "section": "小雅", "group": "南有嘉鱼之什", "intro": "《彤弓》收于《诗经·小雅·南有嘉鱼之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "彤弓弨兮，受言藏之。我有嘉宾，中心贶之。钟鼓既设，一朝飨之。", "sentences": ["彤弓弨兮，受言藏之。", "我有嘉宾，中心贶之。", "钟鼓既设，一朝飨之。"], "notes": "", "page": null}, {"text": "彤弓弨兮，受言载之。我有嘉宾，中心喜之。钟鼓既设，一朝右之。", "sentences": ["彤弓弨兮，受言载之。", "我有嘉宾，中心喜之。", "钟鼓既设，一朝右之。"], "notes": "", "page": null}, {"text": "彤弓弨兮，受言櫜之。我有嘉宾，中心好之。钟鼓既设，一朝酬之。", "sentences": ["彤弓弨兮，受言櫜之。", "我有嘉宾，中心好之。", "钟鼓既设，一朝酬之。"], "notes": "", "page": null}]}, {"id": "p176", "title": "菁菁者莪", "section": "小雅", "group": "南有嘉鱼之什", "intro": "《菁菁者莪》收于《诗经·小雅·南有嘉鱼之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "菁菁者莪，在彼中阿。既见君子，乐且有仪。", "sentences": ["菁菁者莪，在彼中阿。", "既见君子，乐且有仪。"], "notes": "", "page": null}, {"text": "菁菁者莪，在彼中沚。既见君子，我心则喜。", "sentences": ["菁菁者莪，在彼中沚。", "既见君子，我心则喜。"], "notes": "", "page": null}, {"text": "菁菁者莪，在彼中陵。既见君子，锡我百朋。", "sentences": ["菁菁者莪，在彼中陵。", "既见君子，锡我百朋。"], "notes": "", "page": null}, {"text": "泛泛杨舟，载沉载浮。既见君子，我心则休。", "sentences": ["泛泛杨舟，载沉载浮。", "既见君子，我心则休。"], "notes": "", "page": null}]}, {"id": "p177", "title": "六月", "section": "小雅", "group": "南有嘉鱼之什", "intro": "《六月》收于《诗经·小雅·南有嘉鱼之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "六月栖栖，戎车既饬。四牡骙骙，载是常服。玁狁孔炽，我是用急。王于出征，以匡王国。", "sentences": ["六月栖栖，戎车既饬。", "四牡骙骙，载是常服。", "玁狁孔炽，我是用急。", "王于出征，以匡王国。"], "notes": "", "page": null}, {"text": "比物四骊，闲之维则。维此六月，既成我服。我服既成，于三十里。王于出征，以佐天子。", "sentences": ["比物四骊，闲之维则。", "维此六月，既成我服。", "我服既成，于三十里。", "王于出征，以佐天子。"], "notes": "", "page": null}, {"text": "四牡修广，其大有颙。薄伐玁狁，以奏肤公。有严有翼，共武之服。共武之服，以定王国。", "sentences": ["四牡修广，其大有颙。", "薄伐玁狁，以奏肤公。", "有严有翼，共武之服。", "共武之服，以定王国。"], "notes": "", "page": null}, {"text": "玁狁匪茹，整居焦获。侵镐及方，至于泾阳。织文鸟章，白旆央央。元戎十乘，以先启行。", "sentences": ["玁狁匪茹，整居焦获。", "侵镐及方，至于泾阳。", "织文鸟章，白旆央央。", "元戎十乘，以先启行。"], "notes": "", "page": null}, {"text": "戎车既安，如轾如轩。四牡既佶，既佶且闲。薄伐玁狁，至于大原。文武吉甫，万邦为宪。", "sentences": ["戎车既安，如轾如轩。", "四牡既佶，既佶且闲。", "薄伐玁狁，至于大原。", "文武吉甫，万邦为宪。"], "notes": "", "page": null}, {"text": "吉甫燕喜，既多受祉。来归自镐，我行永久。饮御诸友，炰鳖脍鲤。侯谁在矣？张仲孝友。", "sentences": ["吉甫燕喜，既多受祉。", "来归自镐，我行永久。", "饮御诸友，炰鳖脍鲤。", "侯谁在矣？", "张仲孝友。"], "notes": "", "page": null}]}, {"id": "p178", "title": "采芑", "section": "小雅", "group": "南有嘉鱼之什", "intro": "《采芑》收于《诗经·小雅·南有嘉鱼之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "薄言采芑，于彼新田，呈此菑亩。方叔涖止，其车三千。师干之试，方叔率止。", "sentences": ["薄言采芑，于彼新田，呈此菑亩。", "方叔涖止，其车三千。", "师干之试，方叔率止。"], "notes": "", "page": null}, {"text": "乘其四骐，四骐翼翼。路车有奭，簟茀鱼服，钩膺鞗革。", "sentences": ["乘其四骐，四骐翼翼。", "路车有奭，簟茀鱼服，钩膺鞗革。"], "notes": "", "page": null}, {"text": "薄言采芑，于彼新田，于此中乡。方叔涖止，其车三千。旂旐央央，方叔率止。", "sentences": ["薄言采芑，于彼新田，于此中乡。", "方叔涖止，其车三千。", "旂旐央央，方叔率止。"], "notes": "", "page": null}, {"text": "约軧错衡，八鸾玱玱。服其命服，朱芾斯皇，有玱葱珩。", "sentences": ["约軧错衡，八鸾玱玱。", "服其命服，朱芾斯皇，有玱葱珩。"], "notes": "", "page": null}, {"text": "鴥彼飞隼，其飞戾天，亦集爰止。方叔涖止，其车三千。师干之试，方叔率止。", "sentences": ["鴥彼飞隼，其飞戾天，亦集爰止。", "方叔涖止，其车三千。", "师干之试，方叔率止。"], "notes": "", "page": null}, {"text": "钲人伐鼓，陈师鞠旅。显允方叔，伐鼓渊渊，振旅阗阗。", "sentences": ["钲人伐鼓，陈师鞠旅。", "显允方叔，伐鼓渊渊，振旅阗阗。"], "notes": "", "page": null}, {"text": "蠢尔蛮荆，大邦为仇。方叔元老，克壮其犹。方叔率止，执讯获丑。戎车啴啴，", "sentences": ["蠢尔蛮荆，大邦为仇。", "方叔元老，克壮其犹。", "方叔率止，执讯获丑。", "戎车啴啴，"], "notes": "", "page": null}, {"text": "啴啴焞焞，如霆如雷。显允方叔，征伐玁狁，蛮荆来威。", "sentences": ["啴啴焞焞，如霆如雷。", "显允方叔，征伐玁狁，蛮荆来威。"], "notes": "", "page": null}]}, {"id": "p179", "title": "车攻", "section": "小雅", "group": "南有嘉鱼之什", "intro": "《车攻》收于《诗经·小雅·南有嘉鱼之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "我车既攻，我马既同。四牡庞庞，驾言徂东。", "sentences": ["我车既攻，我马既同。", "四牡庞庞，驾言徂东。"], "notes": "", "page": null}, {"text": "田车既好，田牡孔阜。东有甫草，驾言行狩。", "sentences": ["田车既好，田牡孔阜。", "东有甫草，驾言行狩。"], "notes": "", "page": null}, {"text": "之子于苗，选徒嚣嚣。建旐设旄，搏兽于敖。", "sentences": ["之子于苗，选徒嚣嚣。", "建旐设旄，搏兽于敖。"], "notes": "", "page": null}, {"text": "驾彼四牡，四牡奕奕。赤芾金舄，会同有绎。", "sentences": ["驾彼四牡，四牡奕奕。", "赤芾金舄，会同有绎。"], "notes": "", "page": null}, {"text": "决拾既佽，弓矢既调。射夫既同，助我举柴。", "sentences": ["决拾既佽，弓矢既调。", "射夫既同，助我举柴。"], "notes": "", "page": null}, {"text": "四黄既驾，两骖不猗。不失其驰，舍矢如破。", "sentences": ["四黄既驾，两骖不猗。", "不失其驰，舍矢如破。"], "notes": "", "page": null}, {"text": "萧萧马鸣，悠悠旆旌。徒御不惊，大庖不盈。", "sentences": ["萧萧马鸣，悠悠旆旌。", "徒御不惊，大庖不盈。"], "notes": "", "page": null}, {"text": "之子于征，有闻无声。允矣君子，展也大成。", "sentences": ["之子于征，有闻无声。", "允矣君子，展也大成。"], "notes": "", "page": null}]}, {"id": "p180", "title": "吉日", "section": "小雅", "group": "南有嘉鱼之什", "intro": "《吉日》收于《诗经·小雅·南有嘉鱼之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "吉日维戊，既伯既祷。田车既好，四牡孔阜。升彼大阜，从其群丑。", "sentences": ["吉日维戊，既伯既祷。", "田车既好，四牡孔阜。", "升彼大阜，从其群丑。"], "notes": "", "page": null}, {"text": "吉日庚午，既差我马。兽之所同，麀鹿麌麌。漆沮之从，天子之所。", "sentences": ["吉日庚午，既差我马。", "兽之所同，麀鹿麌麌。", "漆沮之从，天子之所。"], "notes": "", "page": null}, {"text": "瞻彼中原，其祁孔有。儦儦俟俟，或群或友。悉率左右，以燕天子。", "sentences": ["瞻彼中原，其祁孔有。", "儦儦俟俟，或群或友。", "悉率左右，以燕天子。"], "notes": "", "page": null}, {"text": "既张我弓，既挟我矢。发彼小豝，殪此大兕。以御宾客，且以酌醴。", "sentences": ["既张我弓，既挟我矢。", "发彼小豝，殪此大兕。", "以御宾客，且以酌醴。"], "notes": "", "page": null}]}, {"id": "p181", "title": "鸿雁", "section": "小雅", "group": "鸿雁之什", "intro": "《鸿雁》收于《诗经·小雅·鸿雁之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "鸿雁于飞，肃肃其羽。之子于征，劬劳于野。爰及矜人，哀此鳏寡。", "sentences": ["鸿雁于飞，肃肃其羽。", "之子于征，劬劳于野。", "爰及矜人，哀此鳏寡。"], "notes": "", "page": null}, {"text": "鸿雁于飞，集于中泽。之子于垣，百堵皆作。虽则劬劳，其究安宅？", "sentences": ["鸿雁于飞，集于中泽。", "之子于垣，百堵皆作。", "虽则劬劳，其究安宅？"], "notes": "", "page": null}, {"text": "鸿雁于飞，哀鸣嗷嗷。维此哲人，谓我劬劳。维彼愚人，谓我宣骄。", "sentences": ["鸿雁于飞，哀鸣嗷嗷。", "维此哲人，谓我劬劳。", "维彼愚人，谓我宣骄。"], "notes": "", "page": null}]}, {"id": "p182", "title": "庭燎", "section": "小雅", "group": "鸿雁之什", "intro": "《庭燎》收于《诗经·小雅·鸿雁之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "夜如何其？夜未央，庭燎之光。君子至止，鸾声将将。", "sentences": ["夜如何其？", "夜未央，庭燎之光。", "君子至止，鸾声将将。"], "notes": "", "page": null}, {"text": "夜如何其？夜未艾，庭燎晣晣。君子至止，鸾声哕哕。", "sentences": ["夜如何其？", "夜未艾，庭燎晣晣。", "君子至止，鸾声哕哕。"], "notes": "", "page": null}, {"text": "夜如何其？夜乡晨，庭燎有辉。君子至止，言观其旂。", "sentences": ["夜如何其？", "夜乡晨，庭燎有辉。", "君子至止，言观其旂。"], "notes": "", "page": null}]}, {"id": "p183", "title": "沔水", "section": "小雅", "group": "鸿雁之什", "intro": "《沔水》收于《诗经·小雅·鸿雁之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "沔彼流水，朝宗于海。鴥彼飞隼，载飞载止。嗟我兄弟，邦人诸友。莫肯念乱，谁无父母？", "sentences": ["沔彼流水，朝宗于海。", "鴥彼飞隼，载飞载止。", "嗟我兄弟，邦人诸友。", "莫肯念乱，谁无父母？"], "notes": "", "page": null}, {"text": "沔彼流水，其流汤汤。鴥彼飞隼，载飞载扬。念彼不迹，载起载行。心之忧矣，不可弭忘。", "sentences": ["沔彼流水，其流汤汤。", "鴥彼飞隼，载飞载扬。", "念彼不迹，载起载行。", "心之忧矣，不可弭忘。"], "notes": "", "page": null}, {"text": "鴥彼飞隼，率彼中陵。民之讹言，宁莫之惩？我友敬矣，谗言其兴。", "sentences": ["鴥彼飞隼，率彼中陵。", "民之讹言，宁莫之惩？", "我友敬矣，谗言其兴。"], "notes": "", "page": null}]}, {"id": "p184", "title": "鹤鸣", "section": "小雅", "group": "鸿雁之什", "intro": "《鹤鸣》收于《诗经·小雅·鸿雁之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "鹤鸣于九皋，声闻于野。鱼潜在渊，或在于渚。乐彼之园，爰有树檀，其下维萚。他山之石，可以为错。", "sentences": ["鹤鸣于九皋，声闻于野。", "鱼潜在渊，或在于渚。", "乐彼之园，爰有树檀，其下维萚。", "他山之石，可以为错。"], "notes": "", "page": null}, {"text": "鹤鸣于九皋，声闻于天。鱼在于渚，或潜在渊。乐彼之园，爰有树檀，其下维谷。他山之石，可以攻玉。", "sentences": ["鹤鸣于九皋，声闻于天。", "鱼在于渚，或潜在渊。", "乐彼之园，爰有树檀，其下维谷。", "他山之石，可以攻玉。"], "notes": "", "page": null}]}, {"id": "p185", "title": "祈父", "section": "小雅", "group": "鸿雁之什", "intro": "《祈父》收于《诗经·小雅·鸿雁之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "祈父，予王之爪牙。胡转予于恤，靡所止居？", "sentences": ["祈父，予王之爪牙。", "胡转予于恤，靡所止居？"], "notes": "", "page": null}, {"text": "祈父，予王之爪士。胡转予于恤，靡所厎止？", "sentences": ["祈父，予王之爪士。", "胡转予于恤，靡所厎止？"], "notes": "", "page": null}, {"text": "祈父，亶不聪。胡转予于恤？有母之尸饔。", "sentences": ["祈父，亶不聪。", "胡转予于恤？", "有母之尸饔。"], "notes": "", "page": null}]}, {"id": "p186", "title": "白驹", "section": "小雅", "group": "鸿雁之什", "intro": "《白驹》收于《诗经·小雅·鸿雁之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "皎皎白驹，食我场苗。絷之维之，以永今朝。所谓伊人，于焉逍遥？", "sentences": ["皎皎白驹，食我场苗。", "絷之维之，以永今朝。", "所谓伊人，于焉逍遥？"], "notes": "", "page": null}, {"text": "皎皎白驹，食我场藿。絷之维之，以永今夕。所谓伊人，于焉嘉客？", "sentences": ["皎皎白驹，食我场藿。", "絷之维之，以永今夕。", "所谓伊人，于焉嘉客？"], "notes": "", "page": null}, {"text": "皎皎白驹，贲然来思。尔公尔侯，逸豫无期？慎尔优游，勉尔遁思。", "sentences": ["皎皎白驹，贲然来思。", "尔公尔侯，逸豫无期？", "慎尔优游，勉尔遁思。"], "notes": "", "page": null}, {"text": "皎皎白驹，在彼空谷。生刍一束，其人如玉。毋金玉尔音，而有遐心。", "sentences": ["皎皎白驹，在彼空谷。", "生刍一束，其人如玉。", "毋金玉尔音，而有遐心。"], "notes": "", "page": null}]}, {"id": "p187", "title": "黄鸟", "section": "小雅", "group": "鸿雁之什", "intro": "《黄鸟》收于《诗经·小雅·鸿雁之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "黄鸟黄鸟，无集于穀，无啄我粟。此邦之人，不我肯穀。言旋言归，复我邦族。", "sentences": ["黄鸟黄鸟，无集于穀，无啄我粟。", "此邦之人，不我肯穀。", "言旋言归，复我邦族。"], "notes": "", "page": null}, {"text": "黄鸟黄鸟，无集于桑，无啄我粱。此邦之人，不可与明。言旋言归，复我诸兄。", "sentences": ["黄鸟黄鸟，无集于桑，无啄我粱。", "此邦之人，不可与明。", "言旋言归，复我诸兄。"], "notes": "", "page": null}, {"text": "黄鸟黄鸟，无集于栩，无啄我黍。此邦之人，不可与处。言旋言归，复我诸父。", "sentences": ["黄鸟黄鸟，无集于栩，无啄我黍。", "此邦之人，不可与处。", "言旋言归，复我诸父。"], "notes": "", "page": null}]}, {"id": "p188", "title": "我行其野", "section": "小雅", "group": "鸿雁之什", "intro": "《我行其野》收于《诗经·小雅·鸿雁之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "我行其野，蔽芾其樗。婚姻之故，言就尔居。尔不我畜，复我邦家。", "sentences": ["我行其野，蔽芾其樗。", "婚姻之故，言就尔居。", "尔不我畜，复我邦家。"], "notes": "", "page": null}, {"text": "我行其野，言采其蓫。婚姻之故，言就尔宿。尔不我畜，言归斯复。", "sentences": ["我行其野，言采其蓫。", "婚姻之故，言就尔宿。", "尔不我畜，言归斯复。"], "notes": "", "page": null}, {"text": "我行其野，言采其葍。不思旧姻，求尔新特。成不以富，亦祗以异。", "sentences": ["我行其野，言采其葍。", "不思旧姻，求尔新特。", "成不以富，亦祗以异。"], "notes": "", "page": null}]}, {"id": "p189", "title": "斯干", "section": "小雅", "group": "鸿雁之什", "intro": "《斯干》收于《诗经·小雅·鸿雁之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "秩秩斯干，幽幽南山。如竹苞矣，如松茂矣。兄及弟矣，式相好矣，无相犹矣。", "sentences": ["秩秩斯干，幽幽南山。", "如竹苞矣，如松茂矣。", "兄及弟矣，式相好矣，无相犹矣。"], "notes": "", "page": null}, {"text": "似续妣祖，筑室百堵，西南其户。爰居爰处，爰笑爰语。", "sentences": ["似续妣祖，筑室百堵，西南其户。", "爰居爰处，爰笑爰语。"], "notes": "", "page": null}, {"text": "约之阁阁，椓之橐橐。风雨攸除，鸟鼠攸去，君子攸芋。", "sentences": ["约之阁阁，椓之橐橐。", "风雨攸除，鸟鼠攸去，君子攸芋。"], "notes": "", "page": null}, {"text": "如跂斯翼，如矢斯棘，如鸟斯革，如翚斯飞，君子攸跻。", "sentences": ["如跂斯翼，如矢斯棘，如鸟斯革，如翚斯飞，君子攸跻。"], "notes": "", "page": null}, {"text": "殖殖其庭，有觉其楹。哙哙其正，哕哕其冥。君子攸宁。", "sentences": ["殖殖其庭，有觉其楹。", "哙哙其正，哕哕其冥。", "君子攸宁。"], "notes": "", "page": null}, {"text": "下莞上簟，乃安斯寝。乃寝乃兴，乃占我梦。吉梦维何？维熊维罴，维虺维蛇。", "sentences": ["下莞上簟，乃安斯寝。", "乃寝乃兴，乃占我梦。", "吉梦维何？", "维熊维罴，维虺维蛇。"], "notes": "", "page": null}, {"text": "大人占之：维熊维罴，男子之祥；维虺维蛇，女子之祥。", "sentences": ["大人占之：维熊维罴，男子之祥；维虺维蛇，女子之祥。"], "notes": "", "page": null}, {"text": "乃生男子，载寝之床。载衣之裳，载弄之璋。其泣喤喤，朱芾斯皇，室家君王。", "sentences": ["乃生男子，载寝之床。", "载衣之裳，载弄之璋。", "其泣喤喤，朱芾斯皇，室家君王。"], "notes": "", "page": null}, {"text": "乃生女子，载寝之地。载衣之裼，载弄之瓦。无非无仪，唯酒食是议，无父母诒罹。", "sentences": ["乃生女子，载寝之地。", "载衣之裼，载弄之瓦。", "无非无仪，唯酒食是议，无父母诒罹。"], "notes": "", "page": null}]}, {"id": "p190", "title": "无羊", "section": "小雅", "group": "鸿雁之什", "intro": "《无羊》收于《诗经·小雅·鸿雁之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "谁谓尔无羊？三百维群。谁谓尔无牛？九十其犉。尔羊来思，其角濈濈。尔牛来思，其耳湿湿。", "sentences": ["谁谓尔无羊？", "三百维群。", "谁谓尔无牛？", "九十其犉。", "尔羊来思，其角濈濈。", "尔牛来思，其耳湿湿。"], "notes": "", "page": null}, {"text": "或降于阿，或饮于池，或寝或讹。尔牧来思，何蓑何笠，或负其餱。三十维物，尔牲则具。", "sentences": ["或降于阿，或饮于池，或寝或讹。", "尔牧来思，何蓑何笠，或负其餱。", "三十维物，尔牲则具。"], "notes": "", "page": null}, {"text": "尔牧来思，以薪以蒸，以雌以雄。尔羊来思，矜矜兢兢，不骞不崩。麾之以肱，毕来既升。", "sentences": ["尔牧来思，以薪以蒸，以雌以雄。", "尔羊来思，矜矜兢兢，不骞不崩。", "麾之以肱，毕来既升。"], "notes": "", "page": null}, {"text": "牧人乃梦，众维鱼矣，旐维旟矣，大人占之；众维鱼矣，实维丰年；旐维旟矣，室家溱溱。", "sentences": ["牧人乃梦，众维鱼矣，旐维旟矣，大人占之；众维鱼矣，实维丰年；旐维旟矣，室家溱溱。"], "notes": "", "page": null}]}, {"id": "p191", "title": "节南山", "section": "小雅", "group": "节南山之什", "intro": "《节南山》收于《诗经·小雅·节南山之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "节彼南山，维石岩岩。赫赫师尹，民具尔瞻。忧心如惔，不敢戏谈。国既卒斩，何用不监！", "sentences": ["节彼南山，维石岩岩。", "赫赫师尹，民具尔瞻。", "忧心如惔，不敢戏谈。", "国既卒斩，何用不监！"], "notes": "", "page": null}, {"text": "节彼南山，有实其猗。赫赫师尹，不平谓何。天方荐瘥，丧乱弘多。民言无嘉，惨莫惩嗟。", "sentences": ["节彼南山，有实其猗。", "赫赫师尹，不平谓何。", "天方荐瘥，丧乱弘多。", "民言无嘉，惨莫惩嗟。"], "notes": "", "page": null}, {"text": "尹氏大师，维周之氐；秉国之钧，四方是维。天子是毗，俾民不迷。不吊昊天，不宜空我师。", "sentences": ["尹氏大师，维周之氐；秉国之钧，四方是维。", "天子是毗，俾民不迷。", "不吊昊天，不宜空我师。"], "notes": "", "page": null}, {"text": "弗躬弗亲，庶民弗信。弗问弗仕，勿罔君子。式夷式已，无小人殆。琐琐姻亚，则无膴仕。", "sentences": ["弗躬弗亲，庶民弗信。", "弗问弗仕，勿罔君子。", "式夷式已，无小人殆。", "琐琐姻亚，则无膴仕。"], "notes": "", "page": null}, {"text": "昊天不佣，降此鞠訩。昊天不惠，降此大戾。君子如届，俾民心阕。君子如夷，恶怒是违。", "sentences": ["昊天不佣，降此鞠訩。", "昊天不惠，降此大戾。", "君子如届，俾民心阕。", "君子如夷，恶怒是违。"], "notes": "", "page": null}, {"text": "不吊昊天，乱靡有定。式月斯生，俾民不宁。忧心如酲，谁秉国成？不自为政，卒劳百姓。", "sentences": ["不吊昊天，乱靡有定。", "式月斯生，俾民不宁。", "忧心如酲，谁秉国成？", "不自为政，卒劳百姓。"], "notes": "", "page": null}, {"text": "驾彼四牡，四牡项领。我瞻四方，蹙蹙靡所骋。", "sentences": ["驾彼四牡，四牡项领。", "我瞻四方，蹙蹙靡所骋。"], "notes": "", "page": null}, {"text": "方茂尔恶，相尔矛矣。既夷既怿，如相酬矣。", "sentences": ["方茂尔恶，相尔矛矣。", "既夷既怿，如相酬矣。"], "notes": "", "page": null}, {"text": "昊天不平，我王不宁。不惩其心，覆怨其正。", "sentences": ["昊天不平，我王不宁。", "不惩其心，覆怨其正。"], "notes": "", "page": null}, {"text": "家父作诵，以究王訩。式讹尔心，以畜万邦。", "sentences": ["家父作诵，以究王訩。", "式讹尔心，以畜万邦。"], "notes": "", "page": null}]}, {"id": "p192", "title": "正月", "section": "小雅", "group": "节南山之什", "intro": "《正月》收于《诗经·小雅·节南山之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "正月繁霜，我心忧伤。民之讹言，亦孔之将。念我独兮，忧心京京。哀我小心，癙忧以痒。", "sentences": ["正月繁霜，我心忧伤。", "民之讹言，亦孔之将。", "念我独兮，忧心京京。", "哀我小心，癙忧以痒。"], "notes": "", "page": null}, {"text": "父母生我，胡俾我瘉？不自我先，不自我后。好言自口，莠言自口。忧心愈愈，是以有侮。", "sentences": ["父母生我，胡俾我瘉？", "不自我先，不自我后。", "好言自口，莠言自口。", "忧心愈愈，是以有侮。"], "notes": "", "page": null}, {"text": "忧心惸惸，念我无禄。民之无辜，并其臣仆。哀我人斯，于何从禄？瞻乌爰止？于谁之屋？", "sentences": ["忧心惸惸，念我无禄。", "民之无辜，并其臣仆。", "哀我人斯，于何从禄？", "瞻乌爰止？", "于谁之屋？"], "notes": "", "page": null}, {"text": "瞻彼中林，侯薪侯蒸。民今方殆，视天梦梦。既克有定，靡人弗胜。有皇上帝，伊谁云憎？", "sentences": ["瞻彼中林，侯薪侯蒸。", "民今方殆，视天梦梦。", "既克有定，靡人弗胜。", "有皇上帝，伊谁云憎？"], "notes": "", "page": null}, {"text": "谓山盖卑，为冈为陵。民之讹言，宁莫之惩。召彼故老，讯之占梦。具曰予圣，谁知乌之雌雄！", "sentences": ["谓山盖卑，为冈为陵。", "民之讹言，宁莫之惩。", "召彼故老，讯之占梦。", "具曰予圣，谁知乌之雌雄！"], "notes": "", "page": null}, {"text": "谓天盖高，不敢不局。谓地盖厚，不敢不蹐。维号斯言，有伦有脊。哀今之人，胡为虺蜴？", "sentences": ["谓天盖高，不敢不局。", "谓地盖厚，不敢不蹐。", "维号斯言，有伦有脊。", "哀今之人，胡为虺蜴？"], "notes": "", "page": null}, {"text": "瞻彼阪田，有菀其特。天之杌我，如不我克。彼求我则，如不我得。执我仇仇，亦不我力。", "sentences": ["瞻彼阪田，有菀其特。", "天之杌我，如不我克。", "彼求我则，如不我得。", "执我仇仇，亦不我力。"], "notes": "", "page": null}, {"text": "心之忧矣，如或结之。今兹之正，胡然厉矣？燎之方扬，宁或灭之？赫赫宗周，褒姒灭之！", "sentences": ["心之忧矣，如或结之。", "今兹之正，胡然厉矣？", "燎之方扬，宁或灭之？", "赫赫宗周，褒姒灭之！"], "notes": "", "page": null}, {"text": "终其永怀，又窘阴雨。其车既载，乃弃尔辅。载输尔载，将伯助予！", "sentences": ["终其永怀，又窘阴雨。", "其车既载，乃弃尔辅。", "载输尔载，将伯助予！"], "notes": "", "page": null}, {"text": "无弃尔辅，员于尔辐。屡顾尔仆，不输尔载。终逾绝险，曾是不意。", "sentences": ["无弃尔辅，员于尔辐。", "屡顾尔仆，不输尔载。", "终逾绝险，曾是不意。"], "notes": "", "page": null}, {"text": "鱼在于沼，亦匪克乐。潜虽伏矣，亦孔之炤。忧心惨惨，念国之为虐！", "sentences": ["鱼在于沼，亦匪克乐。", "潜虽伏矣，亦孔之炤。", "忧心惨惨，念国之为虐！"], "notes": "", "page": null}, {"text": "彼有旨酒，又有嘉肴。洽比其邻，婚姻孔云。念我独兮，忧心殷殷。", "sentences": ["彼有旨酒，又有嘉肴。", "洽比其邻，婚姻孔云。", "念我独兮，忧心殷殷。"], "notes": "", "page": null}, {"text": "佌佌彼有屋，蔌蔌方有谷。民今之无禄，天夭是椓。哿矣富人，哀此惸独。", "sentences": ["佌佌彼有屋，蔌蔌方有谷。", "民今之无禄，天夭是椓。", "哿矣富人，哀此惸独。"], "notes": "", "page": null}]}, {"id": "p193", "title": "十月之交", "section": "小雅", "group": "节南山之什", "intro": "《十月之交》收于《诗经·小雅·节南山之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "十月之交，朔月辛卯。日有食之，亦孔之丑。彼月而微，此日而微；今此下民，亦孔之哀。", "sentences": ["十月之交，朔月辛卯。", "日有食之，亦孔之丑。", "彼月而微，此日而微；今此下民，亦孔之哀。"], "notes": "", "page": null}, {"text": "日月告凶，不用其行。四国无政，不用其良。彼月而食，则维其常；此日而食，于何不臧。", "sentences": ["日月告凶，不用其行。", "四国无政，不用其良。", "彼月而食，则维其常；此日而食，于何不臧。"], "notes": "", "page": null}, {"text": "烨烨震电，不宁不令。百川沸腾，山冢崒崩。高岸为谷，深谷为陵。哀今之人，胡惨莫惩？", "sentences": ["烨烨震电，不宁不令。", "百川沸腾，山冢崒崩。", "高岸为谷，深谷为陵。", "哀今之人，胡惨莫惩？"], "notes": "", "page": null}, {"text": "皇父卿士，番维司徒，家伯维宰，仲允膳夫，棸子内史，蹶维趣马，楀维师氏。醘妻煽方处。", "sentences": ["皇父卿士，番维司徒，家伯维宰，仲允膳夫，棸子内史，蹶维趣马，楀维师氏。", "醘妻煽方处。"], "notes": "", "page": null}, {"text": "抑此皇父，岂曰不时？胡为我作，不即我谋？彻我墙屋，田卒污莱。曰予不戕，礼则然矣。", "sentences": ["抑此皇父，岂曰不时？", "胡为我作，不即我谋？", "彻我墙屋，田卒污莱。", "曰予不戕，礼则然矣。"], "notes": "", "page": null}, {"text": "皇父孔圣，作都于向。择三有事，亶侯多藏。不慭遗一老，俾守我王。择有车马，以居徂向。", "sentences": ["皇父孔圣，作都于向。", "择三有事，亶侯多藏。", "不慭遗一老，俾守我王。", "择有车马，以居徂向。"], "notes": "", "page": null}, {"text": "黾勉从事，不敢告劳。无罪无辜，谗口嚣嚣。下民之孽，匪降自天。噂沓背憎，职竞由人。", "sentences": ["黾勉从事，不敢告劳。", "无罪无辜，谗口嚣嚣。", "下民之孽，匪降自天。", "噂沓背憎，职竞由人。"], "notes": "", "page": null}, {"text": "悠悠我里，亦孔之痗。四方有羡，我独居忧。民莫不逸，我独不敢休。天命不彻，我不敢效我友自逸。", "sentences": ["悠悠我里，亦孔之痗。", "四方有羡，我独居忧。", "民莫不逸，我独不敢休。", "天命不彻，我不敢效我友自逸。"], "notes": "", "page": null}]}, {"id": "p194", "title": "雨无正", "section": "小雅", "group": "节南山之什", "intro": "《雨无正》收于《诗经·小雅·节南山之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "浩浩昊天，不骏其德。降丧饥馑，斩伐四国。旻天疾威，弗虑弗图。舍彼有罪，既伏其辜。若此无罪，沦胥以铺。", "sentences": ["浩浩昊天，不骏其德。", "降丧饥馑，斩伐四国。", "旻天疾威，弗虑弗图。", "舍彼有罪，既伏其辜。", "若此无罪，沦胥以铺。"], "notes": "", "page": null}, {"text": "周宗既灭，靡所止戾。正大夫离居，莫知我勚。三事大夫，莫肯夙夜。邦君诸侯，莫肯朝夕。庶曰式臧，覆出为恶。", "sentences": ["周宗既灭，靡所止戾。", "正大夫离居，莫知我勚。", "三事大夫，莫肯夙夜。", "邦君诸侯，莫肯朝夕。", "庶曰式臧，覆出为恶。"], "notes": "", "page": null}, {"text": "如何昊天，辟言不信。如彼行迈，则靡所臻。凡百君子，各敬尔身。胡不相畏，不畏于天？", "sentences": ["如何昊天，辟言不信。", "如彼行迈，则靡所臻。", "凡百君子，各敬尔身。", "胡不相畏，不畏于天？"], "notes": "", "page": null}, {"text": "戎成不退，饥成不遂。曾我暬御，惨惨日瘁。凡百君子，莫肯用讯。听言则答，谮言则退。", "sentences": ["戎成不退，饥成不遂。", "曾我暬御，惨惨日瘁。", "凡百君子，莫肯用讯。", "听言则答，谮言则退。"], "notes": "", "page": null}, {"text": "哀哉不能言，匪舌是出，维躬是瘁。哿矣能言，巧言如流，俾躬处休！", "sentences": ["哀哉不能言，匪舌是出，维躬是瘁。", "哿矣能言，巧言如流，俾躬处休！"], "notes": "", "page": null}, {"text": "维曰予仕，孔棘且殆。云不何使，得罪于天子；亦云可使，怨及朋友。", "sentences": ["维曰予仕，孔棘且殆。", "云不何使，得罪于天子；亦云可使，怨及朋友。"], "notes": "", "page": null}, {"text": "谓尔迁于王都。曰予未有室家。鼠思泣血，无言不疾。昔尔出居，谁从作尔室？", "sentences": ["谓尔迁于王都。", "曰予未有室家。", "鼠思泣血，无言不疾。", "昔尔出居，谁从作尔室？"], "notes": "", "page": null}]}, {"id": "p195", "title": "小旻", "section": "小雅", "group": "节南山之什", "intro": "《小旻》收于《诗经·小雅·节南山之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "旻天疾威，敷于下土。谋犹回遹，何日斯沮？谋臧不从，不臧覆用。我视谋犹，亦孔之邛。", "sentences": ["旻天疾威，敷于下土。", "谋犹回遹，何日斯沮？", "谋臧不从，不臧覆用。", "我视谋犹，亦孔之邛。"], "notes": "", "page": null}, {"text": "潝潝訿訿，亦孔之哀。谋之其臧，则具是违。谋之不臧，则具是依。我视谋犹，伊于胡厎。", "sentences": ["潝潝訿訿，亦孔之哀。", "谋之其臧，则具是违。", "谋之不臧，则具是依。", "我视谋犹，伊于胡厎。"], "notes": "", "page": null}, {"text": "我龟既厌，不我告犹。谋夫孔多，是用不集。发言盈庭，谁敢执其咎？如匪行迈谋，是用不得于道。", "sentences": ["我龟既厌，不我告犹。", "谋夫孔多，是用不集。", "发言盈庭，谁敢执其咎？", "如匪行迈谋，是用不得于道。"], "notes": "", "page": null}, {"text": "哀哉为犹，匪先民是程，匪大犹是经。维迩言是听，维迩言是争。如彼筑室于道谋，是用不溃于成。", "sentences": ["哀哉为犹，匪先民是程，匪大犹是经。", "维迩言是听，维迩言是争。", "如彼筑室于道谋，是用不溃于成。"], "notes": "", "page": null}, {"text": "国虽靡止，或圣或否。民虽靡膴，或哲或谋，或肃或艾。如彼泉流，无沦胥以败。", "sentences": ["国虽靡止，或圣或否。", "民虽靡膴，或哲或谋，或肃或艾。", "如彼泉流，无沦胥以败。"], "notes": "", "page": null}, {"text": "不敢暴虎，不敢冯河。人知其一，莫知其他。战战兢兢，如临深渊，如履薄冰。", "sentences": ["不敢暴虎，不敢冯河。", "人知其一，莫知其他。", "战战兢兢，如临深渊，如履薄冰。"], "notes": "", "page": null}]}, {"id": "p196", "title": "小宛", "section": "小雅", "group": "节南山之什", "intro": "《小宛》收于《诗经·小雅·节南山之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "宛彼鸣鸠，翰飞戾天。我心忧伤，念昔先人。明发不寐，有怀二人。", "sentences": ["宛彼鸣鸠，翰飞戾天。", "我心忧伤，念昔先人。", "明发不寐，有怀二人。"], "notes": "", "page": null}, {"text": "人之齐圣，饮酒温克。彼昏不知，一醉日富。各敬尔仪，天命不又。", "sentences": ["人之齐圣，饮酒温克。", "彼昏不知，一醉日富。", "各敬尔仪，天命不又。"], "notes": "", "page": null}, {"text": "中原有菽，庶民采之。螟蛉有子，蜾蠃负之。教诲尔子，式穀似之。", "sentences": ["中原有菽，庶民采之。", "螟蛉有子，蜾蠃负之。", "教诲尔子，式穀似之。"], "notes": "", "page": null}, {"text": "题彼脊令，载飞载鸣。我日斯迈，而月斯征。夙兴夜寐，毋忝尔所生。", "sentences": ["题彼脊令，载飞载鸣。", "我日斯迈，而月斯征。", "夙兴夜寐，毋忝尔所生。"], "notes": "", "page": null}, {"text": "交交桑扈，率场啄粟。哀我填寡，宜岸宜狱。握粟出卜，自何能穀？", "sentences": ["交交桑扈，率场啄粟。", "哀我填寡，宜岸宜狱。", "握粟出卜，自何能穀？"], "notes": "", "page": null}, {"text": "温温恭人，如集于木。惴惴小心，如临于谷。战战兢兢，如履薄冰。", "sentences": ["温温恭人，如集于木。", "惴惴小心，如临于谷。", "战战兢兢，如履薄冰。"], "notes": "", "page": null}]}, {"id": "p197", "title": "小弁", "section": "小雅", "group": "节南山之什", "intro": "《小弁》收于《诗经·小雅·节南山之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "弁彼鸴斯，归飞提提。民莫不穀，我独于罹。何辜于天？我罪伊何？心之忧矣，云如之何？", "sentences": ["弁彼鸴斯，归飞提提。", "民莫不穀，我独于罹。", "何辜于天？", "我罪伊何？", "心之忧矣，云如之何？"], "notes": "", "page": null}, {"text": "踧踧周道，鞫为茂草。我心忧伤，惄焉如捣。假寐永叹，维忧用老。心之忧矣，疢如疾首。", "sentences": ["踧踧周道，鞫为茂草。", "我心忧伤，惄焉如捣。", "假寐永叹，维忧用老。", "心之忧矣，疢如疾首。"], "notes": "", "page": null}, {"text": "维桑与梓，必恭敬止。靡瞻匪父，靡依匪母。不属于毛？不罹于里？天之生我，我辰安在？", "sentences": ["维桑与梓，必恭敬止。", "靡瞻匪父，靡依匪母。", "不属于毛？", "不罹于里？", "天之生我，我辰安在？"], "notes": "", "page": null}, {"text": "菀彼柳斯，鸣蜩嘒嘒，有漼者渊，萑苇淠淠。譬彼舟流，不知所届，心之忧矣，不遑假寐。", "sentences": ["菀彼柳斯，鸣蜩嘒嘒，有漼者渊，萑苇淠淠。", "譬彼舟流，不知所届，心之忧矣，不遑假寐。"], "notes": "", "page": null}, {"text": "鹿斯之奔，维足伎伎。雉之朝雊，尚求其雌。譬彼坏木，疾用无枝。心之忧矣，宁莫之知？", "sentences": ["鹿斯之奔，维足伎伎。", "雉之朝雊，尚求其雌。", "譬彼坏木，疾用无枝。", "心之忧矣，宁莫之知？"], "notes": "", "page": null}, {"text": "相彼投兔，尚或先之。行有死人，尚或墐之。君子秉心，维其忍之。心之忧矣，涕既陨之。", "sentences": ["相彼投兔，尚或先之。", "行有死人，尚或墐之。", "君子秉心，维其忍之。", "心之忧矣，涕既陨之。"], "notes": "", "page": null}, {"text": "君子信谗，如或酬之。君子不惠，不舒究之。伐木掎矣，析薪扡矣。舍彼有罪，予之佗矣。", "sentences": ["君子信谗，如或酬之。", "君子不惠，不舒究之。", "伐木掎矣，析薪扡矣。", "舍彼有罪，予之佗矣。"], "notes": "", "page": null}, {"text": "莫高匪山，莫浚匪泉。君子无易由言，耳属于垣。无逝我梁，无发我笱。我躬不阅，遑恤我后。", "sentences": ["莫高匪山，莫浚匪泉。", "君子无易由言，耳属于垣。", "无逝我梁，无发我笱。", "我躬不阅，遑恤我后。"], "notes": "", "page": null}]}, {"id": "p198", "title": "巧言", "section": "小雅", "group": "节南山之什", "intro": "《巧言》收于《诗经·小雅·节南山之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "悠悠昊天，曰父母且。无罪无辜，乱如此幠。昊天已威，予慎无罪。昊天大幠，予慎无辜。", "sentences": ["悠悠昊天，曰父母且。", "无罪无辜，乱如此幠。", "昊天已威，予慎无罪。", "昊天大幠，予慎无辜。"], "notes": "", "page": null}, {"text": "乱之初生，僭始既涵。乱之又生，君子信谗。君子如怒，乱庶遄沮。君子如祉，乱庶遄已。", "sentences": ["乱之初生，僭始既涵。", "乱之又生，君子信谗。", "君子如怒，乱庶遄沮。", "君子如祉，乱庶遄已。"], "notes": "", "page": null}, {"text": "君子屡盟，乱是用长。君子信盗，乱是用暴。盗言孔甘，乱是用餤。匪其止共，维王之邛。", "sentences": ["君子屡盟，乱是用长。", "君子信盗，乱是用暴。", "盗言孔甘，乱是用餤。", "匪其止共，维王之邛。"], "notes": "", "page": null}, {"text": "奕奕寝庙，君子作之。秩秩大猷，圣人莫之。他人有心，予忖度之。跃跃毚兔，遇犬获之。", "sentences": ["奕奕寝庙，君子作之。", "秩秩大猷，圣人莫之。", "他人有心，予忖度之。", "跃跃毚兔，遇犬获之。"], "notes": "", "page": null}, {"text": "荏染柔木，君子树之。往来行言，心焉数之。蛇蛇硕言，出自口矣。巧言如簧，颜之厚矣。", "sentences": ["荏染柔木，君子树之。", "往来行言，心焉数之。", "蛇蛇硕言，出自口矣。", "巧言如簧，颜之厚矣。"], "notes": "", "page": null}, {"text": "彼何人斯？居河之麋。无拳无勇，职为乱阶。既微且尰，尔勇伊何？为犹将多，尔居徒几何？", "sentences": ["彼何人斯？", "居河之麋。", "无拳无勇，职为乱阶。", "既微且尰，尔勇伊何？", "为犹将多，尔居徒几何？"], "notes": "", "page": null}]}, {"id": "p199", "title": "何人斯", "section": "小雅", "group": "节南山之什", "intro": "《何人斯》收于《诗经·小雅·节南山之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "彼何人斯？其心孔艰。胡逝我梁，不入我门？伊谁云从？维暴之云。", "sentences": ["彼何人斯？", "其心孔艰。", "胡逝我梁，不入我门？", "伊谁云从？", "维暴之云。"], "notes": "", "page": null}, {"text": "二人从行，谁为此祸？胡逝我梁，不入唁我？始者不如今，云不我可", "sentences": ["二人从行，谁为此祸？", "胡逝我梁，不入唁我？", "始者不如今，云不我可"], "notes": "", "page": null}, {"text": "彼何人斯？胡逝我陈？我闻其声，不见其身。不愧于人？不畏于天？", "sentences": ["彼何人斯？", "胡逝我陈？", "我闻其声，不见其身。", "不愧于人？", "不畏于天？"], "notes": "", "page": null}, {"text": "彼何人斯？其为飘风。胡不自北？胡不自南？胡逝我梁？絺搅我心。", "sentences": ["彼何人斯？", "其为飘风。", "胡不自北？", "胡不自南？", "胡逝我梁？", "絺搅我心。"], "notes": "", "page": null}, {"text": "尔之安行，亦不遑舍。尔之亟行，遑脂尔车。一者之来，云何其盱。", "sentences": ["尔之安行，亦不遑舍。", "尔之亟行，遑脂尔车。", "一者之来，云何其盱。"], "notes": "", "page": null}, {"text": "尔还而入，我心易也。还而不入，否难知也。一者之来，俾我絺也。", "sentences": ["尔还而入，我心易也。", "还而不入，否难知也。", "一者之来，俾我絺也。"], "notes": "", "page": null}, {"text": "伯氏吹埙，仲氏吹篪。及尔如贯，谅不我郑出此三物，以诅尔斯。", "sentences": ["伯氏吹埙，仲氏吹篪。", "及尔如贯，谅不我郑出此三物，以诅尔斯。"], "notes": "", "page": null}, {"text": "为鬼为蜮，则不可得。有靦面目，视人罔极。作此好歌，以极反侧。", "sentences": ["为鬼为蜮，则不可得。", "有靦面目，视人罔极。", "作此好歌，以极反侧。"], "notes": "", "page": null}]}, {"id": "p200", "title": "巷伯", "section": "小雅", "group": "节南山之什", "intro": "《巷伯》收于《诗经·小雅·节南山之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "萋兮斐兮，成是贝锦。彼谮人者，亦已大甚！", "sentences": ["萋兮斐兮，成是贝锦。", "彼谮人者，亦已大甚！"], "notes": "", "page": null}, {"text": "哆兮侈兮，成是南箕。彼谮人者，谁适与谋。", "sentences": ["哆兮侈兮，成是南箕。", "彼谮人者，谁适与谋。"], "notes": "", "page": null}, {"text": "缉缉翩翩，谋欲谮人。慎尔言也，谓尔不信。", "sentences": ["缉缉翩翩，谋欲谮人。", "慎尔言也，谓尔不信。"], "notes": "", "page": null}, {"text": "捷捷幡幡，谋欲谮言。岂不尔受？既其女迁。", "sentences": ["捷捷幡幡，谋欲谮言。", "岂不尔受？", "既其女迁。"], "notes": "", "page": null}, {"text": "骄人好好，劳人草草。苍天苍天，视彼骄人，矜此劳人。", "sentences": ["骄人好好，劳人草草。", "苍天苍天，视彼骄人，矜此劳人。"], "notes": "", "page": null}, {"text": "彼谮人者，谁适与谋？取彼谮人，投畀豺虎。豺虎不食，投畀有北。有北不受，投畀有昊！", "sentences": ["彼谮人者，谁适与谋？", "取彼谮人，投畀豺虎。", "豺虎不食，投畀有北。", "有北不受，投畀有昊！"], "notes": "", "page": null}, {"text": "杨园之道，猗于亩丘。寺人孟子，作为此诗。凡百君子，敬而听之。", "sentences": ["杨园之道，猗于亩丘。", "寺人孟子，作为此诗。", "凡百君子，敬而听之。"], "notes": "", "page": null}]}, {"id": "p201", "title": "谷风", "section": "小雅", "group": "谷风之什", "intro": "《谷风》收于《诗经·小雅·谷风之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "习习谷风，维风及雨。将恐将惧，维予与女。将安将乐，女转弃予。", "sentences": ["习习谷风，维风及雨。", "将恐将惧，维予与女。", "将安将乐，女转弃予。"], "notes": "", "page": null}, {"text": "习习谷风，维风及颓。将恐将惧，置予于怀。将安将乐，弃予如遗。", "sentences": ["习习谷风，维风及颓。", "将恐将惧，置予于怀。", "将安将乐，弃予如遗。"], "notes": "", "page": null}, {"text": "习习谷风，维山崔嵬。无草不死，无木不萎。忘我大德，思我小怨。", "sentences": ["习习谷风，维山崔嵬。", "无草不死，无木不萎。", "忘我大德，思我小怨。"], "notes": "", "page": null}]}, {"id": "p202", "title": "蓼莪", "section": "小雅", "group": "谷风之什", "intro": "《蓼莪》收于《诗经·小雅·谷风之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "蓼蓼者莪，匪莪伊蒿。哀哀父母，生我劬劳。", "sentences": ["蓼蓼者莪，匪莪伊蒿。", "哀哀父母，生我劬劳。"], "notes": "", "page": null}, {"text": "蓼蓼者莪，匪莪伊蔚。哀哀父母，生我劳瘁。", "sentences": ["蓼蓼者莪，匪莪伊蔚。", "哀哀父母，生我劳瘁。"], "notes": "", "page": null}, {"text": "瓶之罄矣，维罍之耻。鲜民之生，不如死之久矣。无父何怙？无母何恃？出则衔恤，入则靡至。", "sentences": ["瓶之罄矣，维罍之耻。", "鲜民之生，不如死之久矣。", "无父何怙？", "无母何恃？", "出则衔恤，入则靡至。"], "notes": "", "page": null}, {"text": "父兮生我，母兮鞠我。抚我畜我，长我育我，顾我复我，出入腹我。欲报之德。昊天罔极！", "sentences": ["父兮生我，母兮鞠我。", "抚我畜我，长我育我，顾我复我，出入腹我。", "欲报之德。", "昊天罔极！"], "notes": "", "page": null}, {"text": "南山烈烈，飘风发发。民莫不穀，我独何害！南山律律，飘风弗弗。民莫不穀，我独不卒！", "sentences": ["南山烈烈，飘风发发。", "民莫不穀，我独何害！", "南山律律，飘风弗弗。", "民莫不穀，我独不卒！"], "notes": "", "page": null}]}, {"id": "p203", "title": "大东", "section": "小雅", "group": "谷风之什", "intro": "《大东》收于《诗经·小雅·谷风之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "有饛簋飧，有捄棘匕。周道如砥，其直如矢。君子所履，小人所视。眷言顾之，潸焉出涕。", "sentences": ["有饛簋飧，有捄棘匕。", "周道如砥，其直如矢。", "君子所履，小人所视。", "眷言顾之，潸焉出涕。"], "notes": "", "page": null}, {"text": "小东大东，杼柚其空。纠纠葛屦，可以履霜。佻佻公子，行彼周行。既往既来，使我心疚。", "sentences": ["小东大东，杼柚其空。", "纠纠葛屦，可以履霜。", "佻佻公子，行彼周行。", "既往既来，使我心疚。"], "notes": "", "page": null}, {"text": "有冽氿泉，无浸获薪。契契寤叹，哀我惮人。薪是获薪，尚可载也。哀我惮人，亦可息也。", "sentences": ["有冽氿泉，无浸获薪。", "契契寤叹，哀我惮人。", "薪是获薪，尚可载也。", "哀我惮人，亦可息也。"], "notes": "", "page": null}, {"text": "东人之子，职劳不来。西人之子，粲粲衣服。舟人之子，熊罴是裘。私人之子，百僚是试。", "sentences": ["东人之子，职劳不来。", "西人之子，粲粲衣服。", "舟人之子，熊罴是裘。", "私人之子，百僚是试。"], "notes": "", "page": null}, {"text": "或以其酒，不以其浆。鞙鞙佩璲，不以其长。维天有汉，监亦有光。跂彼织女，终日七襄。", "sentences": ["或以其酒，不以其浆。", "鞙鞙佩璲，不以其长。", "维天有汉，监亦有光。", "跂彼织女，终日七襄。"], "notes": "", "page": null}, {"text": "虽则七襄，不成报章。睆彼牵牛，不以服箱。东有启明，西有长庚。有捄天毕，载施之行。", "sentences": ["虽则七襄，不成报章。", "睆彼牵牛，不以服箱。", "东有启明，西有长庚。", "有捄天毕，载施之行。"], "notes": "", "page": null}, {"text": "维南有箕，不可以簸扬。维北有斗，不可以挹酒浆。维南有箕，载翕其舌。维北有斗，西柄之揭。", "sentences": ["维南有箕，不可以簸扬。", "维北有斗，不可以挹酒浆。", "维南有箕，载翕其舌。", "维北有斗，西柄之揭。"], "notes": "", "page": null}]}, {"id": "p204", "title": "四月", "section": "小雅", "group": "谷风之什", "intro": "《四月》收于《诗经·小雅·谷风之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "四月维夏，六月徂署。先祖匪人，胡宁忍予？", "sentences": ["四月维夏，六月徂署。", "先祖匪人，胡宁忍予？"], "notes": "", "page": null}, {"text": "秋日凄凄，百卉具腓。乱离瘼矣，爰其适归？", "sentences": ["秋日凄凄，百卉具腓。", "乱离瘼矣，爰其适归？"], "notes": "", "page": null}, {"text": "冬日烈烈，飘风发发。民莫不穀，我独何害？", "sentences": ["冬日烈烈，飘风发发。", "民莫不穀，我独何害？"], "notes": "", "page": null}, {"text": "山有嘉卉，侯栗侯梅。废为残贼，莫知其尤！", "sentences": ["山有嘉卉，侯栗侯梅。", "废为残贼，莫知其尤！"], "notes": "", "page": null}, {"text": "相彼泉水，载清载浊。我日构祸，曷云能穀？", "sentences": ["相彼泉水，载清载浊。", "我日构祸，曷云能穀？"], "notes": "", "page": null}, {"text": "滔滔江汉，南国之纪。尽瘁以仕，宁莫我有？", "sentences": ["滔滔江汉，南国之纪。", "尽瘁以仕，宁莫我有？"], "notes": "", "page": null}, {"text": "匪鹑匪鸢，翰飞戾天。匪鳣匪鲔，潜逃于渊。", "sentences": ["匪鹑匪鸢，翰飞戾天。", "匪鳣匪鲔，潜逃于渊。"], "notes": "", "page": null}, {"text": "山有蕨薇，隰有杞桋。君子作歌，维以告哀。", "sentences": ["山有蕨薇，隰有杞桋。", "君子作歌，维以告哀。"], "notes": "", "page": null}]}, {"id": "p205", "title": "北山", "section": "小雅", "group": "谷风之什", "intro": "《北山》收于《诗经·小雅·谷风之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "陟彼北山，言采其杞。偕偕士子，朝夕从事。王事靡盬，忧我父母。", "sentences": ["陟彼北山，言采其杞。", "偕偕士子，朝夕从事。", "王事靡盬，忧我父母。"], "notes": "", "page": null}, {"text": "溥天之下，莫非王土；率土之滨，莫非王臣。大夫不均，我从事独贤。", "sentences": ["溥天之下，莫非王土；率土之滨，莫非王臣。", "大夫不均，我从事独贤。"], "notes": "", "page": null}, {"text": "四牡彭彭，王事傍傍。嘉我未老，鲜我方将。旅力方刚，经营四方。", "sentences": ["四牡彭彭，王事傍傍。", "嘉我未老，鲜我方将。", "旅力方刚，经营四方。"], "notes": "", "page": null}, {"text": "或燕燕居息，或尽瘁事国；或息偃在床，或不已于行。", "sentences": ["或燕燕居息，或尽瘁事国；或息偃在床，或不已于行。"], "notes": "", "page": null}, {"text": "或不知叫号，或惨惨劬劳；或栖迟偃仰，或王事鞅掌。", "sentences": ["或不知叫号，或惨惨劬劳；或栖迟偃仰，或王事鞅掌。"], "notes": "", "page": null}, {"text": "或湛乐饮酒，或惨惨畏咎；或出入风议，或靡事不为。", "sentences": ["或湛乐饮酒，或惨惨畏咎；或出入风议，或靡事不为。"], "notes": "", "page": null}]}, {"id": "p206", "title": "无将大车", "section": "小雅", "group": "谷风之什", "intro": "《无将大车》收于《诗经·小雅·谷风之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "无将大车，祇自尘兮。无思百忧，祇自疧兮。", "sentences": ["无将大车，祇自尘兮。", "无思百忧，祇自疧兮。"], "notes": "", "page": null}, {"text": "无将大车，维尘冥冥。无思百忧，不出于颎。", "sentences": ["无将大车，维尘冥冥。", "无思百忧，不出于颎。"], "notes": "", "page": null}, {"text": "无将大车，维尘雍兮。无思百忧，祇自重兮。", "sentences": ["无将大车，维尘雍兮。", "无思百忧，祇自重兮。"], "notes": "", "page": null}]}, {"id": "p207", "title": "小明", "section": "小雅", "group": "谷风之什", "intro": "《小明》收于《诗经·小雅·谷风之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "明明上天，照临下土。我征徂西，至于艽野。二月初吉，载离寒暑。", "sentences": ["明明上天，照临下土。", "我征徂西，至于艽野。", "二月初吉，载离寒暑。"], "notes": "", "page": null}, {"text": "心之忧矣，其毒大苦。念彼共人，涕零如雨。岂不怀归？畏此罪罟！", "sentences": ["心之忧矣，其毒大苦。", "念彼共人，涕零如雨。", "岂不怀归？", "畏此罪罟！"], "notes": "", "page": null}, {"text": "昔我往矣，日月方除。曷云其还？岁聿云莫。念我独兮，我事孔庶。", "sentences": ["昔我往矣，日月方除。", "曷云其还？", "岁聿云莫。", "念我独兮，我事孔庶。"], "notes": "", "page": null}, {"text": "心之忧矣，惮我不暇。念彼共人，眷眷怀顾！岂不怀归？畏此谴怒。", "sentences": ["心之忧矣，惮我不暇。", "念彼共人，眷眷怀顾！", "岂不怀归？", "畏此谴怒。"], "notes": "", "page": null}, {"text": "昔我往矣，日月方奥。曷云其还？政事愈蹙。岁聿云莫，采萧获菽。", "sentences": ["昔我往矣，日月方奥。", "曷云其还？", "政事愈蹙。", "岁聿云莫，采萧获菽。"], "notes": "", "page": null}, {"text": "心之忧矣，自诒伊戚。念彼共人，兴言出宿。岂不怀归？畏此反覆。", "sentences": ["心之忧矣，自诒伊戚。", "念彼共人，兴言出宿。", "岂不怀归？", "畏此反覆。"], "notes": "", "page": null}, {"text": "嗟尔君子，无恒安处。靖共尔位，正直是与。神之听之，式穀以女。", "sentences": ["嗟尔君子，无恒安处。", "靖共尔位，正直是与。", "神之听之，式穀以女。"], "notes": "", "page": null}, {"text": "嗟尔君子，无恒安息。靖共尔位，好是正直。神之听之，介尔景福。", "sentences": ["嗟尔君子，无恒安息。", "靖共尔位，好是正直。", "神之听之，介尔景福。"], "notes": "", "page": null}]}, {"id": "p208", "title": "鼓钟", "section": "小雅", "group": "谷风之什", "intro": "《鼓钟》收于《诗经·小雅·谷风之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "鼓钟将将，淮水汤汤，忧心且伤。淑人君子，怀允不忘。", "sentences": ["鼓钟将将，淮水汤汤，忧心且伤。", "淑人君子，怀允不忘。"], "notes": "", "page": null}, {"text": "鼓钟喈喈，淮水湝湝，忧心且悲。淑人君子，其德不回。", "sentences": ["鼓钟喈喈，淮水湝湝，忧心且悲。", "淑人君子，其德不回。"], "notes": "", "page": null}, {"text": "鼓钟伐鼛，淮有三洲，忧心且妯。淑人君子，其德不犹。", "sentences": ["鼓钟伐鼛，淮有三洲，忧心且妯。", "淑人君子，其德不犹。"], "notes": "", "page": null}, {"text": "鼓钟钦钦，鼓瑟鼓琴，笙磬同音。以雅以南，以龠不僭。", "sentences": ["鼓钟钦钦，鼓瑟鼓琴，笙磬同音。", "以雅以南，以龠不僭。"], "notes": "", "page": null}]}, {"id": "p209", "title": "楚茨", "section": "小雅", "group": "谷风之什", "intro": "《楚茨》收于《诗经·小雅·谷风之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "楚楚者茨，言抽其棘，自昔何为？我蓺黍稷。我黍与与，我稷翼翼。", "sentences": ["楚楚者茨，言抽其棘，自昔何为？", "我蓺黍稷。", "我黍与与，我稷翼翼。"], "notes": "", "page": null}, {"text": "我仓既盈，我庾维亿。以为酒食，以享以祀，以妥以侑，以介景福。", "sentences": ["我仓既盈，我庾维亿。", "以为酒食，以享以祀，以妥以侑，以介景福。"], "notes": "", "page": null}, {"text": "济济跄跄，絜尔牛羊，以往烝尝。或剥或亨，或四或将。祝祭于祊，", "sentences": ["济济跄跄，絜尔牛羊，以往烝尝。", "或剥或亨，或四或将。", "祝祭于祊，"], "notes": "", "page": null}, {"text": "祀事孔明。先祖是皇，神保是飨。孝孙有庆，报以介福，万寿无疆！", "sentences": ["祀事孔明。", "先祖是皇，神保是飨。", "孝孙有庆，报以介福，万寿无疆！"], "notes": "", "page": null}, {"text": "执爨踖踖，为俎孔硕，或燔或炙。君妇莫莫，为豆孔庶。为宾为客，", "sentences": ["执爨踖踖，为俎孔硕，或燔或炙。", "君妇莫莫，为豆孔庶。", "为宾为客，"], "notes": "", "page": null}, {"text": "献酬交错。礼仪卒度，笑语卒获。神保是格，报以介福，万寿攸酢！", "sentences": ["献酬交错。", "礼仪卒度，笑语卒获。", "神保是格，报以介福，万寿攸酢！"], "notes": "", "page": null}, {"text": "我孔戁矣，式礼莫愆。工祝致告，徂赉孝孙。苾芬孝祀，神嗜饮食。", "sentences": ["我孔戁矣，式礼莫愆。", "工祝致告，徂赉孝孙。", "苾芬孝祀，神嗜饮食。"], "notes": "", "page": null}, {"text": "卜尔百福，如几如式。既齐既稷，既匡既敕。永锡尔极，时万时亿！", "sentences": ["卜尔百福，如几如式。", "既齐既稷，既匡既敕。", "永锡尔极，时万时亿！"], "notes": "", "page": null}, {"text": "礼仪既备，钟鼓既戒，孝孙徂位，工祝致告，神具醉止，皇尸载起。", "sentences": ["礼仪既备，钟鼓既戒，孝孙徂位，工祝致告，神具醉止，皇尸载起。"], "notes": "", "page": null}, {"text": "鼓钟送尸，神保聿归。诸宰君妇，废彻不迟。诸父兄弟，备言燕私。", "sentences": ["鼓钟送尸，神保聿归。", "诸宰君妇，废彻不迟。", "诸父兄弟，备言燕私。"], "notes": "", "page": null}, {"text": "乐具入奏，以绥后禄。尔肴既将，莫怨具庆。既醉既饱，小大稽首。", "sentences": ["乐具入奏，以绥后禄。", "尔肴既将，莫怨具庆。", "既醉既饱，小大稽首。"], "notes": "", "page": null}, {"text": "神嗜饮食，使君寿考。孔惠孔时，维其尽之。子子孙孙，勿替引之！", "sentences": ["神嗜饮食，使君寿考。", "孔惠孔时，维其尽之。", "子子孙孙，勿替引之！"], "notes": "", "page": null}]}, {"id": "p210", "title": "信南山", "section": "小雅", "group": "谷风之什", "intro": "《信南山》收于《诗经·小雅·谷风之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "信彼南山，维禹甸之。畇畇原隰，曾孙田之。我疆我理，南东其亩。", "sentences": ["信彼南山，维禹甸之。", "畇畇原隰，曾孙田之。", "我疆我理，南东其亩。"], "notes": "", "page": null}, {"text": "上天同云。雨雪雰雰，益之以霡霂。既优既渥，既沾既足。生我百谷。", "sentences": ["上天同云。", "雨雪雰雰，益之以霡霂。", "既优既渥，既沾既足。", "生我百谷。"], "notes": "", "page": null}, {"text": "疆埸翼翼，黍稷彧彧。曾孙之穑，以为酒食。畀我尸宾，寿考万年。", "sentences": ["疆埸翼翼，黍稷彧彧。", "曾孙之穑，以为酒食。", "畀我尸宾，寿考万年。"], "notes": "", "page": null}, {"text": "中田有庐，疆埸有瓜。是剥是菹，献之皇祖。曾孙寿考，受天之祜。", "sentences": ["中田有庐，疆埸有瓜。", "是剥是菹，献之皇祖。", "曾孙寿考，受天之祜。"], "notes": "", "page": null}, {"text": "祭以清酒，从以骍牡，享于祖考。执其鸾刀，以启其毛，取其血膋。", "sentences": ["祭以清酒，从以骍牡，享于祖考。", "执其鸾刀，以启其毛，取其血膋。"], "notes": "", "page": null}, {"text": "是烝是享，苾苾芬芬。祀事孔明，先祖是皇。报以介福。万寿无疆。", "sentences": ["是烝是享，苾苾芬芬。", "祀事孔明，先祖是皇。", "报以介福。", "万寿无疆。"], "notes": "", "page": null}]}, {"id": "p211", "title": "甫田", "section": "小雅", "group": "甫田之什", "intro": "《甫田》收于《诗经·小雅·甫田之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "倬彼甫田，岁取十千。我取其陈，食我农人。自古有年。", "sentences": ["倬彼甫田，岁取十千。", "我取其陈，食我农人。", "自古有年。"], "notes": "", "page": null}, {"text": "今适南亩，或耘或耔。黍稷薿薿，攸介攸止，烝我髦士。", "sentences": ["今适南亩，或耘或耔。", "黍稷薿薿，攸介攸止，烝我髦士。"], "notes": "", "page": null}, {"text": "以我齐明，与我牺羊，以社以方。我田既臧，农夫之庆。", "sentences": ["以我齐明，与我牺羊，以社以方。", "我田既臧，农夫之庆。"], "notes": "", "page": null}, {"text": "琴瑟击鼓，以御田祖。以祈甘雨，以介我稷黍，以穀我士女。", "sentences": ["琴瑟击鼓，以御田祖。", "以祈甘雨，以介我稷黍，以穀我士女。"], "notes": "", "page": null}, {"text": "曾孙来止，以其妇子。馌彼南亩，田畯至喜。攘其左右，", "sentences": ["曾孙来止，以其妇子。", "馌彼南亩，田畯至喜。", "攘其左右，"], "notes": "", "page": null}, {"text": "尝其旨否。禾易长亩，终善且有。曾孙不怒，农夫克敏。", "sentences": ["尝其旨否。", "禾易长亩，终善且有。", "曾孙不怒，农夫克敏。"], "notes": "", "page": null}, {"text": "曾孙之稼，如茨如梁。曾孙之庾，如坻如京。乃求千斯仓，", "sentences": ["曾孙之稼，如茨如梁。", "曾孙之庾，如坻如京。", "乃求千斯仓，"], "notes": "", "page": null}, {"text": "乃求万斯箱。黍稷稻粱，农夫之庆。报以介福，万寿无疆。", "sentences": ["乃求万斯箱。", "黍稷稻粱，农夫之庆。", "报以介福，万寿无疆。"], "notes": "", "page": null}]}, {"id": "p212", "title": "大田", "section": "小雅", "group": "甫田之什", "intro": "《大田》收于《诗经·小雅·甫田之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "大田多稼，既种既戒，既备乃事。以我覃耜，俶载南亩。", "sentences": ["大田多稼，既种既戒，既备乃事。", "以我覃耜，俶载南亩。"], "notes": "", "page": null}, {"text": "播厥百谷，既庭且硕，曾孙是若。", "sentences": ["播厥百谷，既庭且硕，曾孙是若。"], "notes": "", "page": null}, {"text": "既方既皂，既坚既好，不稂不莠。去其螟螣，及其蟊贼，", "sentences": ["既方既皂，既坚既好，不稂不莠。", "去其螟螣，及其蟊贼，"], "notes": "", "page": null}, {"text": "无害我田稚。田祖有神，秉畀炎火。", "sentences": ["无害我田稚。", "田祖有神，秉畀炎火。"], "notes": "", "page": null}, {"text": "有渰萋萋，兴雨祈祈。雨我公田，遂及我私。彼有不获稚，", "sentences": ["有渰萋萋，兴雨祈祈。", "雨我公田，遂及我私。", "彼有不获稚，"], "notes": "", "page": null}, {"text": "此有不敛穧，彼有遗秉，此有滞穗，伊寡妇之利。", "sentences": ["此有不敛穧，彼有遗秉，此有滞穗，伊寡妇之利。"], "notes": "", "page": null}, {"text": "曾孙来止，以其妇子。馌彼南亩，田畯至喜。来方禋祀，", "sentences": ["曾孙来止，以其妇子。", "馌彼南亩，田畯至喜。", "来方禋祀，"], "notes": "", "page": null}, {"text": "以其骍黑，与其黍稷。以享以祀，以介景福。", "sentences": ["以其骍黑，与其黍稷。", "以享以祀，以介景福。"], "notes": "", "page": null}]}, {"id": "p213", "title": "瞻彼洛矣", "section": "小雅", "group": "甫田之什", "intro": "《瞻彼洛矣》收于《诗经·小雅·甫田之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "瞻彼洛矣，维水泱泱。君子至止，福禄如茨。韎韐有奭，以作六师。", "sentences": ["瞻彼洛矣，维水泱泱。", "君子至止，福禄如茨。", "韎韐有奭，以作六师。"], "notes": "", "page": null}, {"text": "瞻彼洛矣，维水泱泱。君子至止，鞸琫有珌。君子万年，保其家室。", "sentences": ["瞻彼洛矣，维水泱泱。", "君子至止，鞸琫有珌。", "君子万年，保其家室。"], "notes": "", "page": null}, {"text": "瞻彼洛矣，维水泱泱。君子至止，福禄既同。君子万年，保其家邦。", "sentences": ["瞻彼洛矣，维水泱泱。", "君子至止，福禄既同。", "君子万年，保其家邦。"], "notes": "", "page": null}]}, {"id": "p214", "title": "裳裳者华", "section": "小雅", "group": "甫田之什", "intro": "《裳裳者华》收于《诗经·小雅·甫田之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "裳裳者华，其叶湑兮。我觏之子，我心写兮。我心写兮，是以有誉处兮。", "sentences": ["裳裳者华，其叶湑兮。", "我觏之子，我心写兮。", "我心写兮，是以有誉处兮。"], "notes": "", "page": null}, {"text": "裳裳者华，芸其黄矣。我觏之子，维其有章矣。维其有章矣，是以有庆矣。", "sentences": ["裳裳者华，芸其黄矣。", "我觏之子，维其有章矣。", "维其有章矣，是以有庆矣。"], "notes": "", "page": null}, {"text": "裳裳者华，或黄或白。我觏之子，乘其四骆。乘其四骆，六辔沃若。", "sentences": ["裳裳者华，或黄或白。", "我觏之子，乘其四骆。", "乘其四骆，六辔沃若。"], "notes": "", "page": null}, {"text": "左之左之，君子宜之。右之右之，君子有之。维其有之，是以似之。", "sentences": ["左之左之，君子宜之。", "右之右之，君子有之。", "维其有之，是以似之。"], "notes": "", "page": null}]}, {"id": "p215", "title": "桑扈", "section": "小雅", "group": "甫田之什", "intro": "《桑扈》收于《诗经·小雅·甫田之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "交交桑扈，有莺其羽。君子乐胥，受天之祜。", "sentences": ["交交桑扈，有莺其羽。", "君子乐胥，受天之祜。"], "notes": "", "page": null}, {"text": "交交桑扈，有莺其领。君子乐胥，万邦之屏。", "sentences": ["交交桑扈，有莺其领。", "君子乐胥，万邦之屏。"], "notes": "", "page": null}, {"text": "之屏之翰，百辟为宪。不戢不难，受福不那。", "sentences": ["之屏之翰，百辟为宪。", "不戢不难，受福不那。"], "notes": "", "page": null}, {"text": "兕觥其觩，旨酒思柔。彼交匪敖，万福来求。", "sentences": ["兕觥其觩，旨酒思柔。", "彼交匪敖，万福来求。"], "notes": "", "page": null}]}, {"id": "p216", "title": "鸳鸯", "section": "小雅", "group": "甫田之什", "intro": "《鸳鸯》收于《诗经·小雅·甫田之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "鸳鸯于飞，毕之罗之。君子万年，福禄宜之。", "sentences": ["鸳鸯于飞，毕之罗之。", "君子万年，福禄宜之。"], "notes": "", "page": null}, {"text": "鸳鸯在梁，戢其左翼。君子万年，", "sentences": ["鸳鸯在梁，戢其左翼。", "君子万年，"], "notes": "", "page": null}, {"text": "宜其遐福。乘马在厩，摧之秣之。君子万年，福禄艾之。", "sentences": ["宜其遐福。", "乘马在厩，摧之秣之。", "君子万年，福禄艾之。"], "notes": "", "page": null}, {"text": "乘马在厩，秣之摧之。君子万年，福禄绥之。", "sentences": ["乘马在厩，秣之摧之。", "君子万年，福禄绥之。"], "notes": "", "page": null}]}, {"id": "p217", "title": "頍弁", "section": "小雅", "group": "甫田之什", "intro": "《頍弁》收于《诗经·小雅·甫田之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "有頍者弁，实维伊何？尔酒既旨，尔肴既嘉。岂伊异人？兄弟匪他。", "sentences": ["有頍者弁，实维伊何？", "尔酒既旨，尔肴既嘉。", "岂伊异人？", "兄弟匪他。"], "notes": "", "page": null}, {"text": "茑与女萝，施于松柏。未见君子，忧心奕奕；既见君子，庶几说怿。", "sentences": ["茑与女萝，施于松柏。", "未见君子，忧心奕奕；既见君子，庶几说怿。"], "notes": "", "page": null}, {"text": "有頍者弁，实维何期？尔酒既旨，尔肴既时。岂伊异人？兄弟具来。", "sentences": ["有頍者弁，实维何期？", "尔酒既旨，尔肴既时。", "岂伊异人？", "兄弟具来。"], "notes": "", "page": null}, {"text": "茑与女萝，施于松上。未见君子，忧心怲怲；既见君子，庶几有臧。", "sentences": ["茑与女萝，施于松上。", "未见君子，忧心怲怲；既见君子，庶几有臧。"], "notes": "", "page": null}, {"text": "有頍者弁，实维在首。尔酒既旨，尔肴既阜。岂伊异人？兄弟甥舅。", "sentences": ["有頍者弁，实维在首。", "尔酒既旨，尔肴既阜。", "岂伊异人？", "兄弟甥舅。"], "notes": "", "page": null}, {"text": "如彼雨雪，先集维霰。死丧无日，无几相见。乐酒今夕，君子维宴。", "sentences": ["如彼雨雪，先集维霰。", "死丧无日，无几相见。", "乐酒今夕，君子维宴。"], "notes": "", "page": null}]}, {"id": "p218", "title": "车舝", "section": "小雅", "group": "甫田之什", "intro": "《车舝》收于《诗经·小雅·甫田之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "间关车之舝兮，思娈季女逝兮。匪饥匪渴，德音来括。虽无好友？式燕且喜。", "sentences": ["间关车之舝兮，思娈季女逝兮。", "匪饥匪渴，德音来括。", "虽无好友？", "式燕且喜。"], "notes": "", "page": null}, {"text": "依彼平林，有集维鷮。辰彼硕女，令德来教。式燕且誉，好尔无射。", "sentences": ["依彼平林，有集维鷮。", "辰彼硕女，令德来教。", "式燕且誉，好尔无射。"], "notes": "", "page": null}, {"text": "虽无旨酒？式饮庶几。虽无嘉肴？式食庶几。虽无德与女？式歌且舞？", "sentences": ["虽无旨酒？", "式饮庶几。", "虽无嘉肴？", "式食庶几。", "虽无德与女？", "式歌且舞？"], "notes": "", "page": null}, {"text": "陟彼高冈，析其柞薪。析其柞薪，其叶湑兮。鲜我觏尔，我心写兮。", "sentences": ["陟彼高冈，析其柞薪。", "析其柞薪，其叶湑兮。", "鲜我觏尔，我心写兮。"], "notes": "", "page": null}, {"text": "高山仰止，景行行止。四牡騑騑，六辔如琴。觏尔新婚，以慰我心。", "sentences": ["高山仰止，景行行止。", "四牡騑騑，六辔如琴。", "觏尔新婚，以慰我心。"], "notes": "", "page": null}]}, {"id": "p219", "title": "青蝇", "section": "小雅", "group": "甫田之什", "intro": "《青蝇》收于《诗经·小雅·甫田之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "营营青蝇，止于樊。岂弟君子，无信谗言。", "sentences": ["营营青蝇，止于樊。", "岂弟君子，无信谗言。"], "notes": "", "page": null}, {"text": "营营青蝇，止于棘。谗人罔极，交乱四国。", "sentences": ["营营青蝇，止于棘。", "谗人罔极，交乱四国。"], "notes": "", "page": null}, {"text": "营营青蝇，止于榛。谗人罔极，构我二人。", "sentences": ["营营青蝇，止于榛。", "谗人罔极，构我二人。"], "notes": "", "page": null}]}, {"id": "p220", "title": "宾之初筵", "section": "小雅", "group": "甫田之什", "intro": "《宾之初筵》收于《诗经·小雅·甫田之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "宾之初筵，左右秩秩。笾豆有楚，殽核维旅。酒既和旨，饮酒孔偕。", "sentences": ["宾之初筵，左右秩秩。", "笾豆有楚，殽核维旅。", "酒既和旨，饮酒孔偕。"], "notes": "", "page": null}, {"text": "钟鼓既设，举酬逸逸。大侯既抗，弓矢斯张。射夫既同，献尔发功。", "sentences": ["钟鼓既设，举酬逸逸。", "大侯既抗，弓矢斯张。", "射夫既同，献尔发功。"], "notes": "", "page": null}, {"text": "发彼有的，以祈尔爵。", "sentences": ["发彼有的，以祈尔爵。"], "notes": "", "page": null}, {"text": "籥舞笙鼓，乐既和奏。烝衎烈祖，以洽百礼。百礼既至，有壬有林。", "sentences": ["籥舞笙鼓，乐既和奏。", "烝衎烈祖，以洽百礼。", "百礼既至，有壬有林。"], "notes": "", "page": null}, {"text": "锡尔纯嘏，子孙其湛。其湛曰乐，各奏尔能。宾载手仇，室人入又。", "sentences": ["锡尔纯嘏，子孙其湛。", "其湛曰乐，各奏尔能。", "宾载手仇，室人入又。"], "notes": "", "page": null}, {"text": "酌彼康爵，以奏尔时。", "sentences": ["酌彼康爵，以奏尔时。"], "notes": "", "page": null}, {"text": "宾之初筵，温温其恭。其未醉止，威仪反反。曰既醉止，威仪幡幡。", "sentences": ["宾之初筵，温温其恭。", "其未醉止，威仪反反。", "曰既醉止，威仪幡幡。"], "notes": "", "page": null}, {"text": "舍其坐迁，屡舞仙仙。其未醉止，威仪抑抑。曰既醉止，威仪抑抑。", "sentences": ["舍其坐迁，屡舞仙仙。", "其未醉止，威仪抑抑。", "曰既醉止，威仪抑抑。"], "notes": "", "page": null}, {"text": "是曰既醉，不知其秩。", "sentences": ["是曰既醉，不知其秩。"], "notes": "", "page": null}, {"text": "宾既醉止，载号载呶。乱我笾豆，屡舞僛僛。是曰既醉，不知其邮。", "sentences": ["宾既醉止，载号载呶。", "乱我笾豆，屡舞僛僛。", "是曰既醉，不知其邮。"], "notes": "", "page": null}, {"text": "侧弁之俄，屡舞傞傞。既醉而出，并受其福。醉而不出，是谓伐德。", "sentences": ["侧弁之俄，屡舞傞傞。", "既醉而出，并受其福。", "醉而不出，是谓伐德。"], "notes": "", "page": null}, {"text": "饮酒孔嘉，维其令仪。", "sentences": ["饮酒孔嘉，维其令仪。"], "notes": "", "page": null}, {"text": "凡此饮酒，或醉或否。既立之监，或佐之史。彼醉不臧，不醉反耻。", "sentences": ["凡此饮酒，或醉或否。", "既立之监，或佐之史。", "彼醉不臧，不醉反耻。"], "notes": "", "page": null}, {"text": "式勿从谓，无俾大怠。匪言勿言，匪由勿语。由醉之言，俾出童羖。", "sentences": ["式勿从谓，无俾大怠。", "匪言勿言，匪由勿语。", "由醉之言，俾出童羖。"], "notes": "", "page": null}, {"text": "三爵不识，矧敢多又。", "sentences": ["三爵不识，矧敢多又。"], "notes": "", "page": null}]}, {"id": "p221", "title": "鱼藻", "section": "小雅", "group": "鱼藻之什", "intro": "《鱼藻》收于《诗经·小雅·鱼藻之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "鱼在在藻，有颁其首。王在在镐，岂乐饮酒。", "sentences": ["鱼在在藻，有颁其首。", "王在在镐，岂乐饮酒。"], "notes": "", "page": null}, {"text": "鱼在在藻，有莘其尾。王在在镐，饮酒乐岂。", "sentences": ["鱼在在藻，有莘其尾。", "王在在镐，饮酒乐岂。"], "notes": "", "page": null}, {"text": "鱼在在藻，依于其蒲。王在在镐，有那其居。", "sentences": ["鱼在在藻，依于其蒲。", "王在在镐，有那其居。"], "notes": "", "page": null}]}, {"id": "p222", "title": "采菽", "section": "小雅", "group": "鱼藻之什", "intro": "《采菽》收于《诗经·小雅·鱼藻之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "采菽采菽，筐之莒之。君子来朝，何锡予之？虽无予之？路车乘马。又何予之？玄衮及黼。", "sentences": ["采菽采菽，筐之莒之。", "君子来朝，何锡予之？", "虽无予之？", "路车乘马。", "又何予之？", "玄衮及黼。"], "notes": "", "page": null}, {"text": "觱沸槛泉，言采其芹。君子来朝，言观其旂。其旂淠淠，鸾声嘒嘒。载骖载驷，君子所届。", "sentences": ["觱沸槛泉，言采其芹。", "君子来朝，言观其旂。", "其旂淠淠，鸾声嘒嘒。", "载骖载驷，君子所届。"], "notes": "", "page": null}, {"text": "赤芾在股，邪幅在下。彼交匪纾，天子所予。乐只君子，天子命之。乐只君子，福禄申之。", "sentences": ["赤芾在股，邪幅在下。", "彼交匪纾，天子所予。", "乐只君子，天子命之。", "乐只君子，福禄申之。"], "notes": "", "page": null}, {"text": "维柞之枝，其叶蓬蓬。乐只君子，殿天子之邦。乐只君子，万福攸同。平平左右，亦是率从。", "sentences": ["维柞之枝，其叶蓬蓬。", "乐只君子，殿天子之邦。", "乐只君子，万福攸同。", "平平左右，亦是率从。"], "notes": "", "page": null}, {"text": "汎汎杨舟，绋纚维之。乐只君子，天子葵之。乐只君子，福禄膍之。优哉游哉，亦是戾矣。", "sentences": ["汎汎杨舟，绋纚维之。", "乐只君子，天子葵之。", "乐只君子，福禄膍之。", "优哉游哉，亦是戾矣。"], "notes": "", "page": null}]}, {"id": "p223", "title": "角弓", "section": "小雅", "group": "鱼藻之什", "intro": "《角弓》收于《诗经·小雅·鱼藻之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "骍骍角弓，翩其反矣。兄弟婚姻，无胥远矣。", "sentences": ["骍骍角弓，翩其反矣。", "兄弟婚姻，无胥远矣。"], "notes": "", "page": null}, {"text": "尔之远矣，民胥然矣。尔之教矣，民胥效矣。", "sentences": ["尔之远矣，民胥然矣。", "尔之教矣，民胥效矣。"], "notes": "", "page": null}, {"text": "此令兄弟，绰绰有裕。不令兄弟，交相为愈。", "sentences": ["此令兄弟，绰绰有裕。", "不令兄弟，交相为愈。"], "notes": "", "page": null}, {"text": "民之无良，相怨一方。受爵不让，至于已斯亡。", "sentences": ["民之无良，相怨一方。", "受爵不让，至于已斯亡。"], "notes": "", "page": null}, {"text": "老马反为驹，不顾其后。如食宜饇，如酌孔取。", "sentences": ["老马反为驹，不顾其后。", "如食宜饇，如酌孔取。"], "notes": "", "page": null}, {"text": "毋教猱升木，如涂涂附。君子有徽猷，小人与属。", "sentences": ["毋教猱升木，如涂涂附。", "君子有徽猷，小人与属。"], "notes": "", "page": null}, {"text": "雨雪瀌瀌，见晛曰消。莫肯下遗，式居娄骄。", "sentences": ["雨雪瀌瀌，见晛曰消。", "莫肯下遗，式居娄骄。"], "notes": "", "page": null}, {"text": "雨雪浮浮，见晛曰流。如蛮如髦，我是用忧。", "sentences": ["雨雪浮浮，见晛曰流。", "如蛮如髦，我是用忧。"], "notes": "", "page": null}]}, {"id": "p224", "title": "菀柳", "section": "小雅", "group": "鱼藻之什", "intro": "《菀柳》收于《诗经·小雅·鱼藻之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "有菀者柳，不尚息焉。上帝甚蹈，无自暱焉。俾予靖之，后予极焉。", "sentences": ["有菀者柳，不尚息焉。", "上帝甚蹈，无自暱焉。", "俾予靖之，后予极焉。"], "notes": "", "page": null}, {"text": "有菀者柳，不尚愒焉。上帝甚蹈，无自瘵焉。俾予靖之，后予迈焉。", "sentences": ["有菀者柳，不尚愒焉。", "上帝甚蹈，无自瘵焉。", "俾予靖之，后予迈焉。"], "notes": "", "page": null}, {"text": "有鸟高飞，亦傅于天。彼人之心，于何其臻。曷予靖之，居以凶矜。", "sentences": ["有鸟高飞，亦傅于天。", "彼人之心，于何其臻。", "曷予靖之，居以凶矜。"], "notes": "", "page": null}]}, {"id": "p225", "title": "都人士", "section": "小雅", "group": "鱼藻之什", "intro": "《都人士》收于《诗经·小雅·鱼藻之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "彼都人士，狐裘黄黄。其容不改，出言有章。行归于周，万民所望。", "sentences": ["彼都人士，狐裘黄黄。", "其容不改，出言有章。", "行归于周，万民所望。"], "notes": "", "page": null}, {"text": "彼都人士，台笠缁撮。彼君子女，绸直如发。我不见兮，我心不说。", "sentences": ["彼都人士，台笠缁撮。", "彼君子女，绸直如发。", "我不见兮，我心不说。"], "notes": "", "page": null}, {"text": "彼都人士，充耳琇实。彼君子女，谓之尹吉。我不见兮，我心苑结。", "sentences": ["彼都人士，充耳琇实。", "彼君子女，谓之尹吉。", "我不见兮，我心苑结。"], "notes": "", "page": null}, {"text": "彼都人士，垂带而厉。彼君子女，卷发如虿。我不见兮，言从之迈。", "sentences": ["彼都人士，垂带而厉。", "彼君子女，卷发如虿。", "我不见兮，言从之迈。"], "notes": "", "page": null}, {"text": "匪伊垂之，带则有余。匪伊卷之，发则有旟。我不见兮，云何盱矣。", "sentences": ["匪伊垂之，带则有余。", "匪伊卷之，发则有旟。", "我不见兮，云何盱矣。"], "notes": "", "page": null}]}, {"id": "p226", "title": "采绿", "section": "小雅", "group": "鱼藻之什", "intro": "《采绿》收于《诗经·小雅·鱼藻之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "终朝采绿，不盈一匊。予发曲局，薄言归沐。", "sentences": ["终朝采绿，不盈一匊。", "予发曲局，薄言归沐。"], "notes": "", "page": null}, {"text": "终朝采蓝，不盈一襜。五日为期，六日不詹。", "sentences": ["终朝采蓝，不盈一襜。", "五日为期，六日不詹。"], "notes": "", "page": null}, {"text": "之子于狩，言韔其弓。之子于钓，言纶之绳。", "sentences": ["之子于狩，言韔其弓。", "之子于钓，言纶之绳。"], "notes": "", "page": null}, {"text": "其钓维何？维鲂及鱮。维鲂及鱮，薄言观者。", "sentences": ["其钓维何？", "维鲂及鱮。", "维鲂及鱮，薄言观者。"], "notes": "", "page": null}]}, {"id": "p227", "title": "黍苗", "section": "小雅", "group": "鱼藻之什", "intro": "《黍苗》收于《诗经·小雅·鱼藻之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "芃芃黍苗，阴雨膏之。悠悠南行，召伯劳之。", "sentences": ["芃芃黍苗，阴雨膏之。", "悠悠南行，召伯劳之。"], "notes": "", "page": null}, {"text": "我任我辇，我车我牛。我行既集，盖云归哉。", "sentences": ["我任我辇，我车我牛。", "我行既集，盖云归哉。"], "notes": "", "page": null}, {"text": "我徒我御，我师我旅。我行既集，盖云归处。", "sentences": ["我徒我御，我师我旅。", "我行既集，盖云归处。"], "notes": "", "page": null}, {"text": "肃肃谢功，召伯营之。烈烈征师，召伯成之。", "sentences": ["肃肃谢功，召伯营之。", "烈烈征师，召伯成之。"], "notes": "", "page": null}, {"text": "原隰既平，泉流既清。召伯有成，王心则宁。", "sentences": ["原隰既平，泉流既清。", "召伯有成，王心则宁。"], "notes": "", "page": null}]}, {"id": "p228", "title": "隰桑", "section": "小雅", "group": "鱼藻之什", "intro": "《隰桑》收于《诗经·小雅·鱼藻之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "隰桑有阿，其叶有难。既见君子，其乐如何。", "sentences": ["隰桑有阿，其叶有难。", "既见君子，其乐如何。"], "notes": "", "page": null}, {"text": "隰桑有阿，其叶有沃。既见君子，云何不乐。", "sentences": ["隰桑有阿，其叶有沃。", "既见君子，云何不乐。"], "notes": "", "page": null}, {"text": "隰桑有阿，其叶有幽。既见君子，德音孔胶。", "sentences": ["隰桑有阿，其叶有幽。", "既见君子，德音孔胶。"], "notes": "", "page": null}, {"text": "心乎爱矣，遐不谓矣？中心藏之，何日忘之！", "sentences": ["心乎爱矣，遐不谓矣？", "中心藏之，何日忘之！"], "notes": "", "page": null}]}, {"id": "p229", "title": "白华", "section": "小雅", "group": "鱼藻之什", "intro": "《白华》收于《诗经·小雅·鱼藻之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "白华菅兮，白茅束兮。之子之远，俾我独兮。", "sentences": ["白华菅兮，白茅束兮。", "之子之远，俾我独兮。"], "notes": "", "page": null}, {"text": "英英白云，露彼菅茅。天步艰难，之子不犹。", "sentences": ["英英白云，露彼菅茅。", "天步艰难，之子不犹。"], "notes": "", "page": null}, {"text": "滮池北流，浸彼稻田。啸歌伤怀，念彼硕人。", "sentences": ["滮池北流，浸彼稻田。", "啸歌伤怀，念彼硕人。"], "notes": "", "page": null}, {"text": "樵彼桑薪，卬烘于煁。维彼硕人，实劳我心。", "sentences": ["樵彼桑薪，卬烘于煁。", "维彼硕人，实劳我心。"], "notes": "", "page": null}, {"text": "鼓钟于宫，声闻于外。念子懆懆，视我迈迈。", "sentences": ["鼓钟于宫，声闻于外。", "念子懆懆，视我迈迈。"], "notes": "", "page": null}, {"text": "有鹙在梁，有鹤在林。维彼硕人，实劳我心。", "sentences": ["有鹙在梁，有鹤在林。", "维彼硕人，实劳我心。"], "notes": "", "page": null}, {"text": "鸳鸯在梁，戢其左翼。之子无良，二三其德。", "sentences": ["鸳鸯在梁，戢其左翼。", "之子无良，二三其德。"], "notes": "", "page": null}, {"text": "有扁斯石，履之卑兮。之子之远，俾我疧兮。", "sentences": ["有扁斯石，履之卑兮。", "之子之远，俾我疧兮。"], "notes": "", "page": null}]}, {"id": "p230", "title": "绵蛮", "section": "小雅", "group": "鱼藻之什", "intro": "《绵蛮》收于《诗经·小雅·鱼藻之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "绵蛮黄鸟，止于丘阿。道之云远，我劳如何。饮之食之，教之诲之。命彼后车，谓之载之。", "sentences": ["绵蛮黄鸟，止于丘阿。", "道之云远，我劳如何。", "饮之食之，教之诲之。", "命彼后车，谓之载之。"], "notes": "", "page": null}, {"text": "绵蛮黄鸟，止于丘隅。岂敢惮行，畏不能趋。饮之食之。教之诲之。命彼后车，谓之载之。", "sentences": ["绵蛮黄鸟，止于丘隅。", "岂敢惮行，畏不能趋。", "饮之食之。", "教之诲之。", "命彼后车，谓之载之。"], "notes": "", "page": null}, {"text": "绵蛮黄鸟，止于丘侧。岂敢惮行，畏不能极。饮之食之，教之诲之。命彼后车，谓之载之。", "sentences": ["绵蛮黄鸟，止于丘侧。", "岂敢惮行，畏不能极。", "饮之食之，教之诲之。", "命彼后车，谓之载之。"], "notes": "", "page": null}]}, {"id": "p231", "title": "瓠叶", "section": "小雅", "group": "鱼藻之什", "intro": "《瓠叶》收于《诗经·小雅·鱼藻之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "幡幡瓠叶，采之亨之。君子有酒，酌言尝之。", "sentences": ["幡幡瓠叶，采之亨之。", "君子有酒，酌言尝之。"], "notes": "", "page": null}, {"text": "有兔斯首，炮之燔之。君子有酒，酌言献之。", "sentences": ["有兔斯首，炮之燔之。", "君子有酒，酌言献之。"], "notes": "", "page": null}, {"text": "有兔斯首，燔之炙之。君子有酒，酌言酢之。", "sentences": ["有兔斯首，燔之炙之。", "君子有酒，酌言酢之。"], "notes": "", "page": null}, {"text": "有兔斯首，燔之炮之。君子有酒，酌言酬之。", "sentences": ["有兔斯首，燔之炮之。", "君子有酒，酌言酬之。"], "notes": "", "page": null}]}, {"id": "p232", "title": "渐渐之石", "section": "小雅", "group": "鱼藻之什", "intro": "《渐渐之石》收于《诗经·小雅·鱼藻之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "渐渐之石，维其高矣。山川悠远，维其劳矣。武人东征，不遑朝矣。", "sentences": ["渐渐之石，维其高矣。", "山川悠远，维其劳矣。", "武人东征，不遑朝矣。"], "notes": "", "page": null}, {"text": "渐渐之石，维其卒矣。山川悠远，曷其没矣？武人东征，不遑出矣。", "sentences": ["渐渐之石，维其卒矣。", "山川悠远，曷其没矣？", "武人东征，不遑出矣。"], "notes": "", "page": null}, {"text": "有豕白蹢，烝涉波矣。月离于毕，俾滂沱矣。武人东征，不皇他矣。", "sentences": ["有豕白蹢，烝涉波矣。", "月离于毕，俾滂沱矣。", "武人东征，不皇他矣。"], "notes": "", "page": null}]}, {"id": "p233", "title": "苕之华", "section": "小雅", "group": "鱼藻之什", "intro": "《苕之华》收于《诗经·小雅·鱼藻之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "苕之华，芸其黄矣。心之忧矣，维其伤矣！", "sentences": ["苕之华，芸其黄矣。", "心之忧矣，维其伤矣！"], "notes": "", "page": null}, {"text": "苕之华，其叶青青。知我如此，不如无生！", "sentences": ["苕之华，其叶青青。", "知我如此，不如无生！"], "notes": "", "page": null}, {"text": "牂羊坟首，三星在罶。人可以食，鲜可以饱！", "sentences": ["牂羊坟首，三星在罶。", "人可以食，鲜可以饱！"], "notes": "", "page": null}]}, {"id": "p234", "title": "何草不黄", "section": "小雅", "group": "鱼藻之什", "intro": "《何草不黄》收于《诗经·小雅·鱼藻之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "何草不黄？何日不行？何人不将？经营四方。", "sentences": ["何草不黄？", "何日不行？", "何人不将？", "经营四方。"], "notes": "", "page": null}, {"text": "何草不玄？何人不矜？哀我征夫，独为匪民。", "sentences": ["何草不玄？", "何人不矜？", "哀我征夫，独为匪民。"], "notes": "", "page": null}, {"text": "匪兕匪虎，率彼旷野。哀我征夫，朝夕不暇。", "sentences": ["匪兕匪虎，率彼旷野。", "哀我征夫，朝夕不暇。"], "notes": "", "page": null}, {"text": "有芃者狐，率彼幽草。有栈之车，行彼周道。", "sentences": ["有芃者狐，率彼幽草。", "有栈之车，行彼周道。"], "notes": "", "page": null}]}, {"id": "p235", "title": "文王", "section": "大雅", "group": "文王之什", "intro": "《文王》收于《诗经·大雅·文王之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "文王在上，于昭于天。周虽旧邦，其命维新。有周不显，帝命不时。文王陟降，在帝左右。", "sentences": ["文王在上，于昭于天。", "周虽旧邦，其命维新。", "有周不显，帝命不时。", "文王陟降，在帝左右。"], "notes": "", "page": null}, {"text": "亹亹文王，令闻不已。陈锡哉周，侯文王孙子。文王孙子，本支百世，凡周之士，不显亦世。", "sentences": ["亹亹文王，令闻不已。", "陈锡哉周，侯文王孙子。", "文王孙子，本支百世，凡周之士，不显亦世。"], "notes": "", "page": null}, {"text": "世之不显，厥犹翼翼。思皇多士，生此王国。王国克生，维周之桢；济济多士，文王以宁。", "sentences": ["世之不显，厥犹翼翼。", "思皇多士，生此王国。", "王国克生，维周之桢；济济多士，文王以宁。"], "notes": "", "page": null}, {"text": "穆穆文王，于缉熙敬止。假哉天命。有商孙子。商之孙子，其丽不亿。上帝既命，侯于周服。", "sentences": ["穆穆文王，于缉熙敬止。", "假哉天命。", "有商孙子。", "商之孙子，其丽不亿。", "上帝既命，侯于周服。"], "notes": "", "page": null}, {"text": "侯服于周，天命靡常。殷士肤敏。裸将于京。厥作裸将，常服黼冔。王之荩臣。无念尔祖。", "sentences": ["侯服于周，天命靡常。", "殷士肤敏。", "裸将于京。", "厥作裸将，常服黼冔。", "王之荩臣。", "无念尔祖。"], "notes": "", "page": null}, {"text": "无念尔祖，聿修厥德。永言配命，自求多福。殷之未丧师，克配上帝。宜鉴于殷，骏命不易！", "sentences": ["无念尔祖，聿修厥德。", "永言配命，自求多福。", "殷之未丧师，克配上帝。", "宜鉴于殷，骏命不易！"], "notes": "", "page": null}, {"text": "命之不易，无遏尔躬。宣昭义问，有虞殷自天。上天之载，无声无臭。仪刑文王，万邦作孚。", "sentences": ["命之不易，无遏尔躬。", "宣昭义问，有虞殷自天。", "上天之载，无声无臭。", "仪刑文王，万邦作孚。"], "notes": "", "page": null}]}, {"id": "p236", "title": "大明", "section": "大雅", "group": "文王之什", "intro": "《大明》收于《诗经·大雅·文王之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "明明在下，赫赫在上。天难忱斯，不易维王。天位殷适，使不挟四方。", "sentences": ["明明在下，赫赫在上。", "天难忱斯，不易维王。", "天位殷适，使不挟四方。"], "notes": "", "page": null}, {"text": "挚仲氏任，自彼殷商，来嫁于周，曰嫔于京。乃及王季，维德之行。", "sentences": ["挚仲氏任，自彼殷商，来嫁于周，曰嫔于京。", "乃及王季，维德之行。"], "notes": "", "page": null}, {"text": "大任有身，生此文王。维此文王，小心翼翼。昭事上帝，聿怀多福。厥德不回，以受方国。", "sentences": ["大任有身，生此文王。", "维此文王，小心翼翼。", "昭事上帝，聿怀多福。", "厥德不回，以受方国。"], "notes": "", "page": null}, {"text": "天监在下，有命既集。文王初载，天作之合。在洽之阳，在渭之涘。", "sentences": ["天监在下，有命既集。", "文王初载，天作之合。", "在洽之阳，在渭之涘。"], "notes": "", "page": null}, {"text": "文王嘉止，大邦有子。大邦有子，伣天之妹。文定厥祥，亲迎于渭。造舟为梁，不显其光。", "sentences": ["文王嘉止，大邦有子。", "大邦有子，伣天之妹。", "文定厥祥，亲迎于渭。", "造舟为梁，不显其光。"], "notes": "", "page": null}, {"text": "有命自天，命此文王。于周于京，缵女维莘。长子维行，笃生武王。保右命尔，燮伐大商。", "sentences": ["有命自天，命此文王。", "于周于京，缵女维莘。", "长子维行，笃生武王。", "保右命尔，燮伐大商。"], "notes": "", "page": null}, {"text": "殷商之旅，其会如林。矢于牧野，维予侯兴。上帝临女，无二尔心。", "sentences": ["殷商之旅，其会如林。", "矢于牧野，维予侯兴。", "上帝临女，无二尔心。"], "notes": "", "page": null}, {"text": "牧野洋洋，檀车煌煌，驷騵彭彭。维师尚父，时维鹰扬。凉彼武王，四伐大商，会朝清明。", "sentences": ["牧野洋洋，檀车煌煌，驷騵彭彭。", "维师尚父，时维鹰扬。", "凉彼武王，四伐大商，会朝清明。"], "notes": "", "page": null}]}, {"id": "p237", "title": "绵", "section": "大雅", "group": "文王之什", "intro": "《绵》收于《诗经·大雅·文王之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "绵绵瓜瓞。民之初生，自土沮漆。古公亶父，陶复陶冗，未有家室。", "sentences": ["绵绵瓜瓞。", "民之初生，自土沮漆。", "古公亶父，陶复陶冗，未有家室。"], "notes": "", "page": null}, {"text": "古公亶父，来朝走马。率西水浒，至于岐下。爰及姜女，聿来胥宇。", "sentences": ["古公亶父，来朝走马。", "率西水浒，至于岐下。", "爰及姜女，聿来胥宇。"], "notes": "", "page": null}, {"text": "周原膴膴，堇荼如饴。爰始爰谋，爰契我龟，曰止曰时，筑室于兹。", "sentences": ["周原膴膴，堇荼如饴。", "爰始爰谋，爰契我龟，曰止曰时，筑室于兹。"], "notes": "", "page": null}, {"text": "乃慰乃止，乃左乃右，乃疆乃理，乃宣乃亩。自西徂东，周爰执事。", "sentences": ["乃慰乃止，乃左乃右，乃疆乃理，乃宣乃亩。", "自西徂东，周爰执事。"], "notes": "", "page": null}, {"text": "乃召司空，乃召司徒，俾立室家。其绳则直，缩版以载，作庙翼翼。", "sentences": ["乃召司空，乃召司徒，俾立室家。", "其绳则直，缩版以载，作庙翼翼。"], "notes": "", "page": null}, {"text": "捄之陾陾，度之薨薨，筑之登登，削屡冯冯。百堵皆兴，鼛鼓弗胜。", "sentences": ["捄之陾陾，度之薨薨，筑之登登，削屡冯冯。", "百堵皆兴，鼛鼓弗胜。"], "notes": "", "page": null}, {"text": "乃立皋门，皋门有伉。乃立应门，应门将将。乃立冢土，戎丑攸行。", "sentences": ["乃立皋门，皋门有伉。", "乃立应门，应门将将。", "乃立冢土，戎丑攸行。"], "notes": "", "page": null}, {"text": "四不殄厥愠，亦不陨厥问。柞棫拔矣，行道兑矣。混夷駾矣，维其喙矣！", "sentences": ["四不殄厥愠，亦不陨厥问。", "柞棫拔矣，行道兑矣。", "混夷駾矣，维其喙矣！"], "notes": "", "page": null}, {"text": "虞芮质厥成，文王蹶厥生。予曰有疏附，予曰有先后。予曰有奔奏，予曰有御侮！", "sentences": ["虞芮质厥成，文王蹶厥生。", "予曰有疏附，予曰有先后。", "予曰有奔奏，予曰有御侮！"], "notes": "", "page": null}]}, {"id": "p238", "title": "棫朴", "section": "大雅", "group": "文王之什", "intro": "《棫朴》收于《诗经·大雅·文王之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "芃芃棫朴，薪之槱之。济济辟王，左右趣之。", "sentences": ["芃芃棫朴，薪之槱之。", "济济辟王，左右趣之。"], "notes": "", "page": null}, {"text": "济济辟王，左右奉璋。奉璋峨峨，髦士攸宜。", "sentences": ["济济辟王，左右奉璋。", "奉璋峨峨，髦士攸宜。"], "notes": "", "page": null}, {"text": "淠彼泾舟，烝徒楫之。周王于迈，六师及之。", "sentences": ["淠彼泾舟，烝徒楫之。", "周王于迈，六师及之。"], "notes": "", "page": null}, {"text": "倬彼云汉，为章于天。周王寿考，遐不作人？", "sentences": ["倬彼云汉，为章于天。", "周王寿考，遐不作人？"], "notes": "", "page": null}, {"text": "追琢其章，金玉其相。勉勉我王，纲纪四方。", "sentences": ["追琢其章，金玉其相。", "勉勉我王，纲纪四方。"], "notes": "", "page": null}]}, {"id": "p239", "title": "旱麓", "section": "大雅", "group": "文王之什", "intro": "《旱麓》收于《诗经·大雅·文王之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "瞻彼旱麓，榛楛济济。岂弟君子，干禄岂弟。", "sentences": ["瞻彼旱麓，榛楛济济。", "岂弟君子，干禄岂弟。"], "notes": "", "page": null}, {"text": "瑟彼玉瓒，黄流在中。岂弟君子，福禄攸降。", "sentences": ["瑟彼玉瓒，黄流在中。", "岂弟君子，福禄攸降。"], "notes": "", "page": null}, {"text": "鸢飞戾天，鱼跃于渊。岂弟君子，遐不作人？", "sentences": ["鸢飞戾天，鱼跃于渊。", "岂弟君子，遐不作人？"], "notes": "", "page": null}, {"text": "清酒既载，骍牡既备。以享以祀，以介景福。", "sentences": ["清酒既载，骍牡既备。", "以享以祀，以介景福。"], "notes": "", "page": null}, {"text": "瑟彼柞棫，民所燎矣。岂弟君子，神所劳矣。", "sentences": ["瑟彼柞棫，民所燎矣。", "岂弟君子，神所劳矣。"], "notes": "", "page": null}, {"text": "莫莫葛藟，施于条枚。岂弟君子，求福不回。", "sentences": ["莫莫葛藟，施于条枚。", "岂弟君子，求福不回。"], "notes": "", "page": null}]}, {"id": "p240", "title": "思齐", "section": "大雅", "group": "文王之什", "intro": "《思齐》收于《诗经·大雅·文王之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "思齐大任，文王之母，思媚周姜，京室之妇。大姒嗣徽音，则百斯男。", "sentences": ["思齐大任，文王之母，思媚周姜，京室之妇。", "大姒嗣徽音，则百斯男。"], "notes": "", "page": null}, {"text": "惠于宗公，神罔时怨，神罔时恫。刑于寡妻，至于兄弟，以御于家邦。", "sentences": ["惠于宗公，神罔时怨，神罔时恫。", "刑于寡妻，至于兄弟，以御于家邦。"], "notes": "", "page": null}, {"text": "雍雍在宫，肃肃在庙。不显亦临，无射亦保。", "sentences": ["雍雍在宫，肃肃在庙。", "不显亦临，无射亦保。"], "notes": "", "page": null}, {"text": "四戎疾不殄，烈假不瑕。不闻亦式，不谏亦入。四成人有德，小子有造。古之人无斁，誉髦斯士。", "sentences": ["四戎疾不殄，烈假不瑕。", "不闻亦式，不谏亦入。", "四成人有德，小子有造。", "古之人无斁，誉髦斯士。"], "notes": "", "page": null}]}, {"id": "p241", "title": "皇矣", "section": "大雅", "group": "文王之什", "intro": "《皇矣》收于《诗经·大雅·文王之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "皇矣上帝，临下有赫。监观四方，求民之莫。维此二国，其政不获。", "sentences": ["皇矣上帝，临下有赫。", "监观四方，求民之莫。", "维此二国，其政不获。"], "notes": "", "page": null}, {"text": "维彼四国，爰究爰度。上帝耆之，憎其式廓。乃眷西顾，此维与宅。", "sentences": ["维彼四国，爰究爰度。", "上帝耆之，憎其式廓。", "乃眷西顾，此维与宅。"], "notes": "", "page": null}, {"text": "作之屏之，其菑其翳。修之平之，其灌其栵。启之辟之，其柽其椐。", "sentences": ["作之屏之，其菑其翳。", "修之平之，其灌其栵。", "启之辟之，其柽其椐。"], "notes": "", "page": null}, {"text": "攘之剔之，其檿其柘。帝迁明德，串夷载路。天立厥配，受命既固。", "sentences": ["攘之剔之，其檿其柘。", "帝迁明德，串夷载路。", "天立厥配，受命既固。"], "notes": "", "page": null}, {"text": "帝省其山，柞棫斯拔，松柏斯兑。帝作邦作对，自大伯王季。维此王季，", "sentences": ["帝省其山，柞棫斯拔，松柏斯兑。", "帝作邦作对，自大伯王季。", "维此王季，"], "notes": "", "page": null}, {"text": "因心则友。则友其兄，则笃其庆，载锡之光。受禄无丧，奄有四方。", "sentences": ["因心则友。", "则友其兄，则笃其庆，载锡之光。", "受禄无丧，奄有四方。"], "notes": "", "page": null}, {"text": "维此王季，帝度其心。貊其德音，其德克明。克明克类，克长克君。", "sentences": ["维此王季，帝度其心。", "貊其德音，其德克明。", "克明克类，克长克君。"], "notes": "", "page": null}, {"text": "王此大邦，克顺克比。比于文王，其德靡悔。既受帝祉，施于孙子。", "sentences": ["王此大邦，克顺克比。", "比于文王，其德靡悔。", "既受帝祉，施于孙子。"], "notes": "", "page": null}, {"text": "帝谓文王：无然畔援，无然歆羡，诞先登于岸。密人不恭，敢距大邦，", "sentences": ["帝谓文王：无然畔援，无然歆羡，诞先登于岸。", "密人不恭，敢距大邦，"], "notes": "", "page": null}, {"text": "侵阮徂共。王赫斯怒，爰整其旅，以按徂旅。以笃于周祜，以对于天下。", "sentences": ["侵阮徂共。", "王赫斯怒，爰整其旅，以按徂旅。", "以笃于周祜，以对于天下。"], "notes": "", "page": null}, {"text": "依其在京，侵自阮疆。陟我高冈，无矢我陵。我陵我阿，无饮我泉，", "sentences": ["依其在京，侵自阮疆。", "陟我高冈，无矢我陵。", "我陵我阿，无饮我泉，"], "notes": "", "page": null}, {"text": "我泉我池。度其鲜原，居岐之阳，在渭之将。万邦之方，下民之王。", "sentences": ["我泉我池。", "度其鲜原，居岐之阳，在渭之将。", "万邦之方，下民之王。"], "notes": "", "page": null}, {"text": "帝谓文王：予怀明德，不大声以色，不长夏以革。不识不知，顺帝之则。", "sentences": ["帝谓文王：予怀明德，不大声以色，不长夏以革。", "不识不知，顺帝之则。"], "notes": "", "page": null}, {"text": "帝谓文王：訽尔仇方，同尔弟兄。以尔钩援，与尔临冲，以伐崇墉。", "sentences": ["帝谓文王：訽尔仇方，同尔弟兄。", "以尔钩援，与尔临冲，以伐崇墉。"], "notes": "", "page": null}, {"text": "临冲闲闲，崇墉言言。执讯连连，攸馘安安。是类是禡，是致是附，", "sentences": ["临冲闲闲，崇墉言言。", "执讯连连，攸馘安安。", "是类是禡，是致是附，"], "notes": "", "page": null}, {"text": "四方以无侮。临冲茀茀，崇墉仡仡。是伐是四，是绝是忽。四方以无拂。", "sentences": ["四方以无侮。", "临冲茀茀，崇墉仡仡。", "是伐是四，是绝是忽。", "四方以无拂。"], "notes": "", "page": null}]}, {"id": "p242", "title": "灵台", "section": "大雅", "group": "文王之什", "intro": "《灵台》收于《诗经·大雅·文王之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "经始灵台，经之营之。庶民攻之，不日成之。经始勿亟，庶民子来。", "sentences": ["经始灵台，经之营之。", "庶民攻之，不日成之。", "经始勿亟，庶民子来。"], "notes": "", "page": null}, {"text": "王在灵囿，麀鹿攸伏。麀鹿濯濯，白鸟翯翯。王在灵沼，于牣鱼跃。", "sentences": ["王在灵囿，麀鹿攸伏。", "麀鹿濯濯，白鸟翯翯。", "王在灵沼，于牣鱼跃。"], "notes": "", "page": null}, {"text": "虡业维枞，贲鼓维镛。于论鼓钟，于乐辟雍。", "sentences": ["虡业维枞，贲鼓维镛。", "于论鼓钟，于乐辟雍。"], "notes": "", "page": null}, {"text": "于论鼓钟，于乐辟雍。鼍鼓逢逢。矇瞍奏公。", "sentences": ["于论鼓钟，于乐辟雍。", "鼍鼓逢逢。", "矇瞍奏公。"], "notes": "", "page": null}]}, {"id": "p243", "title": "下武", "section": "大雅", "group": "文王之什", "intro": "《下武》收于《诗经·大雅·文王之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "下武维周，世有哲王。三后在天，王配于京。", "sentences": ["下武维周，世有哲王。", "三后在天，王配于京。"], "notes": "", "page": null}, {"text": "王配于京，世德作求。永言配命，成王之孚。", "sentences": ["王配于京，世德作求。", "永言配命，成王之孚。"], "notes": "", "page": null}, {"text": "成王之孚，下土之式。永言孝思，孝思维则。", "sentences": ["成王之孚，下土之式。", "永言孝思，孝思维则。"], "notes": "", "page": null}, {"text": "媚兹一人，应侯顺德。永言孝思，昭哉嗣服。", "sentences": ["媚兹一人，应侯顺德。", "永言孝思，昭哉嗣服。"], "notes": "", "page": null}, {"text": "昭兹来许，绳其祖武。于万斯年，受天之祜。", "sentences": ["昭兹来许，绳其祖武。", "于万斯年，受天之祜。"], "notes": "", "page": null}, {"text": "受天之祜，四方来贺。于万斯年，不遐有佐。", "sentences": ["受天之祜，四方来贺。", "于万斯年，不遐有佐。"], "notes": "", "page": null}]}, {"id": "p244", "title": "文王有声", "section": "大雅", "group": "文王之什", "intro": "《文王有声》收于《诗经·大雅·文王之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "文王有声，遹骏有声。遹求厥宁，遹观厥成。文王烝哉！", "sentences": ["文王有声，遹骏有声。", "遹求厥宁，遹观厥成。", "文王烝哉！"], "notes": "", "page": null}, {"text": "文王受命，有此武功。既伐于崇，作邑于丰。文王烝哉！", "sentences": ["文王受命，有此武功。", "既伐于崇，作邑于丰。", "文王烝哉！"], "notes": "", "page": null}, {"text": "筑城伊淢，作丰伊匹。匪棘其欲，遹追来孝。王后烝哉！", "sentences": ["筑城伊淢，作丰伊匹。", "匪棘其欲，遹追来孝。", "王后烝哉！"], "notes": "", "page": null}, {"text": "王公伊濯，维丰之垣。四方攸同，王后维翰。王后烝哉！", "sentences": ["王公伊濯，维丰之垣。", "四方攸同，王后维翰。", "王后烝哉！"], "notes": "", "page": null}, {"text": "丰水东注，维禹之绩。四方攸同，皇王维辟。皇王烝哉！", "sentences": ["丰水东注，维禹之绩。", "四方攸同，皇王维辟。", "皇王烝哉！"], "notes": "", "page": null}, {"text": "镐京辟雍，自西自东，自南自北，无思不服。皇王烝哉！", "sentences": ["镐京辟雍，自西自东，自南自北，无思不服。", "皇王烝哉！"], "notes": "", "page": null}, {"text": "考卜维王，宅是镐京。维龟正之，武王成之。武王烝哉！", "sentences": ["考卜维王，宅是镐京。", "维龟正之，武王成之。", "武王烝哉！"], "notes": "", "page": null}, {"text": "丰水有芑，武王岂不仕？诒厥孙谋，以燕翼子。武王烝哉！", "sentences": ["丰水有芑，武王岂不仕？", "诒厥孙谋，以燕翼子。", "武王烝哉！"], "notes": "", "page": null}]}, {"id": "p245", "title": "生民", "section": "大雅", "group": "生民之什", "intro": "《生民》收于《诗经·大雅·生民之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "厥初生民，时维姜嫄。生民如何？克禋克祀，以弗无子。", "sentences": ["厥初生民，时维姜嫄。", "生民如何？", "克禋克祀，以弗无子。"], "notes": "", "page": null}, {"text": "履帝武敏歆，攸介攸止，载震载夙。载生载育，时维后稷。", "sentences": ["履帝武敏歆，攸介攸止，载震载夙。", "载生载育，时维后稷。"], "notes": "", "page": null}, {"text": "诞弥厥月，先生如达。不拆不副，无菑无害。以赫厥灵。", "sentences": ["诞弥厥月，先生如达。", "不拆不副，无菑无害。", "以赫厥灵。"], "notes": "", "page": null}, {"text": "上帝不宁，不康禋祀，居然生子。", "sentences": ["上帝不宁，不康禋祀，居然生子。"], "notes": "", "page": null}, {"text": "诞寘之隘巷，牛羊腓字之。诞寘之平林，会伐平林。", "sentences": ["诞寘之隘巷，牛羊腓字之。", "诞寘之平林，会伐平林。"], "notes": "", "page": null}, {"text": "诞寘之寒冰，鸟覆翼之。鸟乃去矣，后稷呱矣。", "sentences": ["诞寘之寒冰，鸟覆翼之。", "鸟乃去矣，后稷呱矣。"], "notes": "", "page": null}, {"text": "实覃实訏，厥声载路。诞实匍匐，克岐克嶷。以就口食。", "sentences": ["实覃实訏，厥声载路。", "诞实匍匐，克岐克嶷。", "以就口食。"], "notes": "", "page": null}, {"text": "蓺之荏菽，荏菽旆旆。禾役穟穟，麻麦幪幪，瓜瓞唪唪。", "sentences": ["蓺之荏菽，荏菽旆旆。", "禾役穟穟，麻麦幪幪，瓜瓞唪唪。"], "notes": "", "page": null}, {"text": "诞后稷之穑，有相之道。茀厥丰草，种之黄茂。实方实苞，实种实褎。", "sentences": ["诞后稷之穑，有相之道。", "茀厥丰草，种之黄茂。", "实方实苞，实种实褎。"], "notes": "", "page": null}, {"text": "实发实秀，实坚实好。实颖实栗，即有邰家室。", "sentences": ["实发实秀，实坚实好。", "实颖实栗，即有邰家室。"], "notes": "", "page": null}, {"text": "诞降嘉种，维秬维秠，维穈维芑。恒之秬秠，是获是亩。", "sentences": ["诞降嘉种，维秬维秠，维穈维芑。", "恒之秬秠，是获是亩。"], "notes": "", "page": null}, {"text": "恒之穈芑，是任是负。以归肇祀。", "sentences": ["恒之穈芑，是任是负。", "以归肇祀。"], "notes": "", "page": null}, {"text": "诞我祀如何？或舂或揄，或簸或蹂。释之叟叟，烝之浮浮。", "sentences": ["诞我祀如何？", "或舂或揄，或簸或蹂。", "释之叟叟，烝之浮浮。"], "notes": "", "page": null}, {"text": "载谋载惟。取萧祭脂，取羝以軷，载燔载烈，以兴嗣岁。", "sentences": ["载谋载惟。", "取萧祭脂，取羝以軷，载燔载烈，以兴嗣岁。"], "notes": "", "page": null}, {"text": "卬盛于豆，于豆于登。其香始升，上帝居歆。胡臭亶时。", "sentences": ["卬盛于豆，于豆于登。", "其香始升，上帝居歆。", "胡臭亶时。"], "notes": "", "page": null}, {"text": "后稷肇祀。庶无罪悔，以迄于今。", "sentences": ["后稷肇祀。", "庶无罪悔，以迄于今。"], "notes": "", "page": null}]}, {"id": "p246", "title": "行苇", "section": "大雅", "group": "生民之什", "intro": "《行苇》收于《诗经·大雅·生民之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "敦彼行苇，牛羊勿践履。方苞方体，维叶泥泥。", "sentences": ["敦彼行苇，牛羊勿践履。", "方苞方体，维叶泥泥。"], "notes": "", "page": null}, {"text": "戚戚兄弟，莫远具尔。或四之筵，或授之几。", "sentences": ["戚戚兄弟，莫远具尔。", "或四之筵，或授之几。"], "notes": "", "page": null}, {"text": "四筵设席，授几有缉御。或献或酢，洗爵奠斝。", "sentences": ["四筵设席，授几有缉御。", "或献或酢，洗爵奠斝。"], "notes": "", "page": null}, {"text": "醓醢以荐，或燔或炙。嘉肴脾臄，或歌或咢。", "sentences": ["醓醢以荐，或燔或炙。", "嘉肴脾臄，或歌或咢。"], "notes": "", "page": null}, {"text": "敦弓既坚，四鍭既均，舍矢既均，序宾以贤。", "sentences": ["敦弓既坚，四鍭既均，舍矢既均，序宾以贤。"], "notes": "", "page": null}, {"text": "敦弓既句，既挟四鍭。四鍭如树，序宾以不侮。", "sentences": ["敦弓既句，既挟四鍭。", "四鍭如树，序宾以不侮。"], "notes": "", "page": null}, {"text": "曾孙维主，酒醴维醽，酌以大斗，以祈黄耇。", "sentences": ["曾孙维主，酒醴维醽，酌以大斗，以祈黄耇。"], "notes": "", "page": null}, {"text": "黄耇台背，以引以翼。寿考维祺，以介景福。", "sentences": ["黄耇台背，以引以翼。", "寿考维祺，以介景福。"], "notes": "", "page": null}]}, {"id": "p247", "title": "既醉", "section": "大雅", "group": "生民之什", "intro": "《既醉》收于《诗经·大雅·生民之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "既醉以酒，既饱以德。君子万年，介尔景福。", "sentences": ["既醉以酒，既饱以德。", "君子万年，介尔景福。"], "notes": "", "page": null}, {"text": "既醉以酒，尔肴既将。君子万年，介尔昭明。", "sentences": ["既醉以酒，尔肴既将。", "君子万年，介尔昭明。"], "notes": "", "page": null}, {"text": "昭明有融，高朗令终，令终有俶。公尸嘉告。", "sentences": ["昭明有融，高朗令终，令终有俶。", "公尸嘉告。"], "notes": "", "page": null}, {"text": "其告维何？笾豆静嘉。朋友攸摄，摄以威仪。", "sentences": ["其告维何？", "笾豆静嘉。", "朋友攸摄，摄以威仪。"], "notes": "", "page": null}, {"text": "威仪孔时，君子有孝子。孝子不匮，永锡尔类。", "sentences": ["威仪孔时，君子有孝子。", "孝子不匮，永锡尔类。"], "notes": "", "page": null}, {"text": "其类维何？室家之壶。君子万年，永锡祚胤。", "sentences": ["其类维何？", "室家之壶。", "君子万年，永锡祚胤。"], "notes": "", "page": null}, {"text": "其胤维何？天被尔禄。君子万年，景命有仆。", "sentences": ["其胤维何？", "天被尔禄。", "君子万年，景命有仆。"], "notes": "", "page": null}, {"text": "其仆维何？厘尔女士。厘尔女士，从以孙子。", "sentences": ["其仆维何？", "厘尔女士。", "厘尔女士，从以孙子。"], "notes": "", "page": null}]}, {"id": "p248", "title": "凫鹥", "section": "大雅", "group": "生民之什", "intro": "《凫鹥》收于《诗经·大雅·生民之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "凫鹥在泾，公尸在燕来宁。尔酒既清，尔肴既馨。公尸燕饮，福禄来成。", "sentences": ["凫鹥在泾，公尸在燕来宁。", "尔酒既清，尔肴既馨。", "公尸燕饮，福禄来成。"], "notes": "", "page": null}, {"text": "凫鹥在沙，公尸来燕来宜。尔酒既多，尔肴既嘉。公尸燕饮，福禄来为。", "sentences": ["凫鹥在沙，公尸来燕来宜。", "尔酒既多，尔肴既嘉。", "公尸燕饮，福禄来为。"], "notes": "", "page": null}, {"text": "凫鹥在渚，公尸来燕来处。尔酒既湑，尔肴伊脯。公尸燕饮，福禄来下。", "sentences": ["凫鹥在渚，公尸来燕来处。", "尔酒既湑，尔肴伊脯。", "公尸燕饮，福禄来下。"], "notes": "", "page": null}, {"text": "凫鹥在潀，公尸来燕来宗，既燕于宗，福禄攸降。公尸燕饮，福禄来崇。", "sentences": ["凫鹥在潀，公尸来燕来宗，既燕于宗，福禄攸降。", "公尸燕饮，福禄来崇。"], "notes": "", "page": null}, {"text": "凫鹥在亹，公尸来止熏熏。旨酒欣欣，燔炙芬芬。公尸燕饮，无有后艰。", "sentences": ["凫鹥在亹，公尸来止熏熏。", "旨酒欣欣，燔炙芬芬。", "公尸燕饮，无有后艰。"], "notes": "", "page": null}]}, {"id": "p249", "title": "假乐", "section": "大雅", "group": "生民之什", "intro": "《假乐》收于《诗经·大雅·生民之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "假乐君子，显显令德，宜民宜人。受禄于天，保右命之，自天申之。", "sentences": ["假乐君子，显显令德，宜民宜人。", "受禄于天，保右命之，自天申之。"], "notes": "", "page": null}, {"text": "千禄百福，子孙千亿。穆穆皇皇，宜君宜王。不愆不忘，率由旧章。", "sentences": ["千禄百福，子孙千亿。", "穆穆皇皇，宜君宜王。", "不愆不忘，率由旧章。"], "notes": "", "page": null}, {"text": "威仪抑抑，德音秩秩。无怨无恶，率由群匹。受福无疆，四方之纲。", "sentences": ["威仪抑抑，德音秩秩。", "无怨无恶，率由群匹。", "受福无疆，四方之纲。"], "notes": "", "page": null}, {"text": "之纲之纪，燕及朋友。百辟卿士，媚于天子。不解于位，民之攸塈。", "sentences": ["之纲之纪，燕及朋友。", "百辟卿士，媚于天子。", "不解于位，民之攸塈。"], "notes": "", "page": null}]}, {"id": "p250", "title": "公刘", "section": "大雅", "group": "生民之什", "intro": "《公刘》收于《诗经·大雅·生民之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "笃公刘，匪居匪康。乃埸乃疆，乃积乃仓；乃裹餱粮，于橐于囊。", "sentences": ["笃公刘，匪居匪康。", "乃埸乃疆，乃积乃仓；乃裹餱粮，于橐于囊。"], "notes": "", "page": null}, {"text": "思辑用光，弓矢斯张；干戈戚扬，爰方启行。", "sentences": ["思辑用光，弓矢斯张；干戈戚扬，爰方启行。"], "notes": "", "page": null}, {"text": "笃公刘，于胥斯原。既庶既繁，既顺乃宣，而无永叹。陟则在巘，", "sentences": ["笃公刘，于胥斯原。", "既庶既繁，既顺乃宣，而无永叹。", "陟则在巘，"], "notes": "", "page": null}, {"text": "复降在原。何以舟之？维玉及瑶，鞞琫容刀。", "sentences": ["复降在原。", "何以舟之？", "维玉及瑶，鞞琫容刀。"], "notes": "", "page": null}, {"text": "笃公刘，逝彼百泉。瞻彼溥原，乃陟南冈。乃觏于京，京师之野。", "sentences": ["笃公刘，逝彼百泉。", "瞻彼溥原，乃陟南冈。", "乃觏于京，京师之野。"], "notes": "", "page": null}, {"text": "于时处处，于时庐旅，于时言言，于时语语。", "sentences": ["于时处处，于时庐旅，于时言言，于时语语。"], "notes": "", "page": null}, {"text": "笃公刘，于京斯依。跄跄济济，俾筵俾几。既登乃依，乃造其曹。", "sentences": ["笃公刘，于京斯依。", "跄跄济济，俾筵俾几。", "既登乃依，乃造其曹。"], "notes": "", "page": null}, {"text": "执豕于牢，酌之用匏。食之饮之，君之宗之。", "sentences": ["执豕于牢，酌之用匏。", "食之饮之，君之宗之。"], "notes": "", "page": null}, {"text": "笃公刘，既溥既长。既景乃冈，相其阴阳，观其流泉。其军三单，", "sentences": ["笃公刘，既溥既长。", "既景乃冈，相其阴阳，观其流泉。", "其军三单，"], "notes": "", "page": null}, {"text": "度其隰原。彻田为粮，度其夕阳。豳居允荒。", "sentences": ["度其隰原。", "彻田为粮，度其夕阳。", "豳居允荒。"], "notes": "", "page": null}, {"text": "笃公刘，于豳斯馆。涉渭为乱，取厉取锻，止基乃理。爰众爰有，", "sentences": ["笃公刘，于豳斯馆。", "涉渭为乱，取厉取锻，止基乃理。", "爰众爰有，"], "notes": "", "page": null}, {"text": "夹其皇涧。溯其过涧。止旅乃密，芮鞫之即。", "sentences": ["夹其皇涧。", "溯其过涧。", "止旅乃密，芮鞫之即。"], "notes": "", "page": null}]}, {"id": "p251", "title": "泂酌", "section": "大雅", "group": "生民之什", "intro": "《泂酌》收于《诗经·大雅·生民之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "泂酌彼行潦，挹彼注兹，可以餴饎。岂弟君子，民之父母。", "sentences": ["泂酌彼行潦，挹彼注兹，可以餴饎。", "岂弟君子，民之父母。"], "notes": "", "page": null}, {"text": "泂酌彼行潦，挹彼注兹，可以濯罍。岂弟君子，民之攸归。", "sentences": ["泂酌彼行潦，挹彼注兹，可以濯罍。", "岂弟君子，民之攸归。"], "notes": "", "page": null}, {"text": "泂酌彼行潦，挹彼注兹，可以濯溉。岂弟君子，民之攸墍。", "sentences": ["泂酌彼行潦，挹彼注兹，可以濯溉。", "岂弟君子，民之攸墍。"], "notes": "", "page": null}]}, {"id": "p252", "title": "卷阿", "section": "大雅", "group": "生民之什", "intro": "《卷阿》收于《诗经·大雅·生民之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "有卷者阿，飘风自南。岂弟君子，来游来歌，以矢其音。", "sentences": ["有卷者阿，飘风自南。", "岂弟君子，来游来歌，以矢其音。"], "notes": "", "page": null}, {"text": "伴奂尔游矣，优游尔休矣。岂弟君子，俾尔弥尔性，似先公酋矣。", "sentences": ["伴奂尔游矣，优游尔休矣。", "岂弟君子，俾尔弥尔性，似先公酋矣。"], "notes": "", "page": null}, {"text": "尔土宇昄章，亦孔之厚矣。岂弟君子，俾尔弥尔性，百神尔主矣。", "sentences": ["尔土宇昄章，亦孔之厚矣。", "岂弟君子，俾尔弥尔性，百神尔主矣。"], "notes": "", "page": null}, {"text": "尔受命长矣，茀禄尔康矣。岂弟君子，俾尔弥尔性，纯嘏尔常矣。", "sentences": ["尔受命长矣，茀禄尔康矣。", "岂弟君子，俾尔弥尔性，纯嘏尔常矣。"], "notes": "", "page": null}, {"text": "有冯有翼，有孝有德，以引以翼。岂弟君子，四方为则。", "sentences": ["有冯有翼，有孝有德，以引以翼。", "岂弟君子，四方为则。"], "notes": "", "page": null}, {"text": "颙颙卬卬，如圭如璋，令闻令望。岂弟君子，四方为纲。", "sentences": ["颙颙卬卬，如圭如璋，令闻令望。", "岂弟君子，四方为纲。"], "notes": "", "page": null}, {"text": "凤凰于飞，翙翙其羽，亦集爰止。蔼蔼王多吉士，维君子使，媚于天子。", "sentences": ["凤凰于飞，翙翙其羽，亦集爰止。", "蔼蔼王多吉士，维君子使，媚于天子。"], "notes": "", "page": null}, {"text": "凤凰于飞，翙翙其羽，亦傅于天。蔼蔼王多吉人，维君子命，媚于庶人。", "sentences": ["凤凰于飞，翙翙其羽，亦傅于天。", "蔼蔼王多吉人，维君子命，媚于庶人。"], "notes": "", "page": null}, {"text": "凤凰鸣矣，于彼高冈。梧桐生矣，于彼朝阳。菶菶萋萋，雍雍喈喈。", "sentences": ["凤凰鸣矣，于彼高冈。", "梧桐生矣，于彼朝阳。", "菶菶萋萋，雍雍喈喈。"], "notes": "", "page": null}, {"text": "君子之车，既庶且多。君子之马，既闲且驰。矢诗不多，维以遂歌。", "sentences": ["君子之车，既庶且多。", "君子之马，既闲且驰。", "矢诗不多，维以遂歌。"], "notes": "", "page": null}]}, {"id": "p253", "title": "民劳", "section": "大雅", "group": "生民之什", "intro": "《民劳》收于《诗经·大雅·生民之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "民亦劳止，汔可小康。惠此中国，以绥四方。无纵诡随，以谨无良。", "sentences": ["民亦劳止，汔可小康。", "惠此中国，以绥四方。", "无纵诡随，以谨无良。"], "notes": "", "page": null}, {"text": "式遏寇虐，憯不畏明。柔远能迩，以定我王。", "sentences": ["式遏寇虐，憯不畏明。", "柔远能迩，以定我王。"], "notes": "", "page": null}, {"text": "民亦劳止，汔可小休。惠此中国，以为民逑。无纵诡随，以谨惛怓。", "sentences": ["民亦劳止，汔可小休。", "惠此中国，以为民逑。", "无纵诡随，以谨惛怓。"], "notes": "", "page": null}, {"text": "式遏寇虐，无俾民忧。无弃尔劳，以为王休。", "sentences": ["式遏寇虐，无俾民忧。", "无弃尔劳，以为王休。"], "notes": "", "page": null}, {"text": "民亦劳止，汔可小息。惠此京师，以绥四国。无纵诡随，以谨罔极。", "sentences": ["民亦劳止，汔可小息。", "惠此京师，以绥四国。", "无纵诡随，以谨罔极。"], "notes": "", "page": null}, {"text": "式遏寇虐，无俾作慝。敬慎威仪，以近有德。", "sentences": ["式遏寇虐，无俾作慝。", "敬慎威仪，以近有德。"], "notes": "", "page": null}, {"text": "民亦劳止，汔可小愒。惠此中国，俾民忧泄。无纵诡随，以谨丑厉。", "sentences": ["民亦劳止，汔可小愒。", "惠此中国，俾民忧泄。", "无纵诡随，以谨丑厉。"], "notes": "", "page": null}, {"text": "式遏寇虐，无俾正败。戎虽小子，而式弘大。", "sentences": ["式遏寇虐，无俾正败。", "戎虽小子，而式弘大。"], "notes": "", "page": null}, {"text": "民亦劳止，汔可小安。惠此中国，国无有残。无纵诡随，以谨缱绻。", "sentences": ["民亦劳止，汔可小安。", "惠此中国，国无有残。", "无纵诡随，以谨缱绻。"], "notes": "", "page": null}, {"text": "式遏寇虐，无俾正反。王欲玉女，是用大谏。", "sentences": ["式遏寇虐，无俾正反。", "王欲玉女，是用大谏。"], "notes": "", "page": null}]}, {"id": "p254", "title": "板", "section": "大雅", "group": "生民之什", "intro": "《板》收于《诗经·大雅·生民之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "上帝板板，下民卒瘅。出话不然，为犹不远。", "sentences": ["上帝板板，下民卒瘅。", "出话不然，为犹不远。"], "notes": "", "page": null}, {"text": "靡圣管管。不实于亶。犹之未远，是用大谏。", "sentences": ["靡圣管管。", "不实于亶。", "犹之未远，是用大谏。"], "notes": "", "page": null}, {"text": "天之方难，无然宪宪。天之方蹶，无然泄泄。", "sentences": ["天之方难，无然宪宪。", "天之方蹶，无然泄泄。"], "notes": "", "page": null}, {"text": "辞之辑矣，民之洽矣。辞之怿矣，民之莫矣。", "sentences": ["辞之辑矣，民之洽矣。", "辞之怿矣，民之莫矣。"], "notes": "", "page": null}, {"text": "我虽异事，及尔同僚。我即尔谋，听我嚣嚣。", "sentences": ["我虽异事，及尔同僚。", "我即尔谋，听我嚣嚣。"], "notes": "", "page": null}, {"text": "我言维服，勿以为笑。先民有言，询于刍荛。", "sentences": ["我言维服，勿以为笑。", "先民有言，询于刍荛。"], "notes": "", "page": null}, {"text": "天之方虐，无然谑谑。老夫灌灌，小子蹻蹻。", "sentences": ["天之方虐，无然谑谑。", "老夫灌灌，小子蹻蹻。"], "notes": "", "page": null}, {"text": "匪我言耄，尔用忧谑。多将熇熇，不可救药。", "sentences": ["匪我言耄，尔用忧谑。", "多将熇熇，不可救药。"], "notes": "", "page": null}, {"text": "天之方懠。无为夸毗。威仪卒迷，善人载尸。", "sentences": ["天之方懠。", "无为夸毗。", "威仪卒迷，善人载尸。"], "notes": "", "page": null}, {"text": "民之方殿屎，则莫我敢葵？丧乱蔑资，曾莫惠我师？", "sentences": ["民之方殿屎，则莫我敢葵？", "丧乱蔑资，曾莫惠我师？"], "notes": "", "page": null}, {"text": "天之牖民，如埙如篪，如璋如圭，如取如携。", "sentences": ["天之牖民，如埙如篪，如璋如圭，如取如携。"], "notes": "", "page": null}, {"text": "携无曰益，牖民孔易。民之多辟，无自立辟。", "sentences": ["携无曰益，牖民孔易。", "民之多辟，无自立辟。"], "notes": "", "page": null}, {"text": "价人维藩，大师维垣，大邦维屏，大宗维翰，", "sentences": ["价人维藩，大师维垣，大邦维屏，大宗维翰，"], "notes": "", "page": null}, {"text": "怀德维宁，宗子维城。无俾城坏，无独斯畏。", "sentences": ["怀德维宁，宗子维城。", "无俾城坏，无独斯畏。"], "notes": "", "page": null}, {"text": "敬天之怒，无敢戏豫。敬天之渝，无敢驰驱。", "sentences": ["敬天之怒，无敢戏豫。", "敬天之渝，无敢驰驱。"], "notes": "", "page": null}, {"text": "昊天曰明，及尔出王。昊天曰旦，及尔游衍。", "sentences": ["昊天曰明，及尔出王。", "昊天曰旦，及尔游衍。"], "notes": "", "page": null}]}, {"id": "p255", "title": "荡", "section": "大雅", "group": "荡之什", "intro": "《荡》收于《诗经·大雅·荡之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "荡荡上帝，下民之辟。疾威上帝，其命多辟。", "sentences": ["荡荡上帝，下民之辟。", "疾威上帝，其命多辟。"], "notes": "", "page": null}, {"text": "天生烝民，其命匪谌。靡不有初，鲜克有终。", "sentences": ["天生烝民，其命匪谌。", "靡不有初，鲜克有终。"], "notes": "", "page": null}, {"text": "文王曰咨，咨汝殷商。曾是彊御？曾是掊克？", "sentences": ["文王曰咨，咨汝殷商。", "曾是彊御？", "曾是掊克？"], "notes": "", "page": null}, {"text": "曾是在位？曾是在服？天降滔德，女兴是力。", "sentences": ["曾是在位？", "曾是在服？", "天降滔德，女兴是力。"], "notes": "", "page": null}, {"text": "文王曰咨，咨女殷商。而秉义类，彊御多怼。", "sentences": ["文王曰咨，咨女殷商。", "而秉义类，彊御多怼。"], "notes": "", "page": null}, {"text": "流言以对。寇攘式内。侯作侯祝，靡届靡究。", "sentences": ["流言以对。", "寇攘式内。", "侯作侯祝，靡届靡究。"], "notes": "", "page": null}, {"text": "文王曰咨，咨女殷商。女炰烋于中国。敛怨以为德。", "sentences": ["文王曰咨，咨女殷商。", "女炰烋于中国。", "敛怨以为德。"], "notes": "", "page": null}, {"text": "不明尔德，时无背无侧。尔德不明，以无陪无卿。", "sentences": ["不明尔德，时无背无侧。", "尔德不明，以无陪无卿。"], "notes": "", "page": null}, {"text": "文王曰咨，咨女殷商。天不湎尔以酒，不义从式。", "sentences": ["文王曰咨，咨女殷商。", "天不湎尔以酒，不义从式。"], "notes": "", "page": null}, {"text": "既衍尔止。靡明靡晦。式号式呼。俾昼作夜。", "sentences": ["既衍尔止。", "靡明靡晦。", "式号式呼。", "俾昼作夜。"], "notes": "", "page": null}, {"text": "文王曰咨，咨女殷商。如蜩如螗，如沸如羹。", "sentences": ["文王曰咨，咨女殷商。", "如蜩如螗，如沸如羹。"], "notes": "", "page": null}, {"text": "小大近丧，人尚乎由行。内奰于中国，覃及鬼方。", "sentences": ["小大近丧，人尚乎由行。", "内奰于中国，覃及鬼方。"], "notes": "", "page": null}, {"text": "文王曰咨，咨女殷商。匪上帝不时，殷不用旧。", "sentences": ["文王曰咨，咨女殷商。", "匪上帝不时，殷不用旧。"], "notes": "", "page": null}, {"text": "虽无老成人，尚有典刑。曾是莫听，大命以倾。", "sentences": ["虽无老成人，尚有典刑。", "曾是莫听，大命以倾。"], "notes": "", "page": null}, {"text": "文王曰咨，咨女殷商。人亦有言：颠沛之揭，", "sentences": ["文王曰咨，咨女殷商。", "人亦有言：颠沛之揭，"], "notes": "", "page": null}, {"text": "枝叶未有害，本实先拨。殷鉴不远，在夏后之世。", "sentences": ["枝叶未有害，本实先拨。", "殷鉴不远，在夏后之世。"], "notes": "", "page": null}]}, {"id": "p256", "title": "抑", "section": "大雅", "group": "荡之什", "intro": "《抑》收于《诗经·大雅·荡之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "抑抑威仪，维德之隅。人亦有言：靡哲不愚，庶人之愚，亦职维疾。", "sentences": ["抑抑威仪，维德之隅。", "人亦有言：靡哲不愚，庶人之愚，亦职维疾。"], "notes": "", "page": null}, {"text": "哲人之愚，亦维斯戾。无竞维人，四方其训之。有觉德行，四国顺之。", "sentences": ["哲人之愚，亦维斯戾。", "无竞维人，四方其训之。", "有觉德行，四国顺之。"], "notes": "", "page": null}, {"text": "訏谟定命，远犹辰告。敬慎威仪，维民之则。其在于今，兴迷乱于政。", "sentences": ["訏谟定命，远犹辰告。", "敬慎威仪，维民之则。", "其在于今，兴迷乱于政。"], "notes": "", "page": null}, {"text": "颠覆厥德，荒湛于酒。女虽湛乐从，弗念厥绍。罔敷求先王，克共明刑。", "sentences": ["颠覆厥德，荒湛于酒。", "女虽湛乐从，弗念厥绍。", "罔敷求先王，克共明刑。"], "notes": "", "page": null}, {"text": "四皇天弗尚，如彼泉流，无沦胥以亡。夙兴夜寐，洒扫庭内，维民之章。", "sentences": ["四皇天弗尚，如彼泉流，无沦胥以亡。", "夙兴夜寐，洒扫庭内，维民之章。"], "notes": "", "page": null}, {"text": "修尔车马，弓矢戎兵，用戒戎作，用逷蛮方。质尔人民，谨尔侯度，用戒不虞。", "sentences": ["修尔车马，弓矢戎兵，用戒戎作，用逷蛮方。", "质尔人民，谨尔侯度，用戒不虞。"], "notes": "", "page": null}, {"text": "慎尔出话，敬尔威仪，无不柔嘉。白圭之玷，尚可磨也；斯言之玷，不可为也！", "sentences": ["慎尔出话，敬尔威仪，无不柔嘉。", "白圭之玷，尚可磨也；斯言之玷，不可为也！"], "notes": "", "page": null}, {"text": "无易由言，无曰苟矣，莫扪朕舌，言不可逝矣。无言不仇，无德不报。", "sentences": ["无易由言，无曰苟矣，莫扪朕舌，言不可逝矣。", "无言不仇，无德不报。"], "notes": "", "page": null}, {"text": "惠于朋友，庶民小子。子孙绳绳，万民靡不承。视尔友君子，辑柔尔颜，不遐有愆。", "sentences": ["惠于朋友，庶民小子。", "子孙绳绳，万民靡不承。", "视尔友君子，辑柔尔颜，不遐有愆。"], "notes": "", "page": null}, {"text": "相在尔室，尚不愧于屋漏。无曰不显，莫予云觏。神之格思，不可度思，矧可射思！", "sentences": ["相在尔室，尚不愧于屋漏。", "无曰不显，莫予云觏。", "神之格思，不可度思，矧可射思！"], "notes": "", "page": null}, {"text": "辟尔为德，俾臧俾嘉。淑慎尔止，不愆于仪。不僭不贼，鲜不为则。投我以桃，报之以李。", "sentences": ["辟尔为德，俾臧俾嘉。", "淑慎尔止，不愆于仪。", "不僭不贼，鲜不为则。", "投我以桃，报之以李。"], "notes": "", "page": null}, {"text": "彼童而角，实虹小子。荏染柔木，言缗之丝。温温恭人，维德之基。", "sentences": ["彼童而角，实虹小子。", "荏染柔木，言缗之丝。", "温温恭人，维德之基。"], "notes": "", "page": null}, {"text": "其维哲人，告之话言，顺德之行。其维愚人，覆谓我僭。民各有心。", "sentences": ["其维哲人，告之话言，顺德之行。", "其维愚人，覆谓我僭。", "民各有心。"], "notes": "", "page": null}, {"text": "于乎小子，未知臧否。匪手携之，言示之事。匪面命之，言提其耳。", "sentences": ["于乎小子，未知臧否。", "匪手携之，言示之事。", "匪面命之，言提其耳。"], "notes": "", "page": null}, {"text": "借曰未知，亦既抱子。民之靡盈，谁夙知而莫成？昊天孔昭，我生靡乐。", "sentences": ["借曰未知，亦既抱子。", "民之靡盈，谁夙知而莫成？", "昊天孔昭，我生靡乐。"], "notes": "", "page": null}, {"text": "视尔梦梦，我心惨惨。诲尔谆谆，听我藐藐。匪用为教，覆用为虐。", "sentences": ["视尔梦梦，我心惨惨。", "诲尔谆谆，听我藐藐。", "匪用为教，覆用为虐。"], "notes": "", "page": null}, {"text": "借曰未知，亦聿既耄。于乎，小子，告尔旧止。听用我谋，庶无大悔。", "sentences": ["借曰未知，亦聿既耄。", "于乎，小子，告尔旧止。", "听用我谋，庶无大悔。"], "notes": "", "page": null}, {"text": "天方艰难，曰丧厥国。取譬不远，昊天不忒。回遹其德，俾民大棘。", "sentences": ["天方艰难，曰丧厥国。", "取譬不远，昊天不忒。", "回遹其德，俾民大棘。"], "notes": "", "page": null}]}, {"id": "p257", "title": "桑柔", "section": "大雅", "group": "荡之什", "intro": "《桑柔》收于《诗经·大雅·荡之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "菀彼桑柔，其下侯旬，捋采其刘，瘼此下民。不殄心忧，仓兄填兮。倬彼昊天，宁不我矜？", "sentences": ["菀彼桑柔，其下侯旬，捋采其刘，瘼此下民。", "不殄心忧，仓兄填兮。", "倬彼昊天，宁不我矜？"], "notes": "", "page": null}, {"text": "四牡骙骙，旟旐有翩。乱生不夷，靡国不泯。民靡有黎，具祸以烬。于乎有哀，国步斯频。", "sentences": ["四牡骙骙，旟旐有翩。", "乱生不夷，靡国不泯。", "民靡有黎，具祸以烬。", "于乎有哀，国步斯频。"], "notes": "", "page": null}, {"text": "国步灭资，天不我将。靡所止疑，云徂何往？君子实维，秉心无竞。谁生厉阶，至今为梗？", "sentences": ["国步灭资，天不我将。", "靡所止疑，云徂何往？", "君子实维，秉心无竞。", "谁生厉阶，至今为梗？"], "notes": "", "page": null}, {"text": "忧心殷殷，念我土宇。我生不辰，逢天僤怒。自西徂东，靡所定处。多我觏痻，孔棘我圉。", "sentences": ["忧心殷殷，念我土宇。", "我生不辰，逢天僤怒。", "自西徂东，靡所定处。", "多我觏痻，孔棘我圉。"], "notes": "", "page": null}, {"text": "为谋为毖，乱况斯削。告尔忧恤，诲尔序爵。谁能执热，逝不以濯？其何能淑，载胥及溺。", "sentences": ["为谋为毖，乱况斯削。", "告尔忧恤，诲尔序爵。", "谁能执热，逝不以濯？", "其何能淑，载胥及溺。"], "notes": "", "page": null}, {"text": "如彼溯风，亦孔之僾。民有肃心，荓云不逮。好是稼穑，力民代食。稼穑维宝，代食维好？", "sentences": ["如彼溯风，亦孔之僾。", "民有肃心，荓云不逮。", "好是稼穑，力民代食。", "稼穑维宝，代食维好？"], "notes": "", "page": null}, {"text": "天降丧乱，灭我立王。降此蟊贼，稼穑卒痒。哀恫中国，具赘卒荒。靡有旅力，以念穹苍。", "sentences": ["天降丧乱，灭我立王。", "降此蟊贼，稼穑卒痒。", "哀恫中国，具赘卒荒。", "靡有旅力，以念穹苍。"], "notes": "", "page": null}, {"text": "维此惠君，民人所瞻。秉心宣犹，考慎其相。维彼不顺，自独俾臧。自有肺肠，俾民卒狂。", "sentences": ["维此惠君，民人所瞻。", "秉心宣犹，考慎其相。", "维彼不顺，自独俾臧。", "自有肺肠，俾民卒狂。"], "notes": "", "page": null}, {"text": "瞻彼中林，甡甡其鹿。朋友已谮，不胥以穀。人亦有言：进退维谷。", "sentences": ["瞻彼中林，甡甡其鹿。", "朋友已谮，不胥以穀。", "人亦有言：进退维谷。"], "notes": "", "page": null}, {"text": "维此圣人，瞻言百里。维彼愚人，覆狂以喜。匪言不能，胡斯畏忌？", "sentences": ["维此圣人，瞻言百里。", "维彼愚人，覆狂以喜。", "匪言不能，胡斯畏忌？"], "notes": "", "page": null}, {"text": "维此良人，弗求弗迪。维彼忍心，是顾是复。民之贪乱，宁为荼毒。", "sentences": ["维此良人，弗求弗迪。", "维彼忍心，是顾是复。", "民之贪乱，宁为荼毒。"], "notes": "", "page": null}, {"text": "大风有隧，有空大谷。维此良人，作为式穀。维彼不顺，征以中垢。", "sentences": ["大风有隧，有空大谷。", "维此良人，作为式穀。", "维彼不顺，征以中垢。"], "notes": "", "page": null}, {"text": "大风有隧，贪人败类。听言则对，诵言如醉。匪用其良，复俾我悖。", "sentences": ["大风有隧，贪人败类。", "听言则对，诵言如醉。", "匪用其良，复俾我悖。"], "notes": "", "page": null}, {"text": "嗟尔朋友，予岂不知而作。如彼飞虫，时亦弋获。既之阴女，反予来赫。", "sentences": ["嗟尔朋友，予岂不知而作。", "如彼飞虫，时亦弋获。", "既之阴女，反予来赫。"], "notes": "", "page": null}, {"text": "民之罔极，职凉善背。为民不利，如云不克。民之回遹，职竞用力。", "sentences": ["民之罔极，职凉善背。", "为民不利，如云不克。", "民之回遹，职竞用力。"], "notes": "", "page": null}, {"text": "民之未戾，职盗为寇。凉曰不可，覆背善詈。虽曰匪予，既作尔歌！", "sentences": ["民之未戾，职盗为寇。", "凉曰不可，覆背善詈。", "虽曰匪予，既作尔歌！"], "notes": "", "page": null}]}, {"id": "p258", "title": "云汉", "section": "大雅", "group": "荡之什", "intro": "《云汉》收于《诗经·大雅·荡之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "倬彼云汉，昭回于天。王曰：于乎！何辜今之人？天降丧乱，饥馑荐臻。", "sentences": ["倬彼云汉，昭回于天。", "王曰：于乎！", "何辜今之人？", "天降丧乱，饥馑荐臻。"], "notes": "", "page": null}, {"text": "靡神不举，靡爱斯牲。圭壁既卒，宁莫我听？", "sentences": ["靡神不举，靡爱斯牲。", "圭壁既卒，宁莫我听？"], "notes": "", "page": null}, {"text": "旱既大甚，蕴隆虫虫。不殄禋祀，自郊徂宫。上下奠瘗，靡神不宗。", "sentences": ["旱既大甚，蕴隆虫虫。", "不殄禋祀，自郊徂宫。", "上下奠瘗，靡神不宗。"], "notes": "", "page": null}, {"text": "后稷不克，上帝不临。耗斁下土，宁丁我梗", "sentences": ["后稷不克，上帝不临。", "耗斁下土，宁丁我梗"], "notes": "", "page": null}, {"text": "旱既大甚，则不可推。兢兢业业，如霆如雷。周余黎民，靡有孑遗。", "sentences": ["旱既大甚，则不可推。", "兢兢业业，如霆如雷。", "周余黎民，靡有孑遗。"], "notes": "", "page": null}, {"text": "昊天上帝，则不我遗。胡不相畏？先祖于摧。", "sentences": ["昊天上帝，则不我遗。", "胡不相畏？", "先祖于摧。"], "notes": "", "page": null}, {"text": "旱既大甚，则不可沮。赫赫炎炎，云我无所。大命近止，靡瞻靡顾。", "sentences": ["旱既大甚，则不可沮。", "赫赫炎炎，云我无所。", "大命近止，靡瞻靡顾。"], "notes": "", "page": null}, {"text": "群公先正，则不我助。父母先祖，胡宁忍予？", "sentences": ["群公先正，则不我助。", "父母先祖，胡宁忍予？"], "notes": "", "page": null}, {"text": "旱既大甚，涤涤山川。旱魃为虐，如惔如焚。我心惮暑，忧心如熏。", "sentences": ["旱既大甚，涤涤山川。", "旱魃为虐，如惔如焚。", "我心惮暑，忧心如熏。"], "notes": "", "page": null}, {"text": "群公先正，则不我闻。昊天上帝，宁俾我遁？", "sentences": ["群公先正，则不我闻。", "昊天上帝，宁俾我遁？"], "notes": "", "page": null}, {"text": "旱既大甚，黾勉畏去。胡宁瘨我以旱？憯不知其故。祈年孔夙，方社不莫。", "sentences": ["旱既大甚，黾勉畏去。", "胡宁瘨我以旱？", "憯不知其故。", "祈年孔夙，方社不莫。"], "notes": "", "page": null}, {"text": "昊天上帝，则不我虞。", "sentences": ["昊天上帝，则不我虞。"], "notes": "", "page": null}, {"text": "敬恭明神，宜无悔怒。旱既大甚，散无友纪。鞫哉庶正，疚哉冢宰。", "sentences": ["敬恭明神，宜无悔怒。", "旱既大甚，散无友纪。", "鞫哉庶正，疚哉冢宰。"], "notes": "", "page": null}, {"text": "趣马师氏，膳夫左右。靡人不周。无不能止，瞻卬昊天，云如何里！", "sentences": ["趣马师氏，膳夫左右。", "靡人不周。", "无不能止，瞻卬昊天，云如何里！"], "notes": "", "page": null}, {"text": "瞻卬昊天，有嘒其星。大夫君子，昭假无赢。大命近止，无弃尔成。", "sentences": ["瞻卬昊天，有嘒其星。", "大夫君子，昭假无赢。", "大命近止，无弃尔成。"], "notes": "", "page": null}, {"text": "何求为我。以戾庶正。瞻卬昊天，曷惠其宁？", "sentences": ["何求为我。", "以戾庶正。", "瞻卬昊天，曷惠其宁？"], "notes": "", "page": null}]}, {"id": "p259", "title": "崧高", "section": "大雅", "group": "荡之什", "intro": "《崧高》收于《诗经·大雅·荡之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "崧高维岳，骏极于天。维岳降神，生甫及申。维申及甫，维周之翰。四国于蕃。四方于宣。", "sentences": ["崧高维岳，骏极于天。", "维岳降神，生甫及申。", "维申及甫，维周之翰。", "四国于蕃。", "四方于宣。"], "notes": "", "page": null}, {"text": "亹亹申伯，王缵之事。于邑于谢，南国是式。王命召伯，定申伯之宅。登是南邦，世执其功。", "sentences": ["亹亹申伯，王缵之事。", "于邑于谢，南国是式。", "王命召伯，定申伯之宅。", "登是南邦，世执其功。"], "notes": "", "page": null}, {"text": "王命申伯，式是南邦。因是谢人，以作尔庸。王命召伯，彻申伯土田。王命傅御，迁其私人。", "sentences": ["王命申伯，式是南邦。", "因是谢人，以作尔庸。", "王命召伯，彻申伯土田。", "王命傅御，迁其私人。"], "notes": "", "page": null}, {"text": "申伯之功，召伯是营。有俶其城，寝庙既成。既成藐藐，王锡申伯。四牡蹻蹻，钩膺濯濯。", "sentences": ["申伯之功，召伯是营。", "有俶其城，寝庙既成。", "既成藐藐，王锡申伯。", "四牡蹻蹻，钩膺濯濯。"], "notes": "", "page": null}, {"text": "王遣申伯，路车乘马。我图尔居，莫如南土。锡尔介圭，以作尔宝。往近王舅，南土是保。", "sentences": ["王遣申伯，路车乘马。", "我图尔居，莫如南土。", "锡尔介圭，以作尔宝。", "往近王舅，南土是保。"], "notes": "", "page": null}, {"text": "申伯信迈，王饯于郿。申伯还南，谢于诚归。王命召伯，彻申伯土疆。以峙其粻，式遄其行。", "sentences": ["申伯信迈，王饯于郿。", "申伯还南，谢于诚归。", "王命召伯，彻申伯土疆。", "以峙其粻，式遄其行。"], "notes": "", "page": null}, {"text": "申伯番番，既入于谢。徒御啴啴。周邦咸喜，戎有良翰。不显申伯，王之元舅，文武是宪。", "sentences": ["申伯番番，既入于谢。", "徒御啴啴。", "周邦咸喜，戎有良翰。", "不显申伯，王之元舅，文武是宪。"], "notes": "", "page": null}, {"text": "申伯之德，柔惠且直。揉此万邦，闻于四国。吉甫作诵，其诗孔硕。其风四好，以赠申伯。", "sentences": ["申伯之德，柔惠且直。", "揉此万邦，闻于四国。", "吉甫作诵，其诗孔硕。", "其风四好，以赠申伯。"], "notes": "", "page": null}]}, {"id": "p260", "title": "烝民", "section": "大雅", "group": "荡之什", "intro": "《烝民》收于《诗经·大雅·荡之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "天生烝民，有物有则。民之秉彝，好是懿德。天监有周，昭假于下。保兹天子，生仲山甫。", "sentences": ["天生烝民，有物有则。", "民之秉彝，好是懿德。", "天监有周，昭假于下。", "保兹天子，生仲山甫。"], "notes": "", "page": null}, {"text": "仲山甫之德，柔嘉维则。令仪令色。小心翼翼。古训是式。威仪是力。天子是若，明命使赋。", "sentences": ["仲山甫之德，柔嘉维则。", "令仪令色。", "小心翼翼。", "古训是式。", "威仪是力。", "天子是若，明命使赋。"], "notes": "", "page": null}, {"text": "王命仲山甫，式是百辟，缵戎祖考，王躬是保。出纳王命，王之喉舌。赋政于外，四方爰发。", "sentences": ["王命仲山甫，式是百辟，缵戎祖考，王躬是保。", "出纳王命，王之喉舌。", "赋政于外，四方爰发。"], "notes": "", "page": null}, {"text": "肃肃王命，仲山甫将之。邦国若否，仲山甫明之。既明且哲，以保其身。夙夜匪解，以事一人。", "sentences": ["肃肃王命，仲山甫将之。", "邦国若否，仲山甫明之。", "既明且哲，以保其身。", "夙夜匪解，以事一人。"], "notes": "", "page": null}, {"text": "人亦有言，柔则茹之，刚则吐之。维仲山甫，柔亦不茹，刚亦不吐。不侮矜寡，不畏强御。", "sentences": ["人亦有言，柔则茹之，刚则吐之。", "维仲山甫，柔亦不茹，刚亦不吐。", "不侮矜寡，不畏强御。"], "notes": "", "page": null}, {"text": "人亦有言，德輶如毛，民鲜克举之。我仪图之，维仲山甫举之。爱莫助之。衮职有阙，维仲山甫补之。", "sentences": ["人亦有言，德輶如毛，民鲜克举之。", "我仪图之，维仲山甫举之。", "爱莫助之。", "衮职有阙，维仲山甫补之。"], "notes": "", "page": null}, {"text": "仲山甫出祖。四牡业业。征夫捷捷，每怀靡及。四牡彭彭，八鸾锵锵。王命仲山甫，城彼东方。", "sentences": ["仲山甫出祖。", "四牡业业。", "征夫捷捷，每怀靡及。", "四牡彭彭，八鸾锵锵。", "王命仲山甫，城彼东方。"], "notes": "", "page": null}, {"text": "四牡骙骙，八鸾喈喈。仲山甫徂齐，式遄其归。吉甫作诵，穆如清风。仲山甫永怀，以慰其心。", "sentences": ["四牡骙骙，八鸾喈喈。", "仲山甫徂齐，式遄其归。", "吉甫作诵，穆如清风。", "仲山甫永怀，以慰其心。"], "notes": "", "page": null}]}, {"id": "p261", "title": "韩奕", "section": "大雅", "group": "荡之什", "intro": "《韩奕》收于《诗经·大雅·荡之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "奕奕梁山，维禹甸之，有倬其道。", "sentences": ["奕奕梁山，维禹甸之，有倬其道。"], "notes": "", "page": null}, {"text": "韩侯受命，王亲命之：缵戎祖考，无废朕命。", "sentences": ["韩侯受命，王亲命之：缵戎祖考，无废朕命。"], "notes": "", "page": null}, {"text": "夙夜匪解，虔共尔位，朕命不易。", "sentences": ["夙夜匪解，虔共尔位，朕命不易。"], "notes": "", "page": null}, {"text": "粲不庭方，以佐戎辟。四牡奕奕，孔修且张。", "sentences": ["粲不庭方，以佐戎辟。", "四牡奕奕，孔修且张。"], "notes": "", "page": null}, {"text": "韩侯入觐，以其介圭，入觐于王。", "sentences": ["韩侯入觐，以其介圭，入觐于王。"], "notes": "", "page": null}, {"text": "王锡韩侯，淑旂绥章，簟茀错衡。", "sentences": ["王锡韩侯，淑旂绥章，簟茀错衡。"], "notes": "", "page": null}, {"text": "玄衮赤舄，钩膺镂锡，鞹鞃浅幭，鞗革金厄。", "sentences": ["玄衮赤舄，钩膺镂锡，鞹鞃浅幭，鞗革金厄。"], "notes": "", "page": null}, {"text": "韩侯出祖，出宿于屠。显父饯之，清酒百壶。", "sentences": ["韩侯出祖，出宿于屠。", "显父饯之，清酒百壶。"], "notes": "", "page": null}, {"text": "其殽维何？炰鳖鲜鱼。其蔌维何？维笋及蒲。", "sentences": ["其殽维何？", "炰鳖鲜鱼。", "其蔌维何？", "维笋及蒲。"], "notes": "", "page": null}, {"text": "其赠维何？乘马路车。笾豆有且。侯氏燕胥。", "sentences": ["其赠维何？", "乘马路车。", "笾豆有且。", "侯氏燕胥。"], "notes": "", "page": null}, {"text": "韩侯取妻，汾王之甥，蹶父之子。", "sentences": ["韩侯取妻，汾王之甥，蹶父之子。"], "notes": "", "page": null}, {"text": "韩侯迎止，于蹶之里。", "sentences": ["韩侯迎止，于蹶之里。"], "notes": "", "page": null}, {"text": "百两彭彭，八鸾锵锵，不显其光。", "sentences": ["百两彭彭，八鸾锵锵，不显其光。"], "notes": "", "page": null}, {"text": "诸娣从之，祁祁如云。韩侯顾之，烂其盈门。", "sentences": ["诸娣从之，祁祁如云。", "韩侯顾之，烂其盈门。"], "notes": "", "page": null}, {"text": "蹶父孔武，靡国不到。为韩姞相攸，莫如韩乐。", "sentences": ["蹶父孔武，靡国不到。", "为韩姞相攸，莫如韩乐。"], "notes": "", "page": null}, {"text": "孔乐韩土，川泽訏訏，鲂鱮甫甫，麀鹿噳噳。", "sentences": ["孔乐韩土，川泽訏訏，鲂鱮甫甫，麀鹿噳噳。"], "notes": "", "page": null}, {"text": "有熊有罴，有猫有虎。庆既令居，韩姞燕誉。", "sentences": ["有熊有罴，有猫有虎。", "庆既令居，韩姞燕誉。"], "notes": "", "page": null}, {"text": "溥彼韩城，燕师所完。以先祖受命，因时百蛮。", "sentences": ["溥彼韩城，燕师所完。", "以先祖受命，因时百蛮。"], "notes": "", "page": null}, {"text": "王锡韩侯，其追其貊。奄受北国，因以其伯。", "sentences": ["王锡韩侯，其追其貊。", "奄受北国，因以其伯。"], "notes": "", "page": null}, {"text": "实墉实壑，实亩实藉。献其貔皮，赤豹黄罴。", "sentences": ["实墉实壑，实亩实藉。", "献其貔皮，赤豹黄罴。"], "notes": "", "page": null}]}, {"id": "p262", "title": "江汉", "section": "大雅", "group": "荡之什", "intro": "《江汉》收于《诗经·大雅·荡之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "江汉浮浮，武夫滔滔。匪安匪游，淮夷来求。既出我车，既设我旟。匪安匪舒，淮夷来铺。", "sentences": ["江汉浮浮，武夫滔滔。", "匪安匪游，淮夷来求。", "既出我车，既设我旟。", "匪安匪舒，淮夷来铺。"], "notes": "", "page": null}, {"text": "江汉汤汤，武夫洸洸。经营四方，告成于王。四方既平，王国庶定。时靡有争，王心载宁。", "sentences": ["江汉汤汤，武夫洸洸。", "经营四方，告成于王。", "四方既平，王国庶定。", "时靡有争，王心载宁。"], "notes": "", "page": null}, {"text": "江汉之浒，王命召虎：式辟四方，彻我疆土。匪疚匪棘，王国来极。于疆于理，至于南海。", "sentences": ["江汉之浒，王命召虎：式辟四方，彻我疆土。", "匪疚匪棘，王国来极。", "于疆于理，至于南海。"], "notes": "", "page": null}, {"text": "王命召虎：来旬来宣。文武受命，召公维翰。无曰予小子，召公是似。肇敏戎公，用锡尔祉。", "sentences": ["王命召虎：来旬来宣。", "文武受命，召公维翰。", "无曰予小子，召公是似。", "肇敏戎公，用锡尔祉。"], "notes": "", "page": null}, {"text": "厘尔圭瓒，秬鬯一卣。告于文人，锡山土田。于周受命，自召祖命，虎拜稽首：天子万年！", "sentences": ["厘尔圭瓒，秬鬯一卣。", "告于文人，锡山土田。", "于周受命，自召祖命，虎拜稽首：天子万年！"], "notes": "", "page": null}, {"text": "虎拜稽首，对扬王休。作召公考：天子万寿！明明天子，令闻不已，矢其文德，洽此四国。", "sentences": ["虎拜稽首，对扬王休。", "作召公考：天子万寿！", "明明天子，令闻不已，矢其文德，洽此四国。"], "notes": "", "page": null}]}, {"id": "p263", "title": "常武", "section": "大雅", "group": "荡之什", "intro": "《常武》收于《诗经·大雅·荡之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "赫赫明明。王命卿士，南仲大祖，大师皇父。整我六师，以修我戎。既敬既戒，惠此南国。", "sentences": ["赫赫明明。", "王命卿士，南仲大祖，大师皇父。", "整我六师，以修我戎。", "既敬既戒，惠此南国。"], "notes": "", "page": null}, {"text": "王谓尹氏，命程伯休父，左右陈行。戒我师旅，率彼淮浦，省此徐土。不留不处，三事就绪。", "sentences": ["王谓尹氏，命程伯休父，左右陈行。", "戒我师旅，率彼淮浦，省此徐土。", "不留不处，三事就绪。"], "notes": "", "page": null}, {"text": "赫赫业业，有严天子。王舒保作，匪绍匪游。徐方绎骚，震惊徐方。如雷如霆，徐方震惊。", "sentences": ["赫赫业业，有严天子。", "王舒保作，匪绍匪游。", "徐方绎骚，震惊徐方。", "如雷如霆，徐方震惊。"], "notes": "", "page": null}, {"text": "王奋厥武，如震如怒。进厥虎臣，阚如虓虎。铺敦淮濆，仍执丑虏。截彼淮浦，王师之所。", "sentences": ["王奋厥武，如震如怒。", "进厥虎臣，阚如虓虎。", "铺敦淮濆，仍执丑虏。", "截彼淮浦，王师之所。"], "notes": "", "page": null}, {"text": "王旅啴啴，如飞如翰。如江如汉，如山之苞。如川之流，绵绵翼翼。不测不克，濯征徐国。", "sentences": ["王旅啴啴，如飞如翰。", "如江如汉，如山之苞。", "如川之流，绵绵翼翼。", "不测不克，濯征徐国。"], "notes": "", "page": null}, {"text": "王犹允塞，徐方既来。徐方既同，天子之功。四方既平，徐方来庭。徐方不回，王曰还归。", "sentences": ["王犹允塞，徐方既来。", "徐方既同，天子之功。", "四方既平，徐方来庭。", "徐方不回，王曰还归。"], "notes": "", "page": null}]}, {"id": "p264", "title": "瞻卬", "section": "大雅", "group": "荡之什", "intro": "《瞻卬》收于《诗经·大雅·荡之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "瞻卬昊天，则不我惠。孔填不宁，降此大厉。邦靡有定，士民其瘵。", "sentences": ["瞻卬昊天，则不我惠。", "孔填不宁，降此大厉。", "邦靡有定，士民其瘵。"], "notes": "", "page": null}, {"text": "蟊贼蟊疾，靡有夷届。罪罟不收，靡有夷瘳。", "sentences": ["蟊贼蟊疾，靡有夷届。", "罪罟不收，靡有夷瘳。"], "notes": "", "page": null}, {"text": "人有土田，女反有之。人有民人，女覆夺之。此宜无罪，女反收之。", "sentences": ["人有土田，女反有之。", "人有民人，女覆夺之。", "此宜无罪，女反收之。"], "notes": "", "page": null}, {"text": "彼宜有罪，女覆说之。", "sentences": ["彼宜有罪，女覆说之。"], "notes": "", "page": null}, {"text": "哲夫成城，哲妇倾城。懿厥哲妇，为枭为鸱。妇有长舌，维厉之阶。", "sentences": ["哲夫成城，哲妇倾城。", "懿厥哲妇，为枭为鸱。", "妇有长舌，维厉之阶。"], "notes": "", "page": null}, {"text": "乱匪降自天，生自妇人。匪教匪诲，时维妇寺。", "sentences": ["乱匪降自天，生自妇人。", "匪教匪诲，时维妇寺。"], "notes": "", "page": null}, {"text": "鞫人忮忒。谮始竞背。岂曰不极？伊胡为慝？如贾三倍，君子是识。", "sentences": ["鞫人忮忒。", "谮始竞背。", "岂曰不极？", "伊胡为慝？", "如贾三倍，君子是识。"], "notes": "", "page": null}, {"text": "妇无公事，休其蚕织。", "sentences": ["妇无公事，休其蚕织。"], "notes": "", "page": null}, {"text": "天何以剌？何神不富？舍尔介狄，维予胥忌。不吊不祥，威仪不类。", "sentences": ["天何以剌？", "何神不富？", "舍尔介狄，维予胥忌。", "不吊不祥，威仪不类。"], "notes": "", "page": null}, {"text": "人之云亡，邦国殄瘁。", "sentences": ["人之云亡，邦国殄瘁。"], "notes": "", "page": null}, {"text": "天之降罔，维其优矣。人之云亡，心之忧矣。天之降罔，维其几矣。", "sentences": ["天之降罔，维其优矣。", "人之云亡，心之忧矣。", "天之降罔，维其几矣。"], "notes": "", "page": null}, {"text": "人之云亡，心之悲矣。", "sentences": ["人之云亡，心之悲矣。"], "notes": "", "page": null}, {"text": "觱沸槛泉，维其深矣。心之忧矣，宁自今矣？不自我先，不自我后。", "sentences": ["觱沸槛泉，维其深矣。", "心之忧矣，宁自今矣？", "不自我先，不自我后。"], "notes": "", "page": null}, {"text": "藐藐昊天，无不克巩。无忝皇祖，式救尔后。", "sentences": ["藐藐昊天，无不克巩。", "无忝皇祖，式救尔后。"], "notes": "", "page": null}]}, {"id": "p265", "title": "召旻", "section": "大雅", "group": "荡之什", "intro": "《召旻》收于《诗经·大雅·荡之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "旻天疾威，天笃降丧。瘨我饥馑，民卒流亡。我居圉卒荒。", "sentences": ["旻天疾威，天笃降丧。", "瘨我饥馑，民卒流亡。", "我居圉卒荒。"], "notes": "", "page": null}, {"text": "天降罪罟，蟊贼内讧。昏椓靡共，溃溃回遹，实靖夷我邦。", "sentences": ["天降罪罟，蟊贼内讧。", "昏椓靡共，溃溃回遹，实靖夷我邦。"], "notes": "", "page": null}, {"text": "皋皋訿訿，曾不知其玷。兢兢业业，孔填不宁，我位孔贬。", "sentences": ["皋皋訿訿，曾不知其玷。", "兢兢业业，孔填不宁，我位孔贬。"], "notes": "", "page": null}, {"text": "如彼岁旱，草不溃茂，如彼栖苴。我相此邦，无不溃止。", "sentences": ["如彼岁旱，草不溃茂，如彼栖苴。", "我相此邦，无不溃止。"], "notes": "", "page": null}, {"text": "维昔之富不如时，维今之疚不如兹。彼疏斯粺，胡不自替？职兄斯引。", "sentences": ["维昔之富不如时，维今之疚不如兹。", "彼疏斯粺，胡不自替？", "职兄斯引。"], "notes": "", "page": null}, {"text": "池之竭矣，不云自频。泉之竭矣，不云自中。溥斯害矣，职兄斯弘，不灾我躬。", "sentences": ["池之竭矣，不云自频。", "泉之竭矣，不云自中。", "溥斯害矣，职兄斯弘，不灾我躬。"], "notes": "", "page": null}, {"text": "昔先王受命，有如召公，日辟国百里，今也日蹙国百里。于乎哀哉！维今之人，不尚有旧！", "sentences": ["昔先王受命，有如召公，日辟国百里，今也日蹙国百里。", "于乎哀哉！", "维今之人，不尚有旧！"], "notes": "", "page": null}]}, {"id": "p266", "title": "清庙", "section": "颂", "group": "周颂 · 清庙之什", "intro": "《清庙》收于《诗经·周颂·清庙之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "于穆清庙，肃雍显相。济济多士，秉文之德。对越在天，骏奔走在庙。不显不承，无射于人斯。", "sentences": ["于穆清庙，肃雍显相。", "济济多士，秉文之德。", "对越在天，骏奔走在庙。", "不显不承，无射于人斯。"], "notes": "", "page": null}]}, {"id": "p267", "title": "维天之命", "section": "颂", "group": "周颂 · 清庙之什", "intro": "《维天之命》收于《诗经·周颂·清庙之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "维天之命，于穆不已。于乎不显，文王之德之纯。假以溢我，我其收之。骏惠我文王，曾孙笃之。", "sentences": ["维天之命，于穆不已。", "于乎不显，文王之德之纯。", "假以溢我，我其收之。", "骏惠我文王，曾孙笃之。"], "notes": "", "page": null}]}, {"id": "p268", "title": "维清", "section": "颂", "group": "周颂 · 清庙之什", "intro": "《维清》收于《诗经·周颂·清庙之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "维清缉熙，文王之典。肇禋，迄用有成，维周之祯。", "sentences": ["维清缉熙，文王之典。", "肇禋，迄用有成，维周之祯。"], "notes": "", "page": null}]}, {"id": "p269", "title": "烈文", "section": "颂", "group": "周颂 · 清庙之什", "intro": "《烈文》收于《诗经·周颂·清庙之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "烈文辟公，锡兹祉福。惠我无疆，子孙保之。无封靡于尔邦，维王其崇之。", "sentences": ["烈文辟公，锡兹祉福。", "惠我无疆，子孙保之。", "无封靡于尔邦，维王其崇之。"], "notes": "", "page": null}, {"text": "念兹戎功，继序其皇之。无竞维人，四方其训之。不显维德，百辟其刑之。于乎，前王不忘！", "sentences": ["念兹戎功，继序其皇之。", "无竞维人，四方其训之。", "不显维德，百辟其刑之。", "于乎，前王不忘！"], "notes": "", "page": null}]}, {"id": "p270", "title": "天作", "section": "颂", "group": "周颂 · 清庙之什", "intro": "《天作》收于《诗经·周颂·清庙之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "天作高山，大王荒之。彼作矣，文王康之。彼徂矣，岐有夷之行。子孙保之。", "sentences": ["天作高山，大王荒之。", "彼作矣，文王康之。", "彼徂矣，岐有夷之行。", "子孙保之。"], "notes": "", "page": null}]}, {"id": "p271", "title": "昊天有成命", "section": "颂", "group": "周颂 · 清庙之什", "intro": "《昊天有成命》收于《诗经·周颂·清庙之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "昊天有成命，二后受之。成王不敢康，夙夜基命宥密。于缉熙！单厥心，四其靖之。", "sentences": ["昊天有成命，二后受之。", "成王不敢康，夙夜基命宥密。", "于缉熙！", "单厥心，四其靖之。"], "notes": "", "page": null}]}, {"id": "p272", "title": "我将", "section": "颂", "group": "周颂 · 清庙之什", "intro": "《我将》收于《诗经·周颂·清庙之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "我将我享，维羊维牛，维天其右之。仪式刑文王之典，日靖四方。", "sentences": ["我将我享，维羊维牛，维天其右之。", "仪式刑文王之典，日靖四方。"], "notes": "", "page": null}, {"text": "伊嘏文王，既右飨之。我其夙夜，畏天之威，于时保之。", "sentences": ["伊嘏文王，既右飨之。", "我其夙夜，畏天之威，于时保之。"], "notes": "", "page": null}]}, {"id": "p273", "title": "时迈", "section": "颂", "group": "周颂 · 清庙之什", "intro": "《时迈》收于《诗经·周颂·清庙之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "时迈其邦，昊天其子之，实右序有周。薄言震之，莫不震叠。怀柔百神，及河乔岳，允王维后。", "sentences": ["时迈其邦，昊天其子之，实右序有周。", "薄言震之，莫不震叠。", "怀柔百神，及河乔岳，允王维后。"], "notes": "", "page": null}, {"text": "明昭有周，式序在位。载戢干戈，载橐弓矢。我求懿德，四于时夏，允王保之。", "sentences": ["明昭有周，式序在位。", "载戢干戈，载橐弓矢。", "我求懿德，四于时夏，允王保之。"], "notes": "", "page": null}]}, {"id": "p274", "title": "执竞", "section": "颂", "group": "周颂 · 清庙之什", "intro": "《执竞》收于《诗经·周颂·清庙之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "执竞武王，无竞维烈。不显成康，上帝是皇。自彼成康，奄有四方，斤斤其明。", "sentences": ["执竞武王，无竞维烈。", "不显成康，上帝是皇。", "自彼成康，奄有四方，斤斤其明。"], "notes": "", "page": null}, {"text": "钟鼓喤喤，磬莞将将，降福穰穰。降福简简，威仪反反。既醉既饱，福禄来反。", "sentences": ["钟鼓喤喤，磬莞将将，降福穰穰。", "降福简简，威仪反反。", "既醉既饱，福禄来反。"], "notes": "", "page": null}]}, {"id": "p275", "title": "思文", "section": "颂", "group": "周颂 · 清庙之什", "intro": "《思文》收于《诗经·周颂·清庙之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "思文后稷，克配彼天。立我烝民，莫菲尔极。贻我来牟，帝命率育，无此疆尔界。陈常于时夏。", "sentences": ["思文后稷，克配彼天。", "立我烝民，莫菲尔极。", "贻我来牟，帝命率育，无此疆尔界。", "陈常于时夏。"], "notes": "", "page": null}]}, {"id": "p276", "title": "臣工", "section": "颂", "group": "周颂 · 臣工之什", "intro": "《臣工》收于《诗经·周颂·臣工之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "嗟嗟臣工，敬尔在公。王厘尔成，来咨来茹。嗟嗟保介，维莫之春，亦又何求？如何新畲？", "sentences": ["嗟嗟臣工，敬尔在公。", "王厘尔成，来咨来茹。", "嗟嗟保介，维莫之春，亦又何求？", "如何新畲？"], "notes": "", "page": null}, {"text": "于皇来牟，将受厥明。明昭上帝，迄用康年。命我众人：庤乃钱镈，奄观铚艾。", "sentences": ["于皇来牟，将受厥明。", "明昭上帝，迄用康年。", "命我众人：庤乃钱镈，奄观铚艾。"], "notes": "", "page": null}]}, {"id": "p277", "title": "噫嘻", "section": "颂", "group": "周颂 · 臣工之什", "intro": "《噫嘻》收于《诗经·周颂·臣工之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "噫嘻成王，既昭假尔。率时农夫，播厥百谷。骏发尔私，终三十里。亦服尔耕，十千维耦。", "sentences": ["噫嘻成王，既昭假尔。", "率时农夫，播厥百谷。", "骏发尔私，终三十里。", "亦服尔耕，十千维耦。"], "notes": "", "page": null}]}, {"id": "p278", "title": "振鹭", "section": "颂", "group": "周颂 · 臣工之什", "intro": "《振鹭》收于《诗经·周颂·臣工之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "振鹭于飞，于彼西雍。我客戾止，亦有斯容。在彼无恶，在此无斁。庶几夙夜，以永终誉。", "sentences": ["振鹭于飞，于彼西雍。", "我客戾止，亦有斯容。", "在彼无恶，在此无斁。", "庶几夙夜，以永终誉。"], "notes": "", "page": null}]}, {"id": "p279", "title": "丰年", "section": "颂", "group": "周颂 · 臣工之什", "intro": "《丰年》收于《诗经·周颂·臣工之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "丰年多黍多稌，亦有高廪，万亿及秭。为酒为醴，烝畀祖妣。以洽百礼，降福孔皆。", "sentences": ["丰年多黍多稌，亦有高廪，万亿及秭。", "为酒为醴，烝畀祖妣。", "以洽百礼，降福孔皆。"], "notes": "", "page": null}]}, {"id": "p280", "title": "有瞽", "section": "颂", "group": "周颂 · 臣工之什", "intro": "《有瞽》收于《诗经·周颂·臣工之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "有瞽有瞽，在周之庭。设业设虡，崇牙树羽。应田县鼓，鞉磬柷圉。既备", "sentences": ["有瞽有瞽，在周之庭。", "设业设虡，崇牙树羽。", "应田县鼓，鞉磬柷圉。", "既备"], "notes": "", "page": null}, {"text": "乃奏，箫管备举。喤喤厥声，肃雍和鸣，先祖是听。我客戾止，永观厥成。", "sentences": ["乃奏，箫管备举。", "喤喤厥声，肃雍和鸣，先祖是听。", "我客戾止，永观厥成。"], "notes": "", "page": null}]}, {"id": "p281", "title": "潜", "section": "颂", "group": "周颂 · 臣工之什", "intro": "《潜》收于《诗经·周颂·臣工之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "猗与漆沮，潜有多鱼。有鳣有鲔，鲦鲿鰋鲤。以享以祀，以介景福。", "sentences": ["猗与漆沮，潜有多鱼。", "有鳣有鲔，鲦鲿鰋鲤。", "以享以祀，以介景福。"], "notes": "", "page": null}]}, {"id": "p282", "title": "雝", "section": "颂", "group": "周颂 · 臣工之什", "intro": "《雝》收于《诗经·周颂·臣工之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "有来雝雝，至止肃肃。相维辟公，天子穆穆。于荐广牡，相予四祀。假哉皇考！绥予孝子。", "sentences": ["有来雝雝，至止肃肃。", "相维辟公，天子穆穆。", "于荐广牡，相予四祀。", "假哉皇考！", "绥予孝子。"], "notes": "", "page": null}, {"text": "宣哲维人，文武维后。燕及皇天，克昌厥后。绥我眉寿，介以繁祉，既右烈考，亦右文母。", "sentences": ["宣哲维人，文武维后。", "燕及皇天，克昌厥后。", "绥我眉寿，介以繁祉，既右烈考，亦右文母。"], "notes": "", "page": null}]}, {"id": "p283", "title": "载见", "section": "颂", "group": "周颂 · 臣工之什", "intro": "《载见》收于《诗经·周颂·臣工之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "载见辟王，曰求厥章。龙旂阳阳，和铃央央。鞗革有鸧，休有烈光。率见昭考，以孝以享。", "sentences": ["载见辟王，曰求厥章。", "龙旂阳阳，和铃央央。", "鞗革有鸧，休有烈光。", "率见昭考，以孝以享。"], "notes": "", "page": null}, {"text": "以介眉寿，永言保之，思皇多祜。烈文辟公，绥以多福，俾缉熙于纯嘏。", "sentences": ["以介眉寿，永言保之，思皇多祜。", "烈文辟公，绥以多福，俾缉熙于纯嘏。"], "notes": "", "page": null}]}, {"id": "p284", "title": "有客", "section": "颂", "group": "周颂 · 臣工之什", "intro": "《有客》收于《诗经·周颂·臣工之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "有客有客，亦白其马。有萋有且，敦琢其旅。有客宿宿，有客信信。", "sentences": ["有客有客，亦白其马。", "有萋有且，敦琢其旅。", "有客宿宿，有客信信。"], "notes": "", "page": null}, {"text": "言授之絷，以絷其马。薄言追之，左右绥之。既有淫威，降福孔夷。", "sentences": ["言授之絷，以絷其马。", "薄言追之，左右绥之。", "既有淫威，降福孔夷。"], "notes": "", "page": null}]}, {"id": "p285", "title": "武", "section": "颂", "group": "周颂 · 臣工之什", "intro": "《武》收于《诗经·周颂·臣工之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "于皇武王！无竞维烈。允文文王，克开厥后。嗣武受之，胜殷遏刘，耆定尔功。", "sentences": ["于皇武王！", "无竞维烈。", "允文文王，克开厥后。", "嗣武受之，胜殷遏刘，耆定尔功。"], "notes": "", "page": null}]}, {"id": "p286", "title": "闵予小子", "section": "颂", "group": "周颂 · 闵予小子之什", "intro": "《闵予小子》收于《诗经·周颂·闵予小子之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "闵予小子，遭家不造，嬛嬛在疚。于乎皇考，永世克孝。", "sentences": ["闵予小子，遭家不造，嬛嬛在疚。", "于乎皇考，永世克孝。"], "notes": "", "page": null}, {"text": "念兹皇祖，陟降庭止。维予小子，夙夜敬止。于乎皇王，继序思不忘。", "sentences": ["念兹皇祖，陟降庭止。", "维予小子，夙夜敬止。", "于乎皇王，继序思不忘。"], "notes": "", "page": null}]}, {"id": "p287", "title": "访落", "section": "颂", "group": "周颂 · 闵予小子之什", "intro": "《访落》收于《诗经·周颂·闵予小子之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "访予落止，率时昭考。于乎悠哉，朕未有艾。将予就之，继犹判涣。", "sentences": ["访予落止，率时昭考。", "于乎悠哉，朕未有艾。", "将予就之，继犹判涣。"], "notes": "", "page": null}, {"text": "维予小子，未堪家多难。绍庭上下，陟降厥家。休矣皇考，以保明其身。", "sentences": ["维予小子，未堪家多难。", "绍庭上下，陟降厥家。", "休矣皇考，以保明其身。"], "notes": "", "page": null}]}, {"id": "p288", "title": "敬之", "section": "颂", "group": "周颂 · 闵予小子之什", "intro": "《敬之》收于《诗经·周颂·闵予小子之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "敬之敬之，天维显思，命不易哉。无曰高高在上，陟降厥士，日监在兹。", "sentences": ["敬之敬之，天维显思，命不易哉。", "无曰高高在上，陟降厥士，日监在兹。"], "notes": "", "page": null}, {"text": "维予小子，不聪敬止。日就月将，学有缉熙于光明。佛时仔肩，示我显德行。", "sentences": ["维予小子，不聪敬止。", "日就月将，学有缉熙于光明。", "佛时仔肩，示我显德行。"], "notes": "", "page": null}]}, {"id": "p289", "title": "小毖", "section": "颂", "group": "周颂 · 闵予小子之什", "intro": "《小毖》收于《诗经·周颂·闵予小子之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "予其惩，而毖后患。莫予荓蜂，自求辛螫。肇允彼桃虫，拚飞维鸟。未堪家多难，予又集于蓼。", "sentences": ["予其惩，而毖后患。", "莫予荓蜂，自求辛螫。", "肇允彼桃虫，拚飞维鸟。", "未堪家多难，予又集于蓼。"], "notes": "", "page": null}]}, {"id": "p290", "title": "载芟", "section": "颂", "group": "周颂 · 闵予小子之什", "intro": "《载芟》收于《诗经·周颂·闵予小子之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "载芟载柞，其耕泽泽。千耦其耘，徂隰徂畛。侯主侯伯，侯亚侯旅，侯彊侯以。", "sentences": ["载芟载柞，其耕泽泽。", "千耦其耘，徂隰徂畛。", "侯主侯伯，侯亚侯旅，侯彊侯以。"], "notes": "", "page": null}, {"text": "有嗿其馌，思媚其妇，有依其士。有略其耜，俶载南亩，播厥百谷。实函斯活，驿驿其达。", "sentences": ["有嗿其馌，思媚其妇，有依其士。", "有略其耜，俶载南亩，播厥百谷。", "实函斯活，驿驿其达。"], "notes": "", "page": null}, {"text": "有厌其杰，厌厌其苗，绵绵其麃。载获济济，有实其积，万亿及秭。为酒为醴，烝畀祖妣，不洽百礼。", "sentences": ["有厌其杰，厌厌其苗，绵绵其麃。", "载获济济，有实其积，万亿及秭。", "为酒为醴，烝畀祖妣，不洽百礼。"], "notes": "", "page": null}, {"text": "有飶其香。邦家之光。有椒其馨，胡考之宁。匪且有且，匪今斯今，振古如兹。", "sentences": ["有飶其香。", "邦家之光。", "有椒其馨，胡考之宁。", "匪且有且，匪今斯今，振古如兹。"], "notes": "", "page": null}]}, {"id": "p291", "title": "良耜", "section": "颂", "group": "周颂 · 闵予小子之什", "intro": "《良耜》收于《诗经·周颂·闵予小子之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "畟畟良耜，俶载南亩。播厥百谷，实函斯活。或来瞻女，载筐及莒，其饟伊黍。", "sentences": ["畟畟良耜，俶载南亩。", "播厥百谷，实函斯活。", "或来瞻女，载筐及莒，其饟伊黍。"], "notes": "", "page": null}, {"text": "其笠伊纠，其镈斯赵，以薅荼蓼。荼蓼朽止，黍稷茂止。获之挃挃，积之栗栗。", "sentences": ["其笠伊纠，其镈斯赵，以薅荼蓼。", "荼蓼朽止，黍稷茂止。", "获之挃挃，积之栗栗。"], "notes": "", "page": null}, {"text": "其崇如墉，其比如栉。以开百室，百室盈止，妇子宁止。杀时犉牡，有捄其角。以似以续，续古之人。", "sentences": ["其崇如墉，其比如栉。", "以开百室，百室盈止，妇子宁止。", "杀时犉牡，有捄其角。", "以似以续，续古之人。"], "notes": "", "page": null}]}, {"id": "p292", "title": "丝衣", "section": "颂", "group": "周颂 · 闵予小子之什", "intro": "《丝衣》收于《诗经·周颂·闵予小子之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "丝衣其紑，载弁俅俅。自堂徂基，自羊徂牛，鼐鼎及鼒，兕觥其觩。旨酒思柔。不吴不敖，胡考之休。", "sentences": ["丝衣其紑，载弁俅俅。", "自堂徂基，自羊徂牛，鼐鼎及鼒，兕觥其觩。", "旨酒思柔。", "不吴不敖，胡考之休。"], "notes": "", "page": null}]}, {"id": "p293", "title": "酌", "section": "颂", "group": "周颂 · 闵予小子之什", "intro": "《酌》收于《诗经·周颂·闵予小子之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "于铄王师，遵养时晦。时纯熙矣，是用大介。我龙受之，蹻蹻王之造。载用有嗣，实维尔公允师。", "sentences": ["于铄王师，遵养时晦。", "时纯熙矣，是用大介。", "我龙受之，蹻蹻王之造。", "载用有嗣，实维尔公允师。"], "notes": "", "page": null}]}, {"id": "p294", "title": "桓", "section": "颂", "group": "周颂 · 闵予小子之什", "intro": "《桓》收于《诗经·周颂·闵予小子之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "绥万邦，屡丰年。天命匪解，桓桓武王。保有厥士，于以四方，克定厥家。于昭于天，皇以间之。", "sentences": ["绥万邦，屡丰年。", "天命匪解，桓桓武王。", "保有厥士，于以四方，克定厥家。", "于昭于天，皇以间之。"], "notes": "", "page": null}]}, {"id": "p295", "title": "赉", "section": "颂", "group": "周颂 · 闵予小子之什", "intro": "《赉》收于《诗经·周颂·闵予小子之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "文王既勤止，我应受之。敷时绎思，我徂维求定。时周之命，于绎思。", "sentences": ["文王既勤止，我应受之。", "敷时绎思，我徂维求定。", "时周之命，于绎思。"], "notes": "", "page": null}]}, {"id": "p296", "title": "般", "section": "颂", "group": "周颂 · 闵予小子之什", "intro": "《般》收于《诗经·周颂·闵予小子之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "于皇时周！陟其高山，嶞山乔岳，允犹翕河。敷天之下，裒时之对。时周之命。", "sentences": ["于皇时周！", "陟其高山，嶞山乔岳，允犹翕河。", "敷天之下，裒时之对。", "时周之命。"], "notes": "", "page": null}]}, {"id": "p297", "title": "駉", "section": "颂", "group": "鲁颂 · 駉之什", "intro": "《駉》收于《诗经·鲁颂·駉之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "駉駉牡马，在坰之野。薄言駉者，有驈有皇，有骊有黄，以车彭彭。思无疆思，马斯臧。", "sentences": ["駉駉牡马，在坰之野。", "薄言駉者，有驈有皇，有骊有黄，以车彭彭。", "思无疆思，马斯臧。"], "notes": "", "page": null}, {"text": "駉駉牡马，在坰之野。薄言駉者，有骓有駓，有骍有骐，以车伾伾。思无期思，马斯才。", "sentences": ["駉駉牡马，在坰之野。", "薄言駉者，有骓有駓，有骍有骐，以车伾伾。", "思无期思，马斯才。"], "notes": "", "page": null}, {"text": "駉駉牡马，在坰之野。溥言駉者，有驒有骆，有骝有雒，以车绎绎。思无斁思，马斯作。", "sentences": ["駉駉牡马，在坰之野。", "溥言駉者，有驒有骆，有骝有雒，以车绎绎。", "思无斁思，马斯作。"], "notes": "", "page": null}, {"text": "駉駉牡马，在坰之野。薄言駉者，有骃有騢，有驔有鱼，以车祛祛。思无邪思，马斯徂。", "sentences": ["駉駉牡马，在坰之野。", "薄言駉者，有骃有騢，有驔有鱼，以车祛祛。", "思无邪思，马斯徂。"], "notes": "", "page": null}]}, {"id": "p298", "title": "有駜", "section": "颂", "group": "鲁颂 · 駉之什", "intro": "《有駜》收于《诗经·鲁颂·駉之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "有駜有駜，駜彼乘黄。夙夜在公，在公明明。振振鹭，鹭于下。鼓咽咽，醉言舞。于胥乐兮！", "sentences": ["有駜有駜，駜彼乘黄。", "夙夜在公，在公明明。", "振振鹭，鹭于下。", "鼓咽咽，醉言舞。", "于胥乐兮！"], "notes": "", "page": null}, {"text": "有駜有駜，駜彼乘牡。夙夜在公，在公饮酒。振振鹭，鹭于飞。鼓咽咽，醉言归。于胥乐兮！", "sentences": ["有駜有駜，駜彼乘牡。", "夙夜在公，在公饮酒。", "振振鹭，鹭于飞。", "鼓咽咽，醉言归。", "于胥乐兮！"], "notes": "", "page": null}, {"text": "有駜有駜，駜彼乘駽。夙夜在公，在公载燕。自今以始，岁其有。君子有穀，诒孙子。于胥乐兮！", "sentences": ["有駜有駜，駜彼乘駽。", "夙夜在公，在公载燕。", "自今以始，岁其有。", "君子有穀，诒孙子。", "于胥乐兮！"], "notes": "", "page": null}]}, {"id": "p299", "title": "泮水", "section": "颂", "group": "鲁颂 · 駉之什", "intro": "《泮水》收于《诗经·鲁颂·駉之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "思乐泮水，薄采其芹。鲁侯戾止，言观其旂。其旂茷茷，鸾声哕哕。无小无大，从公于迈。", "sentences": ["思乐泮水，薄采其芹。", "鲁侯戾止，言观其旂。", "其旂茷茷，鸾声哕哕。", "无小无大，从公于迈。"], "notes": "", "page": null}, {"text": "思乐泮水，薄采其藻。鲁侯戾止，其马蹻蹻。其马蹻蹻，其音昭昭。载色载笑，匪怒伊教。", "sentences": ["思乐泮水，薄采其藻。", "鲁侯戾止，其马蹻蹻。", "其马蹻蹻，其音昭昭。", "载色载笑，匪怒伊教。"], "notes": "", "page": null}, {"text": "思乐泮水，薄采其茆。鲁侯戾止，在泮饮酒。既饮旨酒，永锡难老。顺彼长道，屈此群丑。", "sentences": ["思乐泮水，薄采其茆。", "鲁侯戾止，在泮饮酒。", "既饮旨酒，永锡难老。", "顺彼长道，屈此群丑。"], "notes": "", "page": null}, {"text": "穆穆鲁侯，敬明其德。敬慎威仪，维民之则。允文允武，昭假烈祖。靡有不孝，自求伊祜。", "sentences": ["穆穆鲁侯，敬明其德。", "敬慎威仪，维民之则。", "允文允武，昭假烈祖。", "靡有不孝，自求伊祜。"], "notes": "", "page": null}, {"text": "明明鲁侯，克明其德。既作泮宫，淮夷攸服。矫矫虎臣，在泮献馘。淑问如皋陶，在泮献囚。", "sentences": ["明明鲁侯，克明其德。", "既作泮宫，淮夷攸服。", "矫矫虎臣，在泮献馘。", "淑问如皋陶，在泮献囚。"], "notes": "", "page": null}, {"text": "济济多士，克广德心。桓桓于征，狄彼东南。烝烝皇皇，不吴不扬。不告于訩，在泮献功。", "sentences": ["济济多士，克广德心。", "桓桓于征，狄彼东南。", "烝烝皇皇，不吴不扬。", "不告于訩，在泮献功。"], "notes": "", "page": null}, {"text": "角弓其觩。束矢其搜。戎车孔博。徒御无斁。既克淮夷，孔淑不逆。式固尔犹，淮夷卒获。", "sentences": ["角弓其觩。", "束矢其搜。", "戎车孔博。", "徒御无斁。", "既克淮夷，孔淑不逆。", "式固尔犹，淮夷卒获。"], "notes": "", "page": null}, {"text": "翩彼飞鸮，集于泮林。食我桑黮，怀我好音。憬彼淮夷，来献其琛。元龟象齿，大赂南金。", "sentences": ["翩彼飞鸮，集于泮林。", "食我桑黮，怀我好音。", "憬彼淮夷，来献其琛。", "元龟象齿，大赂南金。"], "notes": "", "page": null}]}, {"id": "p300", "title": "閟宫", "section": "颂", "group": "鲁颂 · 駉之什", "intro": "《閟宫》收于《诗经·鲁颂·駉之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "閟宫有侐，实实枚枚。赫赫姜嫄，其德不回。上帝是依，无灾无害。", "sentences": ["閟宫有侐，实实枚枚。", "赫赫姜嫄，其德不回。", "上帝是依，无灾无害。"], "notes": "", "page": null}, {"text": "弥月不迟，是生后稷。降之百福。黍稷重穋，稙稚菽麦。奄有下国，俾民稼穑。", "sentences": ["弥月不迟，是生后稷。", "降之百福。", "黍稷重穋，稙稚菽麦。", "奄有下国，俾民稼穑。"], "notes": "", "page": null}, {"text": "有稷有黍，有稻有秬。奄有下土，缵禹之绪。后稷之孙，实维大王。", "sentences": ["有稷有黍，有稻有秬。", "奄有下土，缵禹之绪。", "后稷之孙，实维大王。"], "notes": "", "page": null}, {"text": "居岐之阳，实始剪商。至于文武，缵大王之绪，致天之届，于牧之野。", "sentences": ["居岐之阳，实始剪商。", "至于文武，缵大王之绪，致天之届，于牧之野。"], "notes": "", "page": null}, {"text": "无二无虞，上帝临女。敦商之旅，克咸厥功。王曰叔父，建尔元子，俾侯于鲁。", "sentences": ["无二无虞，上帝临女。", "敦商之旅，克咸厥功。", "王曰叔父，建尔元子，俾侯于鲁。"], "notes": "", "page": null}, {"text": "大启尔宇，为周室辅。乃命鲁公，俾侯于东。锡之山川，土田附庸。", "sentences": ["大启尔宇，为周室辅。", "乃命鲁公，俾侯于东。", "锡之山川，土田附庸。"], "notes": "", "page": null}, {"text": "周公之孙，庄公之子。龙旂承祀。六辔耳耳。春秋匪解，享祀不忒。", "sentences": ["周公之孙，庄公之子。", "龙旂承祀。", "六辔耳耳。", "春秋匪解，享祀不忒。"], "notes": "", "page": null}, {"text": "皇皇后帝！皇祖后稷！享以骍牺，是飨是宜。降福既多，周公皇祖，亦其福女。", "sentences": ["皇皇后帝！", "皇祖后稷！", "享以骍牺，是飨是宜。", "降福既多，周公皇祖，亦其福女。"], "notes": "", "page": null}, {"text": "秋而载尝，夏而楅衡，白牡骍刚。牺尊将将，毛炰胾羹。笾豆大房，万舞洋洋。", "sentences": ["秋而载尝，夏而楅衡，白牡骍刚。", "牺尊将将，毛炰胾羹。", "笾豆大房，万舞洋洋。"], "notes": "", "page": null}, {"text": "孝孙有庆。俾尔炽而昌，俾尔寿而臧。保彼东方，鲁邦是尝。不亏不崩，不震不腾。", "sentences": ["孝孙有庆。", "俾尔炽而昌，俾尔寿而臧。", "保彼东方，鲁邦是尝。", "不亏不崩，不震不腾。"], "notes": "", "page": null}, {"text": "三寿作朋，如冈如陵。公车千乘，朱英绿縢。二矛重弓。公徒三万，贝胄朱綅。", "sentences": ["三寿作朋，如冈如陵。", "公车千乘，朱英绿縢。", "二矛重弓。", "公徒三万，贝胄朱綅。"], "notes": "", "page": null}, {"text": "烝徒增增，戎狄是膺，荆舒是惩，则莫我敢承！俾尔昌而炽，俾尔寿而富。", "sentences": ["烝徒增增，戎狄是膺，荆舒是惩，则莫我敢承！", "俾尔昌而炽，俾尔寿而富。"], "notes": "", "page": null}, {"text": "黄发台背，寿胥与试。俾尔昌而大，俾尔耆而艾。万有千岁，眉寿无有害。", "sentences": ["黄发台背，寿胥与试。", "俾尔昌而大，俾尔耆而艾。", "万有千岁，眉寿无有害。"], "notes": "", "page": null}, {"text": "泰山岩岩，鲁邦所詹。奄有龟蒙，遂荒大东。至于海邦，淮夷来同。", "sentences": ["泰山岩岩，鲁邦所詹。", "奄有龟蒙，遂荒大东。", "至于海邦，淮夷来同。"], "notes": "", "page": null}, {"text": "莫不率从，鲁侯之功。保有凫绎，遂荒徐宅。至于海邦，淮夷蛮貊。", "sentences": ["莫不率从，鲁侯之功。", "保有凫绎，遂荒徐宅。", "至于海邦，淮夷蛮貊。"], "notes": "", "page": null}, {"text": "及彼南夷，莫不率从。莫敢不诺，鲁侯是若。天锡公纯嘏，眉寿保鲁。", "sentences": ["及彼南夷，莫不率从。", "莫敢不诺，鲁侯是若。", "天锡公纯嘏，眉寿保鲁。"], "notes": "", "page": null}, {"text": "居常与许，复周公之宇。鲁侯燕喜，令妻寿母。宜大夫庶士，邦国是有。", "sentences": ["居常与许，复周公之宇。", "鲁侯燕喜，令妻寿母。", "宜大夫庶士，邦国是有。"], "notes": "", "page": null}, {"text": "既多受祉，黄发儿齿。徂徠之松，新甫之柏。是断是度，是寻是尺。", "sentences": ["既多受祉，黄发儿齿。", "徂徠之松，新甫之柏。", "是断是度，是寻是尺。"], "notes": "", "page": null}, {"text": "松桷有舄，路寝孔硕，新庙奕奕。奚斯所作，孔曼且硕，万民是若。", "sentences": ["松桷有舄，路寝孔硕，新庙奕奕。", "奚斯所作，孔曼且硕，万民是若。"], "notes": "", "page": null}]}, {"id": "p301", "title": "那", "section": "颂", "group": "商颂 · 那之什", "intro": "《那》收于《诗经·商颂·那之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "猗与那与！置我鞉鼓。奏鼓简简，衎我烈祖。汤孙奏假，绥我思成。", "sentences": ["猗与那与！", "置我鞉鼓。", "奏鼓简简，衎我烈祖。", "汤孙奏假，绥我思成。"], "notes": "", "page": null}, {"text": "鞉鼓渊渊，嘒嘒管声。既和且平，依我磬声。于赫汤孙！穆穆厥声。", "sentences": ["鞉鼓渊渊，嘒嘒管声。", "既和且平，依我磬声。", "于赫汤孙！", "穆穆厥声。"], "notes": "", "page": null}, {"text": "庸鼓有斁，万舞有奕。我有嘉客，亦不夷怿。自古在昔，先民有作。", "sentences": ["庸鼓有斁，万舞有奕。", "我有嘉客，亦不夷怿。", "自古在昔，先民有作。"], "notes": "", "page": null}, {"text": "温恭朝夕，执事有恪，顾予烝尝，汤孙之将。", "sentences": ["温恭朝夕，执事有恪，顾予烝尝，汤孙之将。"], "notes": "", "page": null}]}, {"id": "p302", "title": "烈祖", "section": "颂", "group": "商颂 · 那之什", "intro": "《烈祖》收于《诗经·商颂·那之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "嗟嗟烈祖！有秩斯祜。申锡无疆，及尔斯所。既载清酤，赉我思成。", "sentences": ["嗟嗟烈祖！", "有秩斯祜。", "申锡无疆，及尔斯所。", "既载清酤，赉我思成。"], "notes": "", "page": null}, {"text": "亦有和羹，既戒既平。鬷假无言，时靡有争。绥我眉寿，黄耇无疆。", "sentences": ["亦有和羹，既戒既平。", "鬷假无言，时靡有争。", "绥我眉寿，黄耇无疆。"], "notes": "", "page": null}, {"text": "约軧错衡，八鸾鸧鸧。以假以享，我受命溥将。自天降康，丰年穰穰。", "sentences": ["约軧错衡，八鸾鸧鸧。", "以假以享，我受命溥将。", "自天降康，丰年穰穰。"], "notes": "", "page": null}, {"text": "来假来飨，降福无疆。顾予烝尝，汤孙之将。", "sentences": ["来假来飨，降福无疆。", "顾予烝尝，汤孙之将。"], "notes": "", "page": null}]}, {"id": "p303", "title": "玄鸟", "section": "颂", "group": "商颂 · 那之什", "intro": "《玄鸟》收于《诗经·商颂·那之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "天命玄鸟，降而生商，宅殷土芒芒。古帝命武汤，正域彼四方。", "sentences": ["天命玄鸟，降而生商，宅殷土芒芒。", "古帝命武汤，正域彼四方。"], "notes": "", "page": null}, {"text": "方命厥后，奄有九有。商之先后，受命不殆，在武丁孙子。武丁孙子，武王靡不胜。", "sentences": ["方命厥后，奄有九有。", "商之先后，受命不殆，在武丁孙子。", "武丁孙子，武王靡不胜。"], "notes": "", "page": null}, {"text": "龙旂十乘，大糦是承。邦畿千里，维民所止，肇域彼四海。", "sentences": ["龙旂十乘，大糦是承。", "邦畿千里，维民所止，肇域彼四海。"], "notes": "", "page": null}, {"text": "四海来假，来假祁祁。景员维河。殷受命咸宜，百禄是何。", "sentences": ["四海来假，来假祁祁。", "景员维河。", "殷受命咸宜，百禄是何。"], "notes": "", "page": null}]}, {"id": "p304", "title": "长发", "section": "颂", "group": "商颂 · 那之什", "intro": "《长发》收于《诗经·商颂·那之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "浚哲维商，长发其祥。洪水芒芒，禹敷下土方。外大国是疆，幅陨既长。有娀方将，帝立子生商。", "sentences": ["浚哲维商，长发其祥。", "洪水芒芒，禹敷下土方。", "外大国是疆，幅陨既长。", "有娀方将，帝立子生商。"], "notes": "", "page": null}, {"text": "玄王桓拨，受小国是达，受大国是达。率履不越，遂视既发。相士烈烈。海外有截。", "sentences": ["玄王桓拨，受小国是达，受大国是达。", "率履不越，遂视既发。", "相士烈烈。", "海外有截。"], "notes": "", "page": null}, {"text": "帝命不违，至于汤齐。汤降不迟，圣敬日跻。昭假迟迟，上帝是祗，帝命式于九围。", "sentences": ["帝命不违，至于汤齐。", "汤降不迟，圣敬日跻。", "昭假迟迟，上帝是祗，帝命式于九围。"], "notes": "", "page": null}, {"text": "受小球大球，为下国缀旒，何天之休。不竞不絿，不刚不柔。敷政优优。百禄是遒。", "sentences": ["受小球大球，为下国缀旒，何天之休。", "不竞不絿，不刚不柔。", "敷政优优。", "百禄是遒。"], "notes": "", "page": null}, {"text": "受小共大共，为下国骏厖。何天之龙，敷奏其勇。不震不动，不戁不竦，百禄是总。", "sentences": ["受小共大共，为下国骏厖。", "何天之龙，敷奏其勇。", "不震不动，不戁不竦，百禄是总。"], "notes": "", "page": null}, {"text": "武王载旆，有虔秉钺。如火烈烈，则莫我敢曷。苞有三蘖，莫遂莫达。九有有截，韦顾既伐，昆吾夏桀。", "sentences": ["武王载旆，有虔秉钺。", "如火烈烈，则莫我敢曷。", "苞有三蘖，莫遂莫达。", "九有有截，韦顾既伐，昆吾夏桀。"], "notes": "", "page": null}, {"text": "昔在中叶，有震且业。允也天子，降予卿士。实维阿衡，实左右商王。", "sentences": ["昔在中叶，有震且业。", "允也天子，降予卿士。", "实维阿衡，实左右商王。"], "notes": "", "page": null}]}, {"id": "p305", "title": "殷武", "section": "颂", "group": "商颂 · 那之什", "intro": "《殷武》收于《诗经·商颂·那之什》。公开版未收录现代题解。", "page": null, "stanzas": [{"text": "挞彼殷武，奋伐荆楚。深入其阻，裒荆之旅。有截其所，汤孙之绪。", "sentences": ["挞彼殷武，奋伐荆楚。", "深入其阻，裒荆之旅。", "有截其所，汤孙之绪。"], "notes": "", "page": null}, {"text": "维女荆楚，居国南乡。昔有成汤，自彼氐羌，莫敢不来享，莫敢不来王。曰商是常。", "sentences": ["维女荆楚，居国南乡。", "昔有成汤，自彼氐羌，莫敢不来享，莫敢不来王。", "曰商是常。"], "notes": "", "page": null}, {"text": "天命多辟，设都于禹之绩。岁事来辟，勿予祸适，稼穑匪解。", "sentences": ["天命多辟，设都于禹之绩。", "岁事来辟，勿予祸适，稼穑匪解。"], "notes": "", "page": null}, {"text": "天命降监，下民有严。不僭不滥，不敢怠遑。命于下国，封建厥福。", "sentences": ["天命降监，下民有严。", "不僭不滥，不敢怠遑。", "命于下国，封建厥福。"], "notes": "", "page": null}, {"text": "商邑翼翼，四方之极。赫赫厥声，濯濯厥灵。寿考且宁，以保我后生。", "sentences": ["商邑翼翼，四方之极。", "赫赫厥声，濯濯厥灵。", "寿考且宁，以保我后生。"], "notes": "", "page": null}, {"text": "陟彼景山，松伯丸丸。是断是迁，方斫是虔。松桷有梴，旅楹有闲，寝成孔安。", "sentences": ["陟彼景山，松伯丸丸。", "是断是迁，方斫是虔。", "松桷有梴，旅楹有闲，寝成孔安。"], "notes": "", "page": null}]}]};
